INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('0f4d19a0-1919-56fb-aae5-3119ffb0ca12', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 21, 21, 'The wise in heart shall be called prudent. Pleasantness of the lips promotes instruction.'),
  ('636ea6ba-6760-5080-a45a-8a531a0b14cb', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 22, 22, 'Understanding is a fountain of life to one who has it, but the punishment of fools is their folly.'),
  ('d51daad3-0e3c-566c-ac42-5eed7086f569', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 23, 23, 'The heart of the wise instructs his mouth, and adds learning to his lips.'),
  ('3dc5ab18-1dcb-5062-a5e9-bf26a340b664', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 24, 24, 'Pleasant words are a honeycomb, sweet to the soul, and health to the bones.'),
  ('79894075-2c0e-5a88-aab3-1d5d7236092c', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 25, 25, 'There is a way which seems right to a man, but in the end it leads to death.'),
  ('50570275-8b3d-58cb-a205-6dbf075cd8bb', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 26, 26, 'The appetite of the laboring man labors for him; for his mouth urges him on.'),
  ('47418f9f-7c92-5404-a85b-bd11ccf04b08', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 27, 27, 'A worthless man devises mischief. His speech is like a scorching fire.'),
  ('cad911be-bcc6-5dc3-a6d3-cf9d88cf1211', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 28, 28, 'A perverse man stirs up strife. A whisperer separates close friends.'),
  ('e893c20f-b831-5f95-a0fa-544ba781ee1d', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 29, 29, 'A man of violence entices his neighbor, and leads him in a way that is not good.'),
  ('8bb8357d-68f4-5cff-af9e-f5d9cbfa6f3d', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 30, 30, 'One who winks his eyes to plot perversities, one who compresses his lips, is bent on evil.'),
  ('3d488e96-d97a-54b2-aa3b-0ba50acb900c', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 31, 31, 'Gray hair is a crown of glory. It is attained by a life of righteousness.'),
  ('04be370c-3784-5bdc-a7ad-37be1e1981b8', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 32, 32, 'One who is slow to anger is better than the mighty; one who rules his spirit, than he who takes a city.'),
  ('a1055195-62e5-5b0f-a7a4-1a25aa1303ce', 'f4aef7c9-b117-5727-a99e-2264c16296a3', NULL, 33, 33, 'The lot is cast into the lap, but its every decision is from Yahweh.'),
  ('2fdbdcd4-b636-53fa-aac4-eced25012b4a', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 1, 1, 'Better is a dry morsel with quietness, than a house full of feasting with strife.'),
  ('2c495a36-e5dc-50f6-aafb-304fbc31a3b2', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 2, 2, 'A servant who deals wisely will rule over a son who causes shame, and shall have a part in the inheritance among the brothers.'),
  ('642be487-48d0-592a-a254-9fa1bf530872', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 3, 3, 'The refining pot is for silver, and the furnace for gold, but Yahweh tests the hearts.'),
  ('841bc307-b2b4-5461-a215-4e174647ee80', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 4, 4, 'An evildoer heeds wicked lips. A liar gives ear to a mischievous tongue.'),
  ('af3d908e-4978-5eb3-aab0-99addea8e0d2', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 5, 5, 'Whoever mocks the poor reproaches his Maker. He who is glad at calamity shall not be unpunished.'),
  ('ec8012c8-dfcb-5411-a925-1c14c0a633b1', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 6, 6, 'Children''s children are the crown of old men; the glory of children are their parents.'),
  ('0f98d330-4b56-5d9c-a6ba-ed559ab320a6', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 7, 7, 'Arrogant speech isn''t fitting for a fool, much less do lying lips fit a prince.'),
  ('bcccb0ce-a240-5328-ac4c-0d847b87f605', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 8, 8, 'A bribe is a precious stone in the eyes of him who gives it; wherever he turns, he prospers.'),
  ('b0f9362d-ebc8-54f7-aaab-2af7ee7da6bc', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 9, 9, 'He who covers an offense promotes love; but he who repeats a matter separates best friends.'),
  ('c5b63b0c-8dec-5690-a659-2be9ef7f26a2', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 10, 10, 'A rebuke enters deeper into one who has understanding than a hundred lashes into a fool.'),
  ('bdaa42c5-ac0b-5dbc-a2ff-e690d89be161', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 11, 11, 'An evil man seeks only rebellion; therefore a cruel messenger shall be sent against him.'),
  ('fbaffeb5-8c25-5c4e-a92e-32a381441179', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 12, 12, 'Let a bear robbed of her cubs meet a man, rather than a fool in his folly.'),
  ('807e1e9f-fa18-53d6-a919-77097d9a4130', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 13, 13, 'Whoever rewards evil for good, evil shall not depart from his house.'),
  ('98ab71f2-23d1-5478-a417-e4d76984ff7c', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 14, 14, 'The beginning of strife is like breaching a dam, therefore stop contention before quarreling breaks out.'),
  ('7bde0c05-f807-5904-a830-5bf621c6cd47', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 15, 15, 'He who justifies the wicked, and he who condemns the righteous, both of them alike are an abomination to Yahweh.'),
  ('1737b4fc-45d7-54c7-a409-dc08ebd30506', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 16, 16, 'Why is there money in the hand of a fool to buy wisdom, since he has no understanding?'),
  ('eead2d38-3fe7-5035-ac61-98c5bfbeb058', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 17, 17, 'A friend loves at all times; and a brother is born for adversity.'),
  ('49242217-f1ec-57fd-a898-7ad70f8877a9', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 18, 18, 'A man void of understanding strikes hands, and becomes collateral in the presence of his neighbor.'),
  ('062cd8f4-2f18-5d99-aaa0-72ba5bd596b7', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 19, 19, 'He who loves disobedience loves strife. One who builds a high gate seeks destruction.'),
  ('15bf7270-9e9a-5a16-ad2c-47c38a9acbac', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 20, 20, 'One who has a perverse heart doesn''t find prosperity, and one who has a deceitful tongue falls into trouble.'),
  ('0af5c9db-f4c3-56b9-a4a8-5c08a19d30af', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 21, 21, 'He who becomes the father of a fool grieves. The father of a fool has no joy.'),
  ('3f92e81e-e311-56ab-a730-83c8e1ea663a', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 22, 22, 'A cheerful heart makes good medicine, but a crushed spirit dries up the bones.'),
  ('2eac9e1f-70ce-5e72-a2cb-e2bff341af45', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 23, 23, 'A wicked man receives a bribe in secret, to pervert the ways of justice.'),
  ('c866d4f9-d0d1-5af4-a310-2c6f1ea3aed3', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 24, 24, 'Wisdom is before the face of one who has understanding, but the eyes of a fool wander to the ends of the earth.'),
  ('82d76ba8-f3a7-5332-aab7-fd88ee328b10', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 25, 25, 'A foolish son brings grief to his father, and bitterness to her who bore him.'),
  ('8036656f-c97a-55be-a718-56d13a655cbd', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 26, 26, 'Also to punish the righteous is not good, nor to flog officials for their integrity.'),
  ('61deacdf-c63d-5e1d-a53d-840da04d0eef', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 27, 27, 'He who spares his words has knowledge. He who is even tempered is a man of understanding.'),
  ('c5fce2aa-5757-5e12-ae18-7e045dd44b13', '41d45563-7539-5ec3-abfa-15036ddb1e90', NULL, 28, 28, 'Even a fool, when he keeps silent, is counted wise. When he shuts his lips, he is thought to be discerning.'),
  ('7e3a6352-b077-5ee3-ad26-b5746e25ff27', '60a2c553-53bf-5068-a9e6-bd42408dd774', NULL, 1, 1, 'An unfriendly man pursues selfishness, and defies all sound judgment.'),
  ('2addaf36-a6c9-5ff6-a3e5-bd498b0fe16d', '60a2c553-53bf-5068-a9e6-bd42408dd774', NULL, 2, 2, 'A fool has no delight in understanding, but only in revealing his own opinion.'),
  ('9f2305a6-34db-5196-a0b4-9df569989188', '60a2c553-53bf-5068-a9e6-bd42408dd774', NULL, 3, 3, 'When wickedness comes, contempt also comes, and with shame comes disgrace.'),
  ('584392da-f472-5cae-ab61-2dfb999bab4d', '60a2c553-53bf-5068-a9e6-bd42408dd774', NULL, 4, 4, 'The words of a man''s mouth are like deep waters. The fountain of wisdom is like a flowing brook.'),
  ('1961dcb2-a8c7-5813-adb5-2a5a22331cfa', '60a2c553-53bf-5068-a9e6-bd42408dd774', NULL, 5, 5, 'To be partial to the faces of the wicked is not good, nor to deprive the innocent of justice.'),
  ('48e53ea7-9330-5690-a3fb-6359570246b9', '60a2c553-53bf-5068-a9e6-bd42408dd774', NULL, 6, 6, 'A fool''s lips come into strife, and his mouth invites beatings.'),
  ('206c82f3-8c53-5928-ac80-6f5d1ee9ec60', '60a2c553-53bf-5068-a9e6-bd42408dd774', NULL, 7, 7, 'A fool''s mouth is his destruction, and his lips are a snare to his soul.'),
  ('f177b4e9-3c47-5f2c-a503-8d29bd8444de', '60a2c553-53bf-5068-a9e6-bd42408dd774', NULL, 8, 8, 'The words of a gossip are like dainty morsels: they go down into a person''s innermost parts.'),
  ('865c3c16-aee9-5679-af74-4423ab21799c', '60a2c553-53bf-5068-a9e6-bd42408dd774', NULL, 9, 9, 'One who is slack in his work is brother to him who is a master of destruction.'),
  ('27c7e422-4575-52c2-a56e-a506bbf10367', '60a2c553-53bf-5068-a9e6-bd42408dd774', NULL, 10, 10, 'The name of Yahweh is a strong tower: the righteous run to him, and are safe.'),
  ('56d0ec21-f381-5a0e-ab98-3e386a2b9351', '60a2c553-53bf-5068-a9e6-bd42408dd774', NULL, 11, 11, 'The rich man''s wealth is his strong city, like an unscalable wall in his own imagination.'),
  ('5ec58917-11c9-53d2-a681-fe5e8e088ac3', '60a2c553-53bf-5068-a9e6-bd42408dd774', NULL, 12, 12, 'Before destruction the heart of man is proud, but before honor is humility.'),
  ('7e6307bf-d8e4-5c28-a1b3-3a04ceb2a79c', '60a2c553-53bf-5068-a9e6-bd42408dd774', NULL, 13, 13, 'He who gives answer before he hears, that is folly and shame to him.'),
  ('cc28a501-d98a-5e22-a7fc-f2ca520fa9df', '60a2c553-53bf-5068-a9e6-bd42408dd774', NULL, 14, 14, 'A man''s spirit will sustain him in sickness, but a crushed spirit, who can bear?'),
  ('9f0c8cc1-23d3-5be7-a3ac-2a585d1b8833', '60a2c553-53bf-5068-a9e6-bd42408dd774', NULL, 15, 15, 'The heart of the discerning gets knowledge. The ear of the wise seeks knowledge.'),
  ('8ea5ff11-91f3-5959-ac63-115d955f9e81', '60a2c553-53bf-5068-a9e6-bd42408dd774', NULL, 16, 16, 'A man''s gift makes room for him, and brings him before great men.'),
  ('0718aa21-0c5e-5edb-a380-38e0d78d92ee', '60a2c553-53bf-5068-a9e6-bd42408dd774', NULL, 17, 17, 'He who pleads his cause first seems right; until another comes and questions him.'),
  ('7ad8e2ed-a013-58dd-a76a-8daa5025c3a8', '60a2c553-53bf-5068-a9e6-bd42408dd774', NULL, 18, 18, 'The lot settles disputes, and keeps strong ones apart.'),
  ('1aadc811-39cf-5a5f-ae89-4930d9de3947', '60a2c553-53bf-5068-a9e6-bd42408dd774', NULL, 19, 19, 'A brother offended is more difficult than a fortified city; and disputes are like the bars of a castle.'),
  ('7aecec16-f0ce-591f-a112-6b05a295a2bb', '60a2c553-53bf-5068-a9e6-bd42408dd774', NULL, 20, 20, 'A man''s stomach is filled with the fruit of his mouth. With the harvest of his lips he is satisfied.'),
  ('4978cb0f-90d1-51fa-a475-58044b3504c8', '60a2c553-53bf-5068-a9e6-bd42408dd774', NULL, 21, 21, 'Death and life are in the power of the tongue; those who love it will eat its fruit.'),
  ('08408062-89f8-520d-a323-ba9c35078424', '60a2c553-53bf-5068-a9e6-bd42408dd774', NULL, 22, 22, 'Whoever finds a wife finds a good thing, and obtains favor of Yahweh.'),
  ('c01f7fd7-97c9-59ba-ac26-3213194f40a5', '60a2c553-53bf-5068-a9e6-bd42408dd774', NULL, 23, 23, 'The poor plead for mercy, but the rich answer harshly.'),
  ('792a565e-051e-5598-a59a-e518dfa87ad9', '60a2c553-53bf-5068-a9e6-bd42408dd774', NULL, 24, 24, 'A man of many companions may be ruined, but there is a friend who sticks closer than a brother.'),
  ('461a4cfc-9edc-58d7-adb0-b9b27a17926c', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 1, 1, 'Better is the poor who walks in his integrity than he who is perverse in his lips and is a fool.'),
  ('0f8348c4-c4d6-5507-a701-6286c311714c', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 2, 2, 'It isn''t good to have zeal without knowledge; nor being hasty with one''s feet and missing the way.'),
  ('d0d95a57-c82d-5656-ad5d-a09d0bb36c06', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 3, 3, 'The foolishness of man subverts his way; his heart rages against Yahweh.'),
  ('89158233-336e-5119-aefa-b656267b07b6', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 4, 4, 'Wealth adds many friends, but the poor is separated from his friend.'),
  ('f843aab0-386e-5298-a7bb-ca374952ad0a', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 5, 5, 'A false witness shall not be unpunished. He who pours out lies shall not go free.'),
  ('0c1e7823-7826-5f23-a1b6-02358f52e813', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 6, 6, 'Many will entreat the favor of a ruler, and everyone is a friend to a man who gives gifts.'),
  ('9a7c9ca1-edeb-5b6a-a089-f95979ad38b8', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 7, 7, 'All the relatives of the poor shun him: how much more do his friends avoid him! He pursues them with pleas, but they are gone.'),
  ('44ceaaaf-e308-56f0-ab2b-cd65c175ace4', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 8, 8, 'He who gets wisdom loves his own soul. He who keeps understanding shall find good.'),
  ('89ca6ad8-2048-54ee-abdb-1419b6d8de44', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 9, 9, 'A false witness shall not be unpunished. He who utters lies shall perish.'),
  ('53e042b2-ea47-56f2-ab22-ac36055e18d8', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 10, 10, 'Delicate living is not appropriate for a fool, much less for a servant to have rule over princes.'),
  ('48d985b6-509b-5b55-af91-d4737075d7cc', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 11, 11, 'The discretion of a man makes him slow to anger. It is his glory to overlook an offense.'),
  ('c1adba86-0bef-519d-a023-ba2ba9d2a57b', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 12, 12, 'The king''s wrath is like the roaring of a lion, but his favor is like dew on the grass.'),
  ('3c6b50a4-bb83-5c9b-a507-b06d1d7de5ba', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 13, 13, 'A foolish son is the calamity of his father. A wife''s quarrels are a continual dripping.'),
  ('7362d790-fa16-53c0-a75e-51e27c4a0e94', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 14, 14, 'House and riches are an inheritance from fathers, but a prudent wife is from Yahweh.'),
  ('ead7d6f5-3278-55dd-a40b-c2ae4f43d13b', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 15, 15, 'Slothfulness casts into a deep sleep. The idle soul shall suffer hunger.'),
  ('c9449c82-4f5e-550b-a42b-92d5f001d8f7', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 16, 16, 'He who keeps the commandment keeps his soul, but he who is contemptuous in his ways shall die.'),
  ('8b3da154-8766-5a8a-a95c-92a7b012e4d9', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 17, 17, 'He who has pity on the poor lends to Yahweh; he will reward him.'),
  ('01987cb7-b5cd-5035-a8ed-5f4cc1e174a5', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 18, 18, 'Discipline your son, for there is hope; don''t be a willing party to his death.'),
  ('f2741378-e0d9-524e-ae4f-c571a83a6a0e', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 19, 19, 'A hot-tempered man must pay the penalty, for if you rescue him, you must do it again.'),
  ('4c31f9d1-210f-54c1-ae9c-4106878c8e70', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 20, 20, 'Listen to counsel and receive instruction, that you may be wise in your latter end.'),
  ('52504815-ee16-55bd-aeb5-d99a1e8c2919', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 21, 21, 'There are many plans in a man''s heart, but Yahweh''s counsel will prevail.'),
  ('cac01e10-5c58-5635-a6ee-9fb67271a874', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 22, 22, 'That which makes a man to be desired is his kindness. A poor man is better than a liar.'),
  ('9e91bf36-c36a-5437-a1ef-5c1c23a5541c', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 23, 23, 'The fear of Yahweh leads to life, then contentment; he rests and will not be touched by trouble.'),
  ('1e1d3dc5-dc6a-5696-ada7-e1ab884b953c', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 24, 24, 'The sluggard buries his hand in the dish; he will not so much as bring it to his mouth again.'),
  ('15622471-1694-5ac0-ac76-26df0d73883d', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 25, 25, 'Flog a scoffer, and the simple will learn prudence; rebuke one who has understanding, and he will gain knowledge.'),
  ('742f2cef-6149-5efb-a1b4-5b74553b4436', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 26, 26, 'He who robs his father and drives away his mother, is a son who causes shame and brings reproach.'),
  ('8bc8921f-12d1-5133-a214-686bacf15b90', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 27, 27, 'If you stop listening to instruction, my son, you will stray from the words of knowledge.'),
  ('88760313-6999-5835-adf1-dd385ba144d9', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 28, 28, 'A corrupt witness mocks justice, and the mouth of the wicked gulps down iniquity.'),
  ('778a1bb4-07f5-5e46-a1b9-dc46b24a1af2', '32f311b6-397a-5709-a9c1-c18303c289ee', NULL, 29, 29, 'Penalties are prepared for scoffers, and beatings for the backs of fools.'),
  ('3630b2e9-893f-5010-a270-c467c019a61f', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 1, 1, 'Wine is a mocker, and beer is a brawler. Whoever is led astray by them is not wise.'),
  ('222ead96-152f-5402-a1c7-1fa3e7dc07fb', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 2, 2, 'The terror of a king is like the roaring of a lion. He who provokes him to anger forfeits his own life.'),
  ('5ba7dbf5-fbc5-55d4-a69c-e6b2d2aefa1e', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 3, 3, 'It is an honor for a man to keep aloof from strife; but every fool will be quarreling.'),
  ('7ca4b038-3c43-53a1-ac4e-a49f5b4dbd3b', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 4, 4, 'The sluggard will not plow by reason of the winter; therefore he shall beg in harvest, and have nothing.'),
  ('47eefe5d-6cf5-5ec2-ad3b-6c51524a7f34', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 5, 5, 'Counsel in the heart of man is like deep water; but a man of understanding will draw it out.'),
  ('841de5ae-ecc0-5a50-a6db-08e2fe27f0ce', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 6, 6, 'Many men claim to be men of unfailing love, but who can find a faithful man?'),
  ('2efda1cc-8393-5f24-a221-6582ee748243', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 7, 7, 'A righteous man walks in integrity. Blessed are his children after him.'),
  ('e3f5e679-7fc9-56c9-a063-a4721dbd075f', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 8, 8, 'A king who sits on the throne of judgment scatters away all evil with his eyes.'),
  ('9887885c-4f67-5021-accf-36f3d2e29947', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 9, 9, 'Who can say, "I have made my heart pure. I am clean and without sin?"'),
  ('2706ce08-4b63-5f40-ad57-624dc4521eb1', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 10, 10, 'Differing weights and differing measures, both of them alike are an abomination to Yahweh.'),
  ('53aff629-9410-5d13-a654-00fcef1c1e68', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 11, 11, 'Even a child makes himself known by his doings, whether his work is pure, and whether it is right.'),
  ('b1c523c2-87ad-5826-a5a3-92a73e688381', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 12, 12, 'The hearing ear, and the seeing eye, Yahweh has made even both of them.'),
  ('2fcce03f-825f-590d-ac00-f30515c9e45a', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 13, 13, 'Don''t love sleep, lest you come to poverty. Open your eyes, and you shall be satisfied with bread.'),
  ('f24ff468-2857-5553-ada1-08215f433e0e', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 14, 14, '"It''s no good, it''s no good," says the buyer; but when he is gone his way, then he boasts.'),
  ('d22956f0-5801-5ec5-ab14-60e9c8a76f40', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 15, 15, 'There is gold and abundance of rubies; but the lips of knowledge are a rare jewel.'),
  ('f8435b08-fe07-5672-a79f-5b0bf89fb2d6', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 16, 16, 'Take the garment of one who puts up collateral for a stranger; and hold him in pledge for a wayward woman.'),
  ('a68c0eaa-d9b6-575e-a453-6314486b8d44', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 17, 17, 'Fraudulent food is sweet to a man, but afterwards his mouth is filled with gravel.'),
  ('6bf7a035-f861-578c-a9db-7bc14c1c7694', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 18, 18, 'Plans are established by advice; by wise guidance you wage war!'),
  ('cfc87871-6ee4-5731-a584-31e59d0e357b', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 19, 19, 'He who goes about as a tale-bearer reveals secrets; therefore don''t keep company with him who opens wide his lips.'),
  ('55590024-8b41-5d36-a2e0-613ff3c7188f', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 20, 20, 'Whoever curses his father or his mother, his lamp shall be put out in blackness of darkness.'),
  ('48ccd359-52db-5ec6-af9e-308de7ce1329', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 21, 21, 'An inheritance quickly gained at the beginning, won''t be blessed in the end.'),
  ('64cc980a-26b0-53fc-a203-6f700db579df', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 22, 22, 'Don''t say, "I will pay back evil." Wait for Yahweh, and he will save you.'),
  ('66528a61-45c8-54d6-a809-40e69f087e4e', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 23, 23, 'Yahweh detests differing weights, and dishonest scales are not pleasing.'),
  ('7e74297e-686a-53bc-ad1d-bc5be8a77851', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 24, 24, 'A man''s steps are from Yahweh; how then can man understand his way?'),
  ('c9aef35e-a23b-505c-af70-13ee21e8b015', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 25, 25, 'It is a snare to a man to make a rash dedication, then later to consider his vows.'),
  ('1777749a-83c7-502c-ae1e-06e5b73ba847', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 26, 26, 'A wise king winnows out the wicked, and drives the threshing wheel over them.'),
  ('2728d082-955c-5993-a805-4b5ca864ea1c', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 27, 27, 'The spirit of man is Yahweh''s lamp, searching all his innermost parts.'),
  ('72d31619-496f-5b15-a85b-8d68cfd28a44', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 28, 28, 'Love and faithfulness keep the king safe. His throne is sustained by love.'),
  ('492ee4de-f0d8-5926-ab85-f67f8d672446', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 29, 29, 'The glory of young men is their strength. The splendor of old men is their gray hair.'),
  ('3e8bb293-f685-59a8-aa76-c6f991f8bf64', '217f0ef9-0a52-5542-abe6-957ba3d10002', NULL, 30, 30, 'Wounding blows cleanse away evil, and beatings purge the innermost parts.'),
  ('16bc35eb-e63e-5770-a6ad-8601a1fc7b43', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 1, 1, 'The king''s heart is in Yahweh''s hand like the watercourses. He turns it wherever he desires.'),
  ('587b29fa-b42c-5b12-a16f-8e3634e3a978', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 2, 2, 'Every way of a man is right in his own eyes, but Yahweh weighs the hearts.'),
  ('cd7b21bc-a93d-5f04-a542-add79fc1d4a3', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 3, 3, 'To do righteousness and justice is more acceptable to Yahweh than sacrifice.'),
  ('55dd19c9-cd35-5fce-a90a-d436572c7d62', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 4, 4, 'A high look, and a proud heart, the lamp of the wicked, is sin.'),
  ('ac00afc3-355f-598f-a29e-bec1a661f0eb', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 5, 5, 'The plans of the diligent surely lead to profit; and everyone who is hasty surely rushes to poverty.'),
  ('6097bf32-f6f7-5f1c-a981-7fda209804fe', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 6, 6, 'Getting treasures by a lying tongue is a fleeting vapor for those who seek death.'),
  ('a117fb9d-f305-5139-a283-2b781210e68e', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 7, 7, 'The violence of the wicked will drive them away, because they refuse to do what is right.'),
  ('b453ef7a-53ad-513a-a53c-b19c506bdf37', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 8, 8, 'The way of the guilty is devious, but the conduct of the innocent is upright.'),
  ('336c47cf-72f0-5041-adfb-56a49c54a098', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 9, 9, 'It is better to dwell in the corner of the housetop, than to share a house with a contentious woman.'),
  ('01b1c5ce-0e5a-5cd6-accd-496eb501120c', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 10, 10, 'The soul of the wicked desires evil; his neighbor finds no mercy in his eyes.'),
  ('62112a70-820c-5b15-a842-1bfe359a6e20', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 11, 11, 'When the mocker is punished, the simple gains wisdom. When the wise is instructed, he receives knowledge.'),
  ('6bc3225b-591c-5c03-a16b-ea847e709e47', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 12, 12, 'The Righteous One considers the house of the wicked, and brings the wicked to ruin.'),
  ('ed11cb3c-bba8-521d-a7a9-c5c8356d6ab8', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 13, 13, 'Whoever stops his ears at the cry of the poor, he will also cry out, but shall not be heard.'),
  ('be2f5913-8ef2-5765-aacd-4c25d7f3333d', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 14, 14, 'A gift in secret pacifies anger; and a bribe in the cloak, strong wrath.'),
  ('f2333c52-e556-5979-af40-55f88f4dd0cf', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 15, 15, 'It is joy to the righteous to do justice; but it is a destruction to the workers of iniquity.'),
  ('b1d59dc7-4611-5287-aacb-f1cdd14cb568', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 16, 16, 'The man who wanders out of the way of understanding shall rest in the assembly of the dead.'),
  ('eb67d5e3-4222-5cf7-a9c3-6caf85653ad0', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 17, 17, 'He who loves pleasure shall be a poor man. He who loves wine and oil shall not be rich.'),
  ('5371d8b9-c56f-5796-abf4-3fc5279030b6', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 18, 18, 'The wicked is a ransom for the righteous; the treacherous for the upright.'),
  ('d5099921-0ecc-56c8-a116-5e6fc3852d43', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 19, 19, 'It is better to dwell in a desert land, than with a contentious and fretful woman.'),
  ('df1dc9e5-36f7-5df9-a037-a7c1a0a875db', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 20, 20, 'There is precious treasure and oil in the dwelling of the wise; but a foolish man swallows it up.'),
  ('333bd602-9a1c-5d25-ae22-66881135c166', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 21, 21, 'He who follows after righteousness and kindness finds life, righteousness, and honor.'),
  ('403a00f7-1337-50de-a78e-922828f0c162', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 22, 22, 'A wise man scales the city of the mighty, and brings down the strength of its confidence.'),
  ('87159ace-2657-5494-abfe-548ad792f65d', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 23, 23, 'Whoever guards his mouth and his tongue keeps his soul from troubles.'),
  ('e6abd824-3fe5-509b-a6a0-2711ffbc573e', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 24, 24, 'The proud and haughty man, "scoffer" is his name; he works in the arrogance of pride.'),
  ('6b6d5753-ee36-5eca-a910-b349625274f9', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 25, 25, 'The desire of the sluggard kills him, for his hands refuse to labor.'),
  ('b5f52489-16c8-5d42-a701-3ea146ad4784', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 26, 26, 'There are those who covet greedily all day long; but the righteous give and don''t withhold.'),
  ('515f3952-7256-5ebf-a865-510dc9ae1d23', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 27, 27, 'The sacrifice of the wicked is an abomination: how much more, when he brings it with a wicked mind!'),
  ('acf6d4e2-6841-5267-a262-58f62af517cb', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 28, 28, 'A false witness will perish, and a man who listens speaks to eternity.'),
  ('d6bdd5bf-4ca3-51a2-a6de-e1c34d65e39e', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 29, 29, 'A wicked man hardens his face; but as for the upright, he establishes his ways.'),
  ('8dbb373f-9e79-5da0-a43d-a61ce3d2afff', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 30, 30, 'There is no wisdom nor understanding nor counsel against Yahweh.'),
  ('5708d8df-94d3-5b67-ab34-a075220b02b7', 'd21c7f4e-04ea-55df-aa18-9be022694c4a', NULL, 31, 31, 'The horse is prepared for the day of battle; but victory is with Yahweh.'),
  ('3b7c4b1d-9924-5330-a59a-09a727ec669f', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 1, 1, 'A good name is more desirable than great riches, and loving favor is better than silver and gold.'),
  ('e9ffe2b7-c9a8-59cd-a560-55f536e5d96d', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 2, 2, 'The rich and the poor have this in common: Yahweh is the maker of them all.'),
  ('e40d342f-cdb5-5578-a761-77e8882ab75b', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 3, 3, 'A prudent man sees danger, and hides himself; but the simple pass on, and suffer for it.'),
  ('28bef268-5f09-50d6-ad3e-c2e2b42fe682', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 4, 4, 'The result of humility and the fear of Yahweh is wealth, honor, and life.'),
  ('a863bb2c-e715-5735-a5d8-f5ffde809e9e', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 5, 5, 'Thorns and snares are in the path of the wicked: whoever guards his soul stays from them.'),
  ('5d9c5a65-dc0f-5c37-acc1-288bb595c00e', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 6, 6, 'Train up a child in the way he should go, and when he is old he will not depart from it.'),
  ('46ef5489-e241-5c6b-a100-9b2e4bcecf98', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 7, 7, 'The rich rule over the poor. The borrower is servant to the lender.'),
  ('b4737f2c-efa5-5016-abad-9b11d6a7e835', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 8, 8, 'He who sows wickedness reaps trouble, and the rod of his fury will be destroyed.'),
  ('e64c60cd-d062-525a-a19e-ead17e2017b6', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 9, 9, 'He who has a generous eye will be blessed; for he shares his food with the poor.'),
  ('7e290508-916b-5ca5-adff-b68c2dc9f571', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 10, 10, 'Drive out the mocker, and strife will go out; yes, quarrels and insults will stop.'),
  ('467f4c8e-eda1-51cd-a4de-61191821d1b1', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 11, 11, 'He who loves purity of heart and speaks gracefully is the king''s friend.'),
  ('a9abdbf4-4280-5764-a57f-86858aa896e3', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 12, 12, 'The eyes of Yahweh watch over knowledge; but he frustrates the words of the unfaithful.'),
  ('bf067a4d-1426-5844-a529-0066bfc47852', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 13, 13, 'The sluggard says, "There is a lion outside! I will be killed in the streets!"'),
  ('1e968fbd-a609-5836-a953-dc9aeb01eb06', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 14, 14, 'The mouth of an adulteress is a deep pit: he who is under Yahweh''s wrath will fall into it.'),
  ('dcb0b882-17f6-5e47-a03e-edfb6d2672dd', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 15, 15, 'Folly is bound up in the heart of a child: the rod of discipline drives it far from him.'),
  ('1a19deb5-fc62-5c29-a5f8-ce3e79e33a32', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 16, 16, 'Whoever oppresses the poor for his own increase and whoever gives to the rich, both come to poverty.'),
  ('787ce354-c96a-5803-a053-b0d3d68d82a9', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 17, 17, 'Turn your ear, and listen to the words of the wise. Apply your heart to my teaching.'),
  ('a0d9d57a-c6ad-5abd-ad05-4ee56c709694', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 18, 18, 'For it is a pleasant thing if you keep them within you, if all of them are ready on your lips.'),
  ('e0580b7b-063d-5c50-adea-d5bfba68b619', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 19, 19, 'That your trust may be in Yahweh, I teach you today, even you.'),
  ('d7bac12d-f769-5a92-aa78-154f46575559', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 20, 20, 'Haven''t I written to you thirty excellent things of counsel and knowledge,'),
  ('16135c12-80df-5acc-a8b2-2667868e3366', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 21, 21, 'To teach you truth, reliable words, to give sound answers to the ones who sent you?'),
  ('ab56d279-aa97-50b6-a1de-134cb9d6bdf5', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 22, 22, 'Don''t exploit the poor, because he is poor; and don''t crush the needy in court;'),
  ('f8102f83-b72c-57ef-aeda-ea64b0cd4e2f', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 23, 23, 'for Yahweh will plead their case, and plunder the life of those who plunder them.'),
  ('145d2557-afdc-5604-a13e-97b5f18f5836', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 24, 24, 'Don''t befriend a hot-tempered man, and don''t associate with one who harbors anger:'),
  ('81b72643-d114-5b5e-a18d-6c82ee41bf19', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 25, 25, 'lest you learn his ways, and ensnare your soul.'),
  ('59157d99-4419-5b4b-ac14-cf7032653da7', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 26, 26, 'Don''t you be one of those who strike hands, of those who are collateral for debts.'),
  ('7c4f4599-f1b7-556d-a7ad-ffbde8ecbc31', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 27, 27, 'If you don''t have means to pay, why should he take away your bed from under you?'),
  ('2b2f991f-9d4d-54d5-acf0-39dfdb38dcbb', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 28, 28, 'Don''t move the ancient boundary stone, which your fathers have set up.'),
  ('0011ba5d-c5c6-5dd4-a34a-d415288d7100', '20d1bd05-1b2c-54cd-ab81-5c749034765a', NULL, 29, 29, 'Do you see a man skilled in his work? He will serve kings. He won''t serve obscure men.'),
  ('d9159f6c-2887-5408-aaa9-99c6932111d4', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 1, 1, 'When you sit to eat with a ruler, consider diligently what is before you;'),
  ('f3a1b8f0-a1dd-59ba-a840-b9ed71adea82', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 2, 2, 'put a knife to your throat, if you are a man given to appetite.'),
  ('bb4294fa-be9c-5c74-a0d2-9312dd59c127', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 3, 3, 'Don''t be desirous of his dainties, since they are deceitful food.'),
  ('997996c0-7fcb-59d7-a553-2bad3c4b55a0', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 4, 4, 'Don''t weary yourself to be rich. In your wisdom, show restraint.'),
  ('1b9acccd-4c56-54d8-a6a5-052272735d8d', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 5, 5, 'Why do you set your eyes on that which is not? For it certainly sprouts wings like an eagle and flies in the sky.'),
  ('47276128-6091-5187-a642-b48f07e0fbc6', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 6, 6, 'Don''t eat the food of him who has a stingy eye, and don''t crave his delicacies:'),
  ('cf2b23cf-5f75-59d7-a69a-8d318347e38d', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 7, 7, 'for as he thinks about the cost, so he is. "Eat and drink!" he says to you, but his heart is not with you.'),
  ('2e46ab37-293e-57ef-a510-c41a084c21e4', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 8, 8, 'The morsel which you have eaten you shall vomit up, and lose your good words.'),
  ('81ca075c-0ca3-5a8b-afca-89a9af42c57e', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 9, 9, 'Don''t speak in the ears of a fool, for he will despise the wisdom of your words.'),
  ('640b0cb2-ce82-54ca-acb4-0aac4e51b595', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 10, 10, 'Don''t move the ancient boundary stone. Don''t encroach on the fields of the fatherless:'),
  ('5df8a4a2-9425-5bf1-a1c2-b51de603034b', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 11, 11, 'for their Defender is strong. He will plead their case against you.'),
  ('c610ccb1-edf1-5dd6-af33-6085c0dd10ef', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 12, 12, 'Apply your heart to instruction, and your ears to the words of knowledge.'),
  ('65ba0003-604d-59f7-afa9-7f895578e392', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 13, 13, 'Don''t withhold correction from a child. If you punish him with the rod, he will not die.'),
  ('90a775b5-95ea-52b7-a3fb-71987124baa0', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 14, 14, 'Punish him with the rod, and save his soul from Sheol.'),
  ('0161b59e-ecf1-5e42-a3ea-fbcc9431f4d0', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 15, 15, 'My son, if your heart is wise, then my heart will be glad, even mine:'),
  ('0b6e4015-773b-5c83-ac64-f4555108801a', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 16, 16, 'yes, my heart will rejoice, when your lips speak what is right.'),
  ('e32ab5b7-81eb-57f3-a437-9b886385a04e', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 17, 17, 'Don''t let your heart envy sinners; but rather fear Yahweh all the day long.'),
  ('6efff1d3-f009-5cf5-a400-2d08c4b02a90', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 18, 18, 'Indeed surely there is a future hope, and your hope will not be cut off.'),
  ('c2ab66d8-0e16-5a83-a594-890dad960311', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 19, 19, 'Listen, my son, and be wise, and keep your heart on the right path!'),
  ('54f7bcf8-715b-537d-a511-b9eebdf973a3', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 20, 20, 'Don''t be among ones drinking too much wine, or those who gorge themselves on meat:'),
  ('93280f80-73fe-5525-aafd-4fd6d6d08431', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 21, 21, 'for the drunkard and the glutton shall become poor; and drowsiness clothes them in rags.'),
  ('c769cecd-6ba7-59b5-a926-5da0e37060e5', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 22, 22, 'Listen to your father who gave you life, and don''t despise your mother when she is old.'),
  ('90e2dee1-d8b8-5db1-a7fa-cc56572fe7fa', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 23, 23, 'Buy the truth, and don''t sell it. Get wisdom, discipline, and understanding.'),
  ('cca6175d-bcbf-5f8e-a481-6b8f15636830', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 24, 24, 'The father of the righteous has great joy. Whoever fathers a wise child delights in him.'),
  ('250c0da8-9772-52ec-aaa7-c9e61e04ef5a', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 25, 25, 'Let your father and your mother be glad! Let her who bore you rejoice!'),
  ('6343b9c3-7858-574a-a975-30ef1a8023d4', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 26, 26, 'My son, give me your heart; and let your eyes keep in my ways.'),
  ('ad69b823-d9c4-54dc-ad3a-b14562d90d70', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 27, 27, 'For a prostitute is a deep pit; and a wayward wife is a narrow well.'),
  ('6a476489-bc2d-56dd-ab14-80627ab9bce5', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 28, 28, 'Yes, she lies in wait like a robber, and increases the unfaithful among men.'),
  ('47fb38c3-901d-5d43-af5a-a3b4eafa9f26', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 29, 29, 'Who has woe? Who has sorrow? Who has strife? Who has complaints? Who has needless bruises? Who has bloodshot eyes?'),
  ('7a3fafa2-f993-556a-ae42-420291259037', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 30, 30, 'Those who stay long at the wine; those who go to seek out mixed wine.'),
  ('b5441067-6fe0-5ca9-a87c-c569f81333a4', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 31, 31, 'Don''t look at the wine when it is red, when it sparkles in the cup, when it goes down smoothly.'),
  ('846e46d9-34dd-5616-aaad-d28d82e1b12e', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 32, 32, 'In the end, it bites like a snake, and poisons like a viper.'),
  ('be4b94b3-3f8c-575e-a261-b8e746b6f833', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 33, 33, 'Your eyes will see strange things, and your mind will imagine confusing things.'),
  ('c9725154-623b-5bad-a0a9-bbffbb224a3a', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 34, 34, 'Yes, you will be as he who lies down in the midst of the sea, or as he who lies on top of the rigging:'),
  ('27575b87-70db-5be3-aa0d-1757163dff81', 'e7c995ca-54a2-5dea-a22a-6d4c76efae7a', NULL, 35, 35, '"They hit me, and I was not hurt! They beat me, and I don''t feel it! When will I wake up? I can do it again. I can find another."'),
  ('1d6f56b8-a275-5398-a274-11e9c442aaac', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 1, 1, 'Don''t be envious of evil men; neither desire to be with them:'),
  ('66227d58-a1eb-57f6-ac6b-e8adc3b393bc', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 2, 2, 'for their hearts plot violence, and their lips talk about mischief.'),
  ('3a9c385c-24be-54a5-a1c2-06228ce7007a', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 3, 3, 'Through wisdom a house is built; by understanding it is established;'),
  ('8167a755-a97c-52fe-a6db-1ff706ae92db', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 4, 4, 'by knowledge the rooms are filled with all rare and beautiful treasure.'),
  ('f695edab-0038-5b33-a9a9-02b1cf7b2657', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 5, 5, 'A wise man has great power; and a knowledgeable man increases strength;'),
  ('10276667-e5a7-50bd-aed2-054738c85748', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 6, 6, 'for by wise guidance you wage your war; and victory is in many advisors.'),
  ('05561145-f910-599c-aa5d-50e7a2c96f95', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 7, 7, 'Wisdom is too high for a fool: he doesn''t open his mouth in the gate.'),
  ('5ed1f8fe-5668-5f54-a9ca-44fdee0e3731', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 8, 8, 'One who plots to do evil will be called a schemer.'),
  ('dcee3650-64b7-5fa0-ab6b-c5e02f6dd374', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 9, 9, 'The schemes of folly are sin. The mocker is detested by men.'),
  ('20c7188e-9c2f-54d8-a73c-3927031c4b9e', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 10, 10, 'If you falter in the time of trouble, your strength is small.'),
  ('fd6bd53f-9265-57bc-a9b8-0a3249e69922', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 11, 11, 'Rescue those who are being led away to death! Indeed, hold back those who are staggering to the slaughter!'),
  ('c8164f93-9ce8-58ff-a83c-f64e3d107b57', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 12, 12, 'If you say, "Behold, we didn''t know this;" doesn''t he who weighs the hearts consider it? He who keeps your soul, doesn''t he know it? Shall he not render to every man according to his work?'),
  ('8d36085d-c05d-588e-a7d9-1902a3d8e59d', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 13, 13, 'My son, eat honey, for it is good; the droppings of the honeycomb, which are sweet to your taste:'),
  ('6a6d4941-9a09-5a75-a51b-b8149b29da69', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 14, 14, 'so you shall know wisdom to be to your soul; if you have found it, then there will be a reward, your hope will not be cut off.'),
  ('98ab704e-24e7-5df5-a347-728836cbf1ca', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 15, 15, 'Don''t lay in wait, wicked man, against the habitation of the righteous. Don''t destroy his resting place:'),
  ('1d325b14-4a49-5359-aa94-5150b86715ed', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 16, 16, 'for a righteous man falls seven times, and rises up again; but the wicked are overthrown by calamity.'),
  ('83c84a2f-01ad-5d3e-a3b5-a9b15aeaafd5', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 17, 17, 'Don''t rejoice when your enemy falls. Don''t let your heart be glad when he is overthrown;'),
  ('6b494b95-1d01-5b59-a7d7-ae57c8ea9cf4', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 18, 18, 'lest Yahweh see it, and it displease him, and he turn away his wrath from him.'),
  ('b696785c-22a1-5740-a976-009febf22f15', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 19, 19, 'Don''t fret yourself because of evildoers; neither be envious of the wicked:'),
  ('f9a529fb-01ec-5d2c-a370-a58f299f8503', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 20, 20, 'for there will be no reward to the evil man; and the lamp of the wicked shall be snuffed out.'),
  ('66343a10-9c88-55f7-aa1d-13ffd9989143', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 21, 21, 'My son, fear Yahweh and the king. Don''t join those who are rebellious:'),
  ('64ad61bb-66f4-5db5-a1bb-2ddc5155c3e9', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 22, 22, 'for their calamity will rise suddenly; the destruction from them both--who knows?'),
  ('52fdefbf-c43f-52ff-a2ac-e943ee5c7ef7', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 23, 23, 'These also are sayings of the wise. To show partiality in judgment is not good.'),
  ('d6cefce8-d6c9-58db-ad12-66054efebdf7', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 24, 24, 'He who says to the wicked, "You are righteous;" peoples shall curse him, and nations shall abhor him--'),
  ('5abba4de-c31d-5442-ae47-b04ea1047d99', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 25, 25, 'but it will go well with those who convict the guilty, and a rich blessing will come on them.'),
  ('9bd0eab0-1307-5604-ad18-2a960dc91fc7', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 26, 26, 'An honest answer is like a kiss on the lips.'),
  ('d3330091-8e28-5b85-a142-685e9b65ab88', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 27, 27, 'Prepare your work outside, and get your fields ready. Afterwards, build your house.'),
  ('bd9ec47c-d047-5f57-ab23-66d4d2c7718d', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 28, 28, 'Don''t be a witness against your neighbor without cause. Don''t deceive with your lips.'),
  ('f9c4df28-fb98-5182-affb-f760cfd98ff3', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 29, 29, 'Don''t say, "I will do to him as he has done to me; I will render to the man according to his work."'),
  ('ab521c3a-1db7-5411-aadb-396ea0c8dd9e', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 30, 30, 'I went by the field of the sluggard, by the vineyard of the man void of understanding;'),
  ('7c7a20e6-f7c6-57f6-a6fa-3dd1181718b7', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 31, 31, 'Behold, it was all grown over with thorns. Its surface was covered with nettles, and its stone wall was broken down.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('89cd9752-2641-5e7c-a8af-683b51663aa1', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 32, 32, 'Then I saw, and considered well. I saw, and received instruction:'),
  ('54f51835-8ffe-5a7d-a5ef-b7d9c3dcdffc', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 33, 33, 'a little sleep, a little slumber, a little folding of the hands to sleep;'),
  ('91ecdc13-3891-5664-a7e0-e925f9f0f529', '4f0c2069-6bb1-5cc4-a522-8bbde407cc28', NULL, 34, 34, 'so your poverty will come as a robber, and your want as an armed man.'),
  ('1a8135d7-48e1-544e-a8ed-0ee45e22495b', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 1, 1, 'These also are proverbs of Solomon, which the men of Hezekiah king of Judah copied out.'),
  ('f799957a-70a7-5f11-af81-387d49c956b5', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 2, 2, 'It is the glory of God to conceal a thing, but the glory of kings is to search out a matter.'),
  ('50a64bbc-e72f-5cc3-a1ae-1f5eb8217f4d', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 3, 3, 'As the heavens for height, and the earth for depth, so the hearts of kings are unsearchable.'),
  ('0d28ac72-1372-59df-a413-ecba14bc22a5', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 4, 4, 'Take away the dross from the silver, and material comes out for the refiner;'),
  ('2e03584a-a3e1-5cf0-a836-1c9ae4d32315', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 5, 5, 'Take away the wicked from the king''s presence, and his throne will be established in righteousness.'),
  ('3fad3594-47c6-5141-a9c0-52eb6047ef8d', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 6, 6, 'Don''t exalt yourself in the presence of the king, or claim a place among great men;'),
  ('577e4d0b-17bc-505b-a358-e552170f2d39', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 7, 7, 'for it is better that it be said to you, "Come up here," than that you should be put lower in the presence of the prince, whom your eyes have seen.'),
  ('bff3fcb8-243d-5cce-acf5-3f2b13f0afec', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 8, 8, 'Don''t be hasty in bringing charges to court. What will you do in the end when your neighbor shames you?'),
  ('9bc9ca18-308d-57e1-a252-aca73b2ecf54', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 9, 9, 'Debate your case with your neighbor, and don''t betray the confidence of another;'),
  ('b2d889ab-2ee5-598c-ac36-db4561b6844d', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 10, 10, 'lest one who hears it put you to shame, and your bad reputation never depart.'),
  ('6f1cc96b-52f9-5bc3-ac56-d20aaf0996dc', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 11, 11, 'A word fitly spoken is like apples of gold in settings of silver.'),
  ('7a5c6fa4-33a6-5ec5-a31c-39acd090189e', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 12, 12, 'As an earring of gold, and an ornament of fine gold, so is a wise reprover to an obedient ear.'),
  ('b6c5a1f2-2665-5fd5-aded-d2a87d17f4ac', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 13, 13, 'As the cold of snow in the time of harvest, so is a faithful messenger to those who send him; for he refreshes the soul of his masters.'),
  ('428ea1d4-c9c5-58c4-aff0-c108d64b510d', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 14, 14, 'As clouds and wind without rain, so is he who boasts of gifts deceptively.'),
  ('c7534b60-7f34-5332-a87d-3920eb7ed16d', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 15, 15, 'By patience a ruler is persuaded. A soft tongue breaks the bone.'),
  ('4a04120e-06b1-53cd-a68e-63879d7bd465', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 16, 16, 'Have you found honey? Eat as much as is sufficient for you, lest you eat too much, and vomit it.'),
  ('349ee876-ffe9-5acc-ac62-253cd1051dcd', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 17, 17, 'Let your foot be seldom in your neighbor''s house, lest he be weary of you, and hate you.'),
  ('60510b12-b64f-501e-a0e1-8e46d95857b2', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 18, 18, 'A man who gives false testimony against his neighbor is like a club, a sword, or a sharp arrow.'),
  ('9bee64f6-3537-5111-a355-10d8d874ed72', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 19, 19, 'Confidence in someone unfaithful in time of trouble is like a bad tooth, or a lame foot.'),
  ('42a17c65-53b1-5383-a891-103a5c2c649c', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 20, 20, 'As one who takes away a garment in cold weather, or vinegar on soda, so is one who sings songs to a heavy heart.'),
  ('8b7cdb78-545c-502e-aeae-0634b2b68f68', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 21, 21, 'If your enemy is hungry, give him food to eat. If he is thirsty, give him water to drink:'),
  ('56e9a79f-6235-5816-ae6f-879132b8772d', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 22, 22, 'for you will heap coals of fire on his head, and Yahweh will reward you.'),
  ('0361bcbe-ec36-5ca4-a5f7-c3b292be6dcd', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 23, 23, 'The north wind brings forth rain: so a backbiting tongue brings an angry face.'),
  ('da25e35b-e9fb-5b71-a74d-c5c0d3da9ac1', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 24, 24, 'It is better to dwell in the corner of the housetop, than to share a house with a contentious woman.'),
  ('ebc62cf4-2ca5-5e5e-a937-b97509b7ef81', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 25, 25, 'Like cold water to a thirsty soul, so is good news from a far country.'),
  ('bd870a72-6055-5f7a-ae81-a5af0ec9a2e3', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 26, 26, 'Like a muddied spring, and a polluted well, so is a righteous man who gives way before the wicked.'),
  ('72f1b719-2087-5c05-a8e9-09c8a1635f6c', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 27, 27, 'It is not good to eat much honey; nor is it honorable to seek one''s own honor.'),
  ('c8918352-2481-5ed8-a150-8780e0a11b5c', '297c41cf-a7d7-5f68-a79d-5ff3c018d1af', NULL, 28, 28, 'Like a city that is broken down and without walls is a man whose spirit is without restraint.'),
  ('b0072181-059f-5f0f-a16f-3f1ca79e282c', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 1, 1, 'Like snow in summer, and as rain in harvest, so honor is not fitting for a fool.'),
  ('6a681ec9-8535-57c0-aec1-98bf40f3d537', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 2, 2, 'Like a fluttering sparrow, like a darting swallow, so the undeserved curse doesn''t come to rest.'),
  ('cf2920cd-5d46-5e19-a3ab-ea633594fa73', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 3, 3, 'A whip is for the horse, a bridle for the donkey, and a rod for the back of fools!'),
  ('cd54cdbb-6dee-5f57-a780-656db48c4744', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 4, 4, 'Don''t answer a fool according to his folly, lest you also be like him.'),
  ('e099e914-002b-5f87-af26-948aacf53d3c', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 5, 5, 'Answer a fool according to his folly, lest he be wise in his own eyes.'),
  ('15af3790-fc57-571f-a3b5-7638145738a7', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 6, 6, 'One who sends a message by the hand of a fool is cutting off feet and drinking violence.'),
  ('abab7651-3dd3-5f52-ac16-a8ad203d69b0', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 7, 7, 'Like the legs of the lame that hang loose: so is a parable in the mouth of fools.'),
  ('e2f9ab13-4d0e-5f1a-ac6e-b7dc8d8a2066', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 8, 8, 'As one who binds a stone in a sling, so is he who gives honor to a fool.'),
  ('d0bbf553-1642-5170-ae13-91ae959971b6', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 9, 9, 'Like a thornbush that goes into the hand of a drunkard, so is a parable in the mouth of fools.'),
  ('4e6ce88a-f017-52dd-af55-2fe0ce25a627', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 10, 10, 'As an archer who wounds all, so is he who hires a fool or he who hires those who pass by.'),
  ('02878592-3230-5f99-ad4f-77836cdf6dcb', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 11, 11, 'As a dog that returns to his vomit, so is a fool who repeats his folly.'),
  ('7a645996-8ba7-56e9-ade2-fbaf1b7752e2', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 12, 12, 'Do you see a man wise in his own eyes? There is more hope for a fool than for him.'),
  ('de12cf5e-bbeb-5840-a6aa-10e2acb585e5', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 13, 13, 'The sluggard says, "There is a lion in the road! A fierce lion roams the streets!"'),
  ('ffc1f168-6645-5038-a48b-fce108af43b1', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 14, 14, 'As the door turns on its hinges, so does the sluggard on his bed.'),
  ('e7c8b0fb-5422-5bc4-a462-6bffcd8246f6', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 15, 15, 'The sluggard buries his hand in the dish. He is too lazy to bring it back to his mouth.'),
  ('989f1d2e-ddbc-5cb7-aaf6-104eaed220b2', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 16, 16, 'The sluggard is wiser in his own eyes than seven men who answer with discretion.'),
  ('df93c41f-eb0f-56a9-adaf-9c4cabdd5e43', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 17, 17, 'Like one who grabs a dog''s ears is one who passes by and meddles in a quarrel not his own.'),
  ('085245b4-8bf3-5974-a9c6-7d1b6495d53f', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 18, 18, 'Like a madman who shoots torches, arrows, and death,'),
  ('7378b8eb-4018-50fe-a01a-f6a79bc685a5', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 19, 19, 'is the man who deceives his neighbor and says, "Am I not joking?"'),
  ('91252863-809f-5a31-adf4-e1f0848308ee', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 20, 20, 'For lack of wood a fire goes out. Without gossip, a quarrel dies down.'),
  ('8b2102d2-4153-5488-adbe-d9c953cc540d', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 21, 21, 'As coals are to hot embers, and wood to fire, so is a contentious man to kindling strife.'),
  ('3693a215-a6dc-5ab8-a065-99177f9d1185', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 22, 22, 'The words of a whisperer are as dainty morsels, they go down into the innermost parts.'),
  ('ef1fa59e-0e04-53a4-a87f-43669cb3b729', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 23, 23, 'Like silver dross on an earthen vessel are the lips of a fervent one with an evil heart.'),
  ('00a7eb16-f529-50a8-a959-a2608049832a', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 24, 24, 'A malicious man disguises himself with his lips, but he harbors evil in his heart.'),
  ('ff57bebd-455f-5810-aa5f-29b482ac12b8', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 25, 25, 'When his speech is charming, don''t believe him; for there are seven abominations in his heart.'),
  ('9d39c092-6153-581d-abd9-89833eb8660c', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 26, 26, 'His malice may be concealed by deception, but his wickedness will be exposed in the assembly.'),
  ('4b59300d-8292-5960-a4dc-f662b4b04ce8', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 27, 27, 'Whoever digs a pit shall fall into it. Whoever rolls a stone, it will come back on him.'),
  ('3658c431-ceb7-5469-a5d6-b60154290226', '4783044a-e3dd-5be4-ac84-cdc790bd20ee', NULL, 28, 28, 'A lying tongue hates those it hurts; and a flattering mouth works ruin.'),
  ('0f211093-3216-5930-a6f3-c4ff8e696bf3', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 1, 1, 'Don''t boast about tomorrow; for you don''t know what a day may bring forth.'),
  ('7088bf22-1e4a-564e-ad22-78db456d17f0', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 2, 2, 'Let another man praise you, and not your own mouth; a stranger, and not your own lips.'),
  ('a5dea014-c983-56eb-a617-1ce363acce3b', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 3, 3, 'A stone is heavy, and sand is a burden; but a fool''s provocation is heavier than both.'),
  ('8cb500fd-9813-546f-a527-1a5f40d73250', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 4, 4, 'Wrath is cruel, and anger is overwhelming; but who is able to stand before jealousy?'),
  ('55ceb221-bfef-5324-a2d2-35aff0b1dc26', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 5, 5, 'Better is open rebuke than hidden love.'),
  ('d21d6620-ade5-5122-aea4-0eed53a5d86e', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 6, 6, 'Faithful are the wounds of a friend; although the kisses of an enemy are profuse.'),
  ('82fce824-35cf-58a2-abcf-3bac3d79a00d', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 7, 7, 'A full soul loathes a honeycomb; but to a hungry soul, every bitter thing is sweet.'),
  ('7abc3ee5-2dba-5832-a5ea-0e876022409e', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 8, 8, 'As a bird that wanders from her nest, so is a man who wanders from his home.'),
  ('f0043b55-ff4c-5b68-a0f6-1b37783b0cfe', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 9, 9, 'Perfume and incense bring joy to the heart; so does earnest counsel from a man''s friend.'),
  ('00e462a8-f385-50f0-ad30-f51d06ec6da4', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 10, 10, 'Don''t forsake your friend and your father''s friend. Don''t go to your brother''s house in the day of your disaster: better is a neighbor who is near than a distant brother.'),
  ('b1cf5899-6a33-584a-a7c0-34a4d6f96c9b', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 11, 11, 'Be wise, my son, and bring joy to my heart, then I can answer my tormentor.'),
  ('de45290d-1a8d-582e-a5f1-e4b59bd2d877', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 12, 12, 'A prudent man sees danger and takes refuge; but the simple pass on, and suffer for it.'),
  ('4a3fbbde-b237-5c17-a8de-56176d6a0efb', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 13, 13, 'Take his garment when he puts up collateral for a stranger. Hold it for a wayward woman!'),
  ('07e1b297-254b-5080-a59d-87b8cbd64c14', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 14, 14, 'He who blesses his neighbor with a loud voice early in the morning, it will be taken as a curse by him.'),
  ('d529238e-770d-5baf-a343-39a5b0a69680', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 15, 15, 'A continual dropping on a rainy day and a contentious wife are alike:'),
  ('a6fa06b4-5956-5483-ad05-35f45467e1d9', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 16, 16, 'restraining her is like restraining the wind, or like grasping oil in his right hand.'),
  ('585ce44c-e1ef-532a-a4b0-8fa3bc1d2d16', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 17, 17, 'Iron sharpens iron; so a man sharpens his friend''s countenance.'),
  ('8aa58be0-6b7a-5d03-adb2-6157c9256577', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 18, 18, 'Whoever tends the fig tree shall eat its fruit. He who looks after his master shall be honored.'),
  ('495975e2-47c5-5c11-a78d-750ba1744ca3', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 19, 19, 'As water reflects a face, so a man''s heart reflects the man.'),
  ('77681bf0-2732-5d53-a7c2-c3b8565db4c2', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 20, 20, 'Sheol and Abaddon are never satisfied; and a man''s eyes are never satisfied.'),
  ('61ec8aac-7032-5b58-a959-d6e1c093cf70', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 21, 21, 'The crucible is for silver, and the furnace for gold; but man is refined by his praise.'),
  ('b2265d07-ee46-5a8d-acc7-d5cf5c5aed76', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 22, 22, 'Though you grind a fool in a mortar with a pestle along with grain, yet his foolishness will not be removed from him.'),
  ('c8e1ee87-e96a-528e-a025-f95700685960', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 23, 23, 'Know well the state of your flocks, and pay attention to your herds:'),
  ('16032e67-f3e2-5d5f-a633-6533e2ce094b', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 24, 24, 'for riches are not forever, nor does even the crown endure to all generations.'),
  ('5ed5a418-cd0c-5ae1-ab9b-b2a2276439a9', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 25, 25, 'The hay is removed, and the new growth appears, the grasses of the hills are gathered in.'),
  ('9e1b7c68-de88-5690-a626-c2669c86c312', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 26, 26, 'The lambs are for your clothing, and the goats are the price of a field.'),
  ('cc9a478b-60a3-572e-af81-80b1d5681dcd', '5ec2a2c1-2d50-5b2c-aa5f-2429f8ef1d1b', NULL, 27, 27, 'There will be plenty of goats'' milk for your food, for your family''s food, and for the nourishment of your servant girls.'),
  ('4e0ccf45-ddb3-52ce-a6ea-28bc7db1b34e', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 1, 1, 'The wicked flee when no one pursues; but the righteous are as bold as a lion.'),
  ('1bf1da39-22db-5d2b-a727-eed3de895317', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 2, 2, 'In rebellion, a land has many rulers, but order is maintained by a man of understanding and knowledge.'),
  ('dbb8e16c-9aa0-5958-a501-4c2f84ff53e1', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 3, 3, 'A needy man who oppresses the poor is like a driving rain which leaves no crops.'),
  ('f6fc093b-3819-5c36-a0f2-f2037cb635e3', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 4, 4, 'Those who forsake the law praise the wicked; but those who keep the law contend with them.'),
  ('2c3fcf25-5d65-557d-a108-a1f00118b333', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 5, 5, 'Evil men don''t understand justice; but those who seek Yahweh understand it fully.'),
  ('4b272a8c-8b92-5ba7-a982-728d20f1c888', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 6, 6, 'Better is the poor who walks in his integrity, than he who is perverse in his ways, and he is rich.'),
  ('44f962af-8192-5073-ad3e-1e0594b840fb', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 7, 7, 'Whoever keeps the law is a wise son; but he who is a companion of gluttons shames his father.'),
  ('c3b444f7-ff3a-59fa-a89a-c5e3fbd4b15c', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 8, 8, 'He who increases his wealth by excessive interest gathers it for one who has pity on the poor.'),
  ('53626c70-09a0-572e-a31f-7cef437fc411', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 9, 9, 'He who turns away his ear from hearing the law, even his prayer is an abomination.'),
  ('f950cc9d-dc09-50e6-a731-8bca6fe916bb', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 10, 10, 'Whoever causes the upright to go astray in an evil way, he will fall into his own trap; but the blameless will inherit good.'),
  ('c1e073cf-f935-5fa3-af41-5e279f1eefee', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 11, 11, 'The rich man is wise in his own eyes; but the poor who has understanding sees through him.'),
  ('20e9da9f-687b-5f3f-aa6e-d0d487182d19', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 12, 12, 'When the righteous triumph, there is great glory; but when the wicked rise, men hide themselves.'),
  ('90d31d46-a18e-5099-a9d6-64416a7cf49b', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 13, 13, 'He who conceals his sins doesn''t prosper, but whoever confesses and renounces them finds mercy.'),
  ('d9cc37ff-0162-54ac-ab3a-8d3affb97614', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 14, 14, 'Blessed is the man who always fears; but one who hardens his heart falls into trouble.'),
  ('671d012f-f301-5062-a304-ebb1fb7c3899', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 15, 15, 'As a roaring lion or a charging bear, so is a wicked ruler over helpless people.'),
  ('50b28624-53dd-54b2-a893-535b443473be', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 16, 16, 'A tyrannical ruler lacks judgment. One who hates ill-gotten gain will have long days.'),
  ('a53b1f74-6cb8-54fe-a6b5-6d1fd6c3a6eb', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 17, 17, 'A man who is tormented by life blood will be a fugitive until death; no one will support him.'),
  ('5b70f9d3-fc93-5c36-abee-c84be342ea3c', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 18, 18, 'Whoever walks blamelessly is kept safe; but one with perverse ways will fall suddenly.'),
  ('c54f532a-aa40-5c93-ac80-48e0899efbfa', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 19, 19, 'One who works his land will have an abundance of food; but one who chases fantasies will have his fill of poverty.'),
  ('36a42a6e-5321-567f-af35-26a63c91c2c7', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 20, 20, 'A faithful man is rich with blessings; but one who is eager to be rich will not go unpunished.'),
  ('461adb27-0da2-5fec-a2ce-cb19b8ccb986', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 21, 21, 'To show partiality is not good; yet a man will do wrong for a piece of bread.'),
  ('6809f6ec-cc22-575e-abd7-467adb9cfad0', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 22, 22, 'A stingy man hurries after riches, and doesn''t know that poverty waits for him.'),
  ('c484de40-d881-56af-ac7b-abc994918455', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 23, 23, 'One who rebukes a man will afterward find more favor than one who flatters with the tongue.'),
  ('694bc85a-e7b2-5a52-a54d-cd2190660df4', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 24, 24, 'Whoever robs his father or his mother, and says, "It''s not wrong." He is a partner with a destroyer.'),
  ('bc265872-ade0-5e61-ad99-3bea45f24656', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 25, 25, 'One who is greedy stirs up strife; but one who trusts in Yahweh will prosper.'),
  ('58322979-d387-5839-a1b1-6375be808e1f', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 26, 26, 'One who trusts in himself is a fool; but one who walks in wisdom is kept safe.'),
  ('c45c75c2-b8ea-5270-a3ac-bbe237683211', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 27, 27, 'One who gives to the poor has no lack; but one who closes his eyes will have many curses.'),
  ('ef0ecaef-b69e-500a-ad6c-0db75eaea1a0', '1ef12c60-1b2e-5457-a958-eaf87819e3d9', NULL, 28, 28, 'When the wicked rise, men hide themselves; but when they perish, the righteous thrive.'),
  ('e8923c7b-cea1-574d-abf0-6e039f3306d6', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 1, 1, 'He who is often rebuked and stiffens his neck will be destroyed suddenly, with no remedy.'),
  ('e5534e6d-8b5a-520f-aef8-1af6571b97ba', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 2, 2, 'When the righteous thrive, the people rejoice; but when the wicked rule, the people groan.'),
  ('2e64f50a-6820-540f-a035-e4c99cef8f49', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 3, 3, 'Whoever loves wisdom brings joy to his father; but a companion of prostitutes squanders his wealth.'),
  ('4df56305-24ed-5580-ac6a-b9fafcd68dbb', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 4, 4, 'The king by justice makes the land stable, but he who takes bribes tears it down.'),
  ('02764688-95b2-58c4-a2fe-5a5ac12b838b', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 5, 5, 'A man who flatters his neighbor spreads a net for his feet.'),
  ('4d5188ce-deee-5c73-af1d-0c6aa37a5cbf', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 6, 6, 'An evil man is snared by his sin, but the righteous can sing and be glad.'),
  ('082a8ad3-2075-505b-a92b-10e6601d61d2', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 7, 7, 'The righteous care about justice for the poor. The wicked aren''t concerned about knowledge.'),
  ('ccceacab-bc37-58fc-a473-2b6d02e8ce26', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 8, 8, 'Mockers stir up a city, but wise men turn away anger.'),
  ('b03883cd-66d3-5d2a-a1df-bdfa7dd3471e', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 9, 9, 'If a wise man goes to court with a foolish man, the fool rages or scoffs, and there is no peace.'),
  ('9dd9ce14-d93b-5279-aa67-8b6f59a80128', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 10, 10, 'The bloodthirsty hate a man of integrity; and they seek the life of the upright.'),
  ('c300c2d5-2966-59bb-aa61-2b6df38621e1', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 11, 11, 'A fool vents all of his anger, but a wise man brings himself under control.'),
  ('55ab9263-eab3-5766-a324-b39d42d8bb5b', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 12, 12, 'If a ruler listens to lies, all of his officials are wicked.'),
  ('9f2cb7a7-9b3b-5987-ac72-055ff94e738f', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 13, 13, 'The poor man and the oppressor have this in common: Yahweh gives sight to the eyes of both.'),
  ('e6cbfe4d-caba-58f3-ab25-70c37535ed83', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 14, 14, 'The king who fairly judges the poor, his throne shall be established forever.'),
  ('9ce8e5fe-961b-581d-a351-ebc5a5683360', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 15, 15, 'The rod of correction gives wisdom, but a child left to himself causes shame to his mother.'),
  ('7dcac7ea-0619-5576-a6d7-74c00c049fd0', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 16, 16, 'When the wicked increase, sin increases; but the righteous will see their downfall.'),
  ('f5c6b7ac-d925-58b2-adf4-c019f8ccb8ce', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 17, 17, 'Correct your son, and he will give you peace; yes, he will bring delight to your soul.'),
  ('b58503a1-5cec-5114-a2aa-5818524e23dd', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 18, 18, 'Where there is no revelation, the people cast off restraint; but one who keeps the law is blessed.'),
  ('3341e28a-b2ed-5a88-a7a6-d58edfbf885d', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 19, 19, 'A servant can''t be corrected by words. Though he understands, yet he will not respond.'),
  ('077f6bed-4e34-5598-a7fd-198c02bc0178', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 20, 20, 'Do you see a man who is hasty in his words? There is more hope for a fool than for him.'),
  ('acf5dd9a-8ce3-5b26-a14d-25c36a869012', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 21, 21, 'He who pampers his servant from youth will have him become a son in the end.'),
  ('182c59d6-193a-58fd-ae1f-15a9ff3c7b5f', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 22, 22, 'An angry man stirs up strife, and a wrathful man abounds in sin.'),
  ('2e71876c-aa4a-51ac-aada-1a4c6c65c359', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 23, 23, 'A man''s pride brings him low, but one of lowly spirit gains honor.'),
  ('5bd26403-57da-5024-ab28-e5e8f99817eb', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 24, 24, 'Whoever is an accomplice of a thief is an enemy of his own soul. He takes an oath, but dares not testify.'),
  ('06810175-b0ad-5a96-ab65-724ded18ab11', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 25, 25, 'The fear of man proves to be a snare, but whoever puts his trust in Yahweh is kept safe.'),
  ('ca100491-4401-5f49-abb8-73badb3f593c', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 26, 26, 'Many seek the ruler''s favor, but a man''s justice comes from Yahweh.'),
  ('843385db-e3c6-5d76-a7cd-9aef9e2ac375', '50df3e95-f824-5413-a31f-8a0c2d61dab7', NULL, 27, 27, 'A dishonest man detests the righteous, and the upright in their ways detest the wicked.'),
  ('67fd024a-3c4a-59fc-ad50-6a8a5c3eb2cf', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 1, 1, 'The words of Agur the son of Jakeh, the oracle: the man says to Ithiel, to Ithiel and Ucal:'),
  ('3c22aacd-7907-55ec-a30d-ef9486a19c1f', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 2, 2, '"Surely I am the most ignorant man, and don''t have a man''s understanding.'),
  ('bad53f6f-9a67-50f9-a709-409f96bbd72b', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 3, 3, 'I have not learned wisdom, neither do I have the knowledge of the Holy One.'),
  ('6fa8c93d-bf5e-574f-ab4d-f820629a80d8', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 4, 4, 'Who has ascended up into heaven, and descended? Who has gathered the wind in his fists? Who has bound the waters in his garment? Who has established all the ends of the earth? What is his name, and what is his son''s name, if you know?'),
  ('4f616241-7230-5d4e-a87d-4f3e6327bbc0', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 5, 5, '"Every word of God is flawless. He is a shield to those who take refuge in him.'),
  ('546d7af2-6e94-576d-a650-afbbfebb2ebb', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 6, 6, 'Don''t you add to his words, lest he reprove you, and you be found a liar.'),
  ('33cf91fe-bcc5-5adb-a344-d7a9eaf5b2e9', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 7, 7, '"Two things I have asked of you; don''t deny me before I die:'),
  ('5bbcd807-3713-5bf8-ad3e-f8633b5f74e7', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 8, 8, 'Remove far from me falsehood and lies. Give me neither poverty nor riches. Feed me with the food that is needful for me;'),
  ('022db65f-07a6-5ab3-a438-f3dcff0a57f9', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 9, 9, 'lest I be full, deny you, and say, ''Who is Yahweh?'' or lest I be poor, and steal, and so dishonor the name of my God.'),
  ('825cb62f-3b77-5bd8-af65-458f48e54119', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 10, 10, '"Don''t slander a servant to his master, lest he curse you, and you be held guilty.'),
  ('799c18b8-4184-55a8-a9d8-5a9637828dbd', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 11, 11, 'There is a generation that curses their father, and doesn''t bless their mother.'),
  ('2f792b50-0277-519e-a18a-138f94976040', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 12, 12, 'There is a generation that is pure in their own eyes, yet are not washed from their filthiness.'),
  ('56c5217f-ae3a-545e-a219-98c00ae61959', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 13, 13, 'There is a generation, oh how lofty are their eyes! Their eyelids are lifted up.'),
  ('96dfad0e-aedd-514a-a63a-7a1b8eb46a49', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 14, 14, 'There is a generation whose teeth are like swords, and their jaws like knives, to devour the poor from the earth, and the needy from among men.'),
  ('75a0050d-865d-510f-a3a5-a6b9b75da34f', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 15, 15, '"The leach has two daughters: ''Give, give.'' "There are three things that are never satisfied; four that don''t say, ''Enough:'''),
  ('dc53ec9a-7273-50bd-a64f-f64bca070c20', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 16, 16, 'Sheol, the barren womb; the earth that is not satisfied with water; and the fire that doesn''t say, ''Enough.'''),
  ('55c2f39d-89a1-5d60-a17c-948b1665fda7', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 17, 17, '"The eye that mocks at his father, and scorns obedience to his mother: the ravens of the valley shall pick it out, the young eagles shall eat it.'),
  ('accde106-26c5-51f2-a9f9-dcae220c209d', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 18, 18, '"There are three things which are too amazing for me, four which I don''t understand:'),
  ('28161a06-f25d-527d-afeb-c158e59a281a', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 19, 19, 'The way of an eagle in the air; the way of a serpent on a rock; the way of a ship in the midst of the sea; and the way of a man with a maiden.'),
  ('1680a26a-1cfd-5106-a98e-d6b536b1d6b8', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 20, 20, '"So is the way of an adulterous woman: she eats and wipes her mouth, and says, ''I have done nothing wrong.'''),
  ('43287a94-fce3-56fd-af8f-399ff0eb38f4', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 21, 21, '"For three things the earth tremble, and under four, it can''t bear up:'),
  ('2376e361-0d30-5fc0-a835-e887dd029a43', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 22, 22, 'For a servant when he is king; a fool when he is filled with food;'),
  ('17c3d202-62f4-5cac-a261-3a92cf6226ea', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 23, 23, 'for an unloved woman when she is married; and a handmaid who is heir to her mistress.'),
  ('db77557f-9f2e-5a41-a03b-3130dce01604', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 24, 24, '"There are four things which are little on the earth, but they are exceedingly wise:'),
  ('97960ba6-ec67-518a-a74a-5385839933bb', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 25, 25, 'the ants are not a strong people, yet they provide their food in the summer.'),
  ('67dc33d6-9a4f-5dce-ae17-7f4594a37e1f', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 26, 26, 'The conies are but a feeble folk, yet make they their houses in the rocks.'),
  ('0013ba1c-1c16-5584-ae56-cc811cd9f5fa', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 27, 27, 'The locusts have no king, yet they advance in ranks.'),
  ('8919a65b-b092-56ab-a0ed-1478c21f47f5', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 28, 28, 'You can catch a lizard with your hands, yet it is in kings'' palaces.'),
  ('5c7b569a-4c6d-5c6e-a109-ae274fef8a06', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 29, 29, '"There are three things which are stately in their march, four which are stately in going:'),
  ('6f556857-fce9-5458-a8e5-85b2a6324264', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 30, 30, 'The lion, which is mightiest among animals, and doesn''t turn away for any;'),
  ('1df15f4d-cee1-5390-a05e-b534c5570061', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 31, 31, 'the greyhound, the male goat also; and the king against whom there is no rising up.'),
  ('b424b5cb-71d8-5d37-a938-1b6546ce9144', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 32, 32, '"If you have done foolishly in lifting up yourself, or if you have thought evil, put your hand over your mouth.'),
  ('c538a233-cd54-5db7-a8e6-f06c98a1b4d2', '96b21002-3b30-5ffe-a7ac-a8c6720ae9f1', NULL, 33, 33, 'For as the churning of milk brings forth butter, and the wringing of the nose brings forth blood; so the forcing of wrath brings forth strife."'),
  ('9574a0cf-48fd-5f8e-a20b-5844665798a2', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 1, 1, 'The words of king Lemuel; the oracle which his mother taught him.'),
  ('bba4bc70-f342-5ce6-a4c2-1f6ab1bdef17', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 2, 2, '"Oh, my son! Oh, son of my womb! Oh, son of my vows!'),
  ('e800c5da-0b45-5f50-acbe-193dfd0197f2', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 3, 3, 'Don''t give your strength to women, nor your ways to that which destroys kings.'),
  ('ebd16795-9333-5a4a-a0fb-0e3d72452842', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 4, 4, 'It is not for kings, Lemuel; it is not for kings to drink wine; nor for princes to say, ''Where is strong drink?'''),
  ('b2aaeb24-47d1-5ab9-a950-e822391417ee', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 5, 5, 'lest they drink, and forget the law, and pervert the justice due to anyone who is afflicted.'),
  ('c8ea4906-a17d-5e71-a138-37208f2f5455', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 6, 6, 'Give strong drink to him who is ready to perish; and wine to the bitter in soul:'),
  ('eafaf607-3b97-523d-a509-2aae1d6126f5', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 7, 7, 'Let him drink, and forget his poverty, and remember his misery no more.'),
  ('de2654cc-ae3d-5f0a-a8e2-67929dd75245', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 8, 8, 'Open your mouth for the mute, in the cause of all who are left desolate.'),
  ('23413082-2bb3-59bf-a259-f576d9e3aaf0', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 9, 9, 'Open your mouth, judge righteously, and serve justice to the poor and needy."'),
  ('b6e9e32e-86f0-5c6a-ae6f-4138cb0c61c0', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 10, 10, 'Who can find a worthy woman? For her price is far above rubies.'),
  ('9009dced-5fd9-5d83-a24d-c2be38ecdcea', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 11, 11, 'The heart of her husband trusts in her. He shall have no lack of gain.'),
  ('78c6064a-b686-5085-a8ed-f2d222c71d13', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 12, 12, 'She does him good, and not harm, all the days of her life.'),
  ('0ca7cd5e-51ce-598f-a202-8f3a91802d6f', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 13, 13, 'She seeks wool and flax, and works eagerly with her hands.'),
  ('59b36aad-e561-5807-a990-0571e7b09548', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 14, 14, 'She is like the merchant ships. She brings her bread from afar.'),
  ('376e025e-1ffa-556f-ad94-085d3ee6959f', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 15, 15, 'She rises also while it is yet night, gives food to her household, and portions for her servant girls.'),
  ('f8628d0c-ae11-5640-a16f-d7d2fa110365', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 16, 16, 'She considers a field, and buys it. With the fruit of her hands, she plants a vineyard.'),
  ('2589156b-8ceb-5d03-ac04-cdb0b39ffa18', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 17, 17, 'She arms her waist with strength, and makes her arms strong.'),
  ('e959a615-488c-5daa-a9b1-f8bbed25c156', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 18, 18, 'She perceives that her merchandise is profitable. Her lamp doesn''t go out by night.'),
  ('90b87c90-a30c-5275-a2b5-555ea5c5c42a', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 19, 19, 'She lays her hands to the distaff, and her hands hold the spindle.'),
  ('069703e2-7367-5bd1-ab9c-36e3a4f7df4f', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 20, 20, 'She opens her arms to the poor; yes, she extends her hands to the needy.'),
  ('2b7cd37a-9b33-5e6e-a411-8544716b1a2b', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 21, 21, 'She is not afraid of the snow for her household; for all her household are clothed with scarlet.'),
  ('cb8ce615-845f-51ea-af3d-365b53106f5f', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 22, 22, 'She makes for herself carpets of tapestry. Her clothing is fine linen and purple.'),
  ('06c2597d-27ac-5116-a5f3-facd2fb4718b', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 23, 23, 'Her husband is respected in the gates, when he sits among the elders of the land.'),
  ('5de2d6b2-1c97-54a1-a489-dab59b8c0069', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 24, 24, 'She makes linen garments and sells them, and delivers sashes to the merchant.'),
  ('4caa7f28-ff6c-563f-af93-53fb7b6dd8e4', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 25, 25, 'Strength and dignity are her clothing. She laughs at the time to come.'),
  ('9dfe5168-6284-5364-adb1-384b6baf12eb', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 26, 26, 'She opens her mouth with wisdom. Faithful instruction is on her tongue.'),
  ('f89fe6f1-88a1-56a2-ab43-8ba1e32f1673', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 27, 27, 'She looks well to the ways of her household, and doesn''t eat the bread of idleness.'),
  ('fb84cde4-30c3-5a60-a229-5ffe2918c080', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 28, 28, 'Her children rise up and call her blessed. Her husband also praises her:'),
  ('35dc2f04-2765-5ce7-a8ed-f2b4758d6627', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 29, 29, '"Many women do noble things, but you excel them all."'),
  ('c6ebe997-82b7-5508-a1b6-d9d394a1068d', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 30, 30, 'Charm is deceitful, and beauty is vain; but a woman who fears Yahweh, she shall be praised.'),
  ('d9690fda-a38d-595b-ae15-6c7ecaccd0bc', '46ab1ecc-4ac0-5268-a722-3ff5d32a930a', NULL, 31, 31, 'Give her of the fruit of her hands! Let her works praise her in the gates!'),
  ('11b5ed5c-030e-5887-a158-58794a3d5f13', 'fd1ec766-c800-5d81-a351-7cb874891126', NULL, 1, 1, 'The words of the Preacher, the son of David, king in Jerusalem:'),
  ('68373ae4-8bfa-5cce-a90c-0440c91e3229', 'fd1ec766-c800-5d81-a351-7cb874891126', NULL, 2, 2, '"Vanity of vanities," says the Preacher; "Vanity of vanities, all is vanity."'),
  ('c4913fa4-95a0-54be-aa5b-17d6964853c1', 'fd1ec766-c800-5d81-a351-7cb874891126', NULL, 3, 3, 'What does man gain from all his labor in which he labors under the sun?'),
  ('4436f540-a8e4-51e9-ad64-76a1a51733ae', 'fd1ec766-c800-5d81-a351-7cb874891126', NULL, 4, 4, 'One generation goes, and another generation comes; but the earth remains forever.'),
  ('efabb73c-530b-5897-a22a-3d755b589f8a', 'fd1ec766-c800-5d81-a351-7cb874891126', NULL, 5, 5, 'The sun also rises, and the sun goes down, and hurries to its place where it rises.'),
  ('4f8057e7-da0b-562b-a633-7c611363f644', 'fd1ec766-c800-5d81-a351-7cb874891126', NULL, 6, 6, 'The wind goes toward the south, and turns around to the north. It turns around continually as it goes, and the wind returns again to its courses.'),
  ('3219c2e7-f1aa-5c0b-a515-62e656d723c6', 'fd1ec766-c800-5d81-a351-7cb874891126', NULL, 7, 7, 'All the rivers run into the sea, yet the sea is not full. To the place where the rivers flow, there they flow again.'),
  ('059fb106-0061-58e7-a42d-acaf8e72dca8', 'fd1ec766-c800-5d81-a351-7cb874891126', NULL, 8, 8, 'All things are full of weariness beyond uttering. The eye is not satisfied with seeing, nor the ear filled with hearing.'),
  ('e434d0a4-65b3-525d-a8d8-3b61df2f485d', 'fd1ec766-c800-5d81-a351-7cb874891126', NULL, 9, 9, 'That which has been is that which shall be; and that which has been done is that which shall be done: and there is no new thing under the sun.'),
  ('dd8e36d0-6366-5800-a28a-f6d429026a22', 'fd1ec766-c800-5d81-a351-7cb874891126', NULL, 10, 10, 'Is there a thing of which it may be said, "Behold, this is new?" It has been long ago, in the ages which were before us.'),
  ('bb45f4be-4afc-562e-a87e-90ed045a64f2', 'fd1ec766-c800-5d81-a351-7cb874891126', NULL, 11, 11, 'There is no memory of the former; neither shall there be any memory of the latter that are to come, among those that shall come after.'),
  ('83a7c312-22b0-53cb-ae4c-0fc480e1c02f', 'fd1ec766-c800-5d81-a351-7cb874891126', NULL, 12, 12, 'I, the Preacher, was king over Israel in Jerusalem.'),
  ('480ea995-cfda-5ef4-a3ae-6c5f0f54b31b', 'fd1ec766-c800-5d81-a351-7cb874891126', NULL, 13, 13, 'I applied my heart to seek and to search out by wisdom concerning all that is done under the sky. It is a heavy burden that God has given to the sons of men to be afflicted with.'),
  ('a302848f-07c6-5db6-a2ae-5505b5308584', 'fd1ec766-c800-5d81-a351-7cb874891126', NULL, 14, 14, 'I have seen all the works that are done under the sun; and behold, all is vanity and a chasing after wind.'),
  ('823fbccd-ebce-5f52-a640-b3481a4a0ca8', 'fd1ec766-c800-5d81-a351-7cb874891126', NULL, 15, 15, 'That which is crooked can''t be made straight; and that which is lacking can''t be counted.'),
  ('60134d51-82d7-5d49-a152-7d4078aed392', 'fd1ec766-c800-5d81-a351-7cb874891126', NULL, 16, 16, 'I said to myself, "Behold, I have obtained for myself great wisdom above all who were before me in Jerusalem. Yes, my heart has had great experience of wisdom and knowledge."'),
  ('6a09a6f6-18cb-54f5-ad60-d9a7182a64b5', 'fd1ec766-c800-5d81-a351-7cb874891126', NULL, 17, 17, 'I applied my heart to know wisdom, and to know madness and folly. I perceived that this also was a chasing after wind.'),
  ('09c290e1-be66-53cf-a315-10bef6cc62d5', 'fd1ec766-c800-5d81-a351-7cb874891126', NULL, 18, 18, 'For in much wisdom is much grief; and he who increases knowledge increases sorrow.'),
  ('0cd97e30-a6d9-59af-a0d6-0389c481e7b3', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 1, 1, 'I said in my heart, "Come now, I will test you with mirth: therefore enjoy pleasure;" and behold, this also was vanity.'),
  ('02c58a63-d963-5827-a29d-f2620b831f57', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 2, 2, 'I said of laughter, "It is foolishness;" and of mirth, "What does it accomplish?"'),
  ('04c6c2dc-24dd-5a91-af02-916991c2aa6c', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 3, 3, 'I searched in my heart how to cheer my flesh with wine, my heart yet guiding me with wisdom, and how to lay hold of folly, until I might see what it was good for the sons of men that they should do under heaven all the days of their lives.'),
  ('21cb9ad6-5e45-590a-a128-61016e5c33cc', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 4, 4, 'I made myself great works. I built myself houses. I planted myself vineyards.'),
  ('8520e580-709b-5516-a7dd-d76865a14c54', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 5, 5, 'I made myself gardens and parks, and I planted trees in them of all kinds of fruit.'),
  ('a0f44942-e90c-5cb6-aea8-9b50a3bbc9bd', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 6, 6, 'I made myself pools of water, to water from it the forest where trees were reared.'),
  ('51c0761f-8dfa-51e7-a559-f6434194cdb2', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 7, 7, 'I bought male servants and female servants, and had servants born in my house. I also had great possessions of herds and flocks, above all who were before me in Jerusalem;'),
  ('b168982b-7f9f-51bf-ae6d-8fe1bd4dc06a', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 8, 8, 'I also gathered silver and gold for myself, and the treasure of kings and of the provinces. I got myself male and female singers, and the delights of the sons of men--musical instruments, and that of all sorts.'),
  ('3f9c82f0-3d18-5d2f-a7e9-c869c1bb8183', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 9, 9, 'So I was great, and increased more than all who were before me in Jerusalem. My wisdom also remained with me.'),
  ('6043abc6-903a-583d-a592-6651aa763f75', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 10, 10, 'Whatever my eyes desired, I didn''t keep from them. I didn''t withhold my heart from any joy, for my heart rejoiced because of all my labor, and this was my portion from all my labor.'),
  ('937c2b9f-8c0c-50b7-a053-16f857c8156b', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 11, 11, 'Then I looked at all the works that my hands had worked, and at the labor that I had labored to do; and behold, all was vanity and a chasing after wind, and there was no profit under the sun.'),
  ('7796099c-1ff2-5dfd-a39d-bca6e47ae259', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 12, 12, 'I turned myself to consider wisdom, madness, and folly: for what can the king''s successor do? Just that which has been done long ago.'),
  ('bb864366-a8d7-50d0-afad-18376a32758a', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 13, 13, 'Then I saw that wisdom excels folly, as far as light excels darkness.'),
  ('898b3d2a-4b94-5596-a3f3-a0bdca859f4e', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 14, 14, 'The wise man''s eyes are in his head, and the fool walks in darkness--and yet I perceived that one event happens to them all.'),
  ('978d1ac1-9287-51ef-aab0-8745b00607f8', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 15, 15, 'Then I said in my heart, "As it happens to the fool, so will it happen even to me; and why was I then more wise?" Then I said in my heart that this also is vanity.'),
  ('cd6911c5-de52-554a-ab91-cd8ecf128391', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 16, 16, 'For of the wise man, even as of the fool, there is no memory for ever, since in the days to come all will have been long forgotten. Indeed, the wise man must die just like the fool!'),
  ('aba8df9c-7d3d-56e0-abbd-fe918614d721', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 17, 17, 'So I hated life, because the work that is worked under the sun was grievous to me; for all is vanity and a chasing after wind.'),
  ('5f4535a5-04fc-5dd4-ad12-f93f04e92cf7', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 18, 18, 'I hated all my labor in which I labored under the sun, because I must leave it to the man who comes after me.'),
  ('bf704620-9957-567e-a64f-d93ee3614a61', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 19, 19, 'Who knows whether he will be a wise man or a fool? Yet he will have rule over all of my labor in which I have labored, and in which I have shown myself wise under the sun. This also is vanity.'),
  ('81361f0b-efd8-5bc9-a334-acbee85685ac', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 20, 20, 'Therefore I began to cause my heart to despair concerning all the labor in which I had labored under the sun.'),
  ('5a8009fe-21d2-5540-a52a-a8a45cf5e3de', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 21, 21, 'For there is a man whose labor is with wisdom, with knowledge, and with skillfulness; yet he shall leave it for his portion to a man who has not labored for it. This also is vanity and a great evil.'),
  ('ab913235-f641-5dc3-a178-7aec93af59fe', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 22, 22, 'For what has a man of all his labor, and of the striving of his heart, in which he labors under the sun?'),
  ('d6884c29-c166-50df-a682-0ab8279c7f14', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 23, 23, 'For all his days are sorrows, and his travail is grief; yes, even in the night his heart takes no rest. This also is vanity.'),
  ('a578429d-3298-5868-a9cf-a70047bc6f8a', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 24, 24, 'There is nothing better for a man than that he should eat and drink, and make his soul enjoy good in his labor. This also I saw, that it is from the hand of God.'),
  ('d62d6131-3f03-59b4-a855-7b059effb32f', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 25, 25, 'For who can eat, or who can have enjoyment, more than I?'),
  ('18c794cd-2d23-5aa3-af87-f00844830b80', 'dcd8a8d3-49f4-5983-a26a-4582f638a760', NULL, 26, 26, 'For to the man who pleases him, God gives wisdom, knowledge, and joy; but to the sinner he gives travail, to gather and to heap up, that he may give to him who pleases God. This also is vanity and a chasing after wind.'),
  ('2c58f592-3577-5492-a108-2ef201b68db8', 'b9924e74-be92-5ba8-a1a0-0b5291fb5f9b', NULL, 1, 1, 'For everything there is a season, and a time for every purpose under heaven:')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('bc45f4a1-faad-58aa-a33b-b4c726be02fa', 'b9924e74-be92-5ba8-a1a0-0b5291fb5f9b', NULL, 2, 2, 'a time to be born, and a time to die; a time to plant, and a time to pluck up that which is planted;'),
  ('279a21b5-11ff-5680-a0f6-08ba4b516ed9', 'b9924e74-be92-5ba8-a1a0-0b5291fb5f9b', NULL, 3, 3, 'a time to kill, and a time to heal; a time to break down, and a time to build up;'),
  ('a0c30897-0bf5-5412-a9dd-8db32858c21e', 'b9924e74-be92-5ba8-a1a0-0b5291fb5f9b', NULL, 4, 4, 'a time to weep, and a time to laugh; a time to mourn, and a time to dance;'),
  ('9c82254c-304d-576f-a913-6a91ee579269', 'b9924e74-be92-5ba8-a1a0-0b5291fb5f9b', NULL, 5, 5, 'a time to cast away stones, and a time to gather stones together; a time to embrace, and a time to refrain from embracing;'),
  ('91a21495-ccd8-5286-a763-407967e0766b', 'b9924e74-be92-5ba8-a1a0-0b5291fb5f9b', NULL, 6, 6, 'a time to seek, and a time to lose; a time to keep, and a time to cast away;'),
  ('ea52ca85-31e2-57ea-ab32-f613f3808321', 'b9924e74-be92-5ba8-a1a0-0b5291fb5f9b', NULL, 7, 7, 'a time to tear, and a time to sew; a time to keep silence, and a time to speak;'),
  ('d98cf02d-d987-58a7-adb5-7a6f71bf9c7e', 'b9924e74-be92-5ba8-a1a0-0b5291fb5f9b', NULL, 8, 8, 'a time to love, and a time to hate; a time for war, and a time for peace.'),
  ('47f5a286-3cbf-5878-a1b8-849ed14f031e', 'b9924e74-be92-5ba8-a1a0-0b5291fb5f9b', NULL, 9, 9, 'What profit has he who works in that in which he labors?'),
  ('69d64684-fb70-510b-a1b0-36564989e1ae', 'b9924e74-be92-5ba8-a1a0-0b5291fb5f9b', NULL, 10, 10, 'I have seen the burden which God has given to the sons of men to be afflicted with.'),
  ('49b761be-b6c5-5dfa-a369-df8802daedad', 'b9924e74-be92-5ba8-a1a0-0b5291fb5f9b', NULL, 11, 11, 'He has made everything beautiful in its time. He has also set eternity in their hearts, yet so that man can''t find out the work that God has done from the beginning even to the end.'),
  ('0d5d27d9-83ec-596f-a9eb-a7a0ccaba58b', 'b9924e74-be92-5ba8-a1a0-0b5291fb5f9b', NULL, 12, 12, 'I know that there is nothing better for them than to rejoice, and to do good as long as they live.'),
  ('0e9f7e68-93ae-50af-a6e7-ccb3ca1416b9', 'b9924e74-be92-5ba8-a1a0-0b5291fb5f9b', NULL, 13, 13, 'Also that every man should eat and drink, and enjoy good in all his labor, is the gift of God.'),
  ('26d903bd-afc2-58d5-a9de-668399a41503', 'b9924e74-be92-5ba8-a1a0-0b5291fb5f9b', NULL, 14, 14, 'I know that whatever God does, it shall be forever. Nothing can be added to it, nor anything taken from it; and God has done it, that men should fear before him.'),
  ('2f5c3fe4-8951-5f1e-a33c-688266645756', 'b9924e74-be92-5ba8-a1a0-0b5291fb5f9b', NULL, 15, 15, 'That which is has been long ago, and that which is to be has been long ago: and God seeks again that which is passed away.'),
  ('cb3b74a3-cc77-520f-a070-45085e0cc492', 'b9924e74-be92-5ba8-a1a0-0b5291fb5f9b', NULL, 16, 16, 'Moreover I saw under the sun, in the place of justice, that wickedness was there; and in the place of righteousness, that wickedness was there.'),
  ('db2bf1d9-7cd3-5013-a9ad-c0cc581ba623', 'b9924e74-be92-5ba8-a1a0-0b5291fb5f9b', NULL, 17, 17, 'I said in my heart, "God will judge the righteous and the wicked; for there is a time there for every purpose and for every work."'),
  ('f52d32ee-0ade-5e1a-a7ab-4deb00f4b273', 'b9924e74-be92-5ba8-a1a0-0b5291fb5f9b', NULL, 18, 18, 'I said in my heart, "As for the sons of men, God tests them, so that they may see that they themselves are like animals.'),
  ('5b0e6e11-0de2-5d6e-aea6-e05d61a8b23b', 'b9924e74-be92-5ba8-a1a0-0b5291fb5f9b', NULL, 19, 19, 'For that which happens to the sons of men happens to animals. Even one thing happens to them. As the one dies, so the other dies. Yes, they have all one breath; and man has no advantage over the animals: for all is vanity.'),
  ('82b28c32-f57f-5093-ab92-bfbd7a783836', 'b9924e74-be92-5ba8-a1a0-0b5291fb5f9b', NULL, 20, 20, 'All go to one place. All are from the dust, and all turn to dust again.'),
  ('d5da8a31-cc01-5ce7-af2e-5dc8316491ae', 'b9924e74-be92-5ba8-a1a0-0b5291fb5f9b', NULL, 21, 21, 'Who knows the spirit of man, whether it goes upward, and the spirit of the animal, whether it goes downward to the earth?"'),
  ('d2a31be3-ce45-5f88-a13c-d59ce9ca032c', 'b9924e74-be92-5ba8-a1a0-0b5291fb5f9b', NULL, 22, 22, 'Therefore I saw that there is nothing better, than that a man should rejoice in his works; for that is his portion: for who can bring him to see what will be after him?'),
  ('45bb7d0a-63a5-56ce-a3cf-c7d5e2d97c84', 'fac4beb9-d0f8-59e7-a716-c7550c8e6e15', NULL, 1, 1, 'Then I returned and saw all the oppressions that are done under the sun: and behold, the tears of those who were oppressed, and they had no comforter; and on the side of their oppressors there was power; but they had no comforter.'),
  ('421d1db7-25d2-5d4c-a3f1-79494b4d9815', 'fac4beb9-d0f8-59e7-a716-c7550c8e6e15', NULL, 2, 2, 'Therefore I praised the dead who have been long dead more than the living who are yet alive.'),
  ('3386c12a-6d17-5dc4-aa48-96b4c3e38f0e', 'fac4beb9-d0f8-59e7-a716-c7550c8e6e15', NULL, 3, 3, 'Yes, better than them both is him who has not yet been, who has not seen the evil work that is done under the sun.'),
  ('5b23f9f3-2cf1-5173-a0d4-6a9ab74a3ce8', 'fac4beb9-d0f8-59e7-a716-c7550c8e6e15', NULL, 4, 4, 'Then I saw all the labor and achievement that is the envy of a man''s neighbor. This also is vanity and a striving after wind.'),
  ('9fcb8aaf-34f2-5ce8-a9d2-c86fa3a77dcd', 'fac4beb9-d0f8-59e7-a716-c7550c8e6e15', NULL, 5, 5, 'The fool folds his hands together and ruins himself.'),
  ('f52ee243-93b4-589b-a725-a7f4ce59cbeb', 'fac4beb9-d0f8-59e7-a716-c7550c8e6e15', NULL, 6, 6, 'Better is a handful, with quietness, than two handfuls with labor and chasing after wind.'),
  ('df85a198-59ff-55cb-a865-f8cdf85949ad', 'fac4beb9-d0f8-59e7-a716-c7550c8e6e15', NULL, 7, 7, 'Then I returned and saw vanity under the sun.'),
  ('61b17310-8dac-52dd-a69f-74d020fb566d', 'fac4beb9-d0f8-59e7-a716-c7550c8e6e15', NULL, 8, 8, 'There is one who is alone, and he has neither son nor brother. There is no end to all of his labor, neither are his eyes satisfied with wealth. "For whom then, do I labor, and deprive my soul of enjoyment?" This also is vanity. Yes, it is a miserable business.'),
  ('4c052993-1645-5de5-ae76-3e1277e68c08', 'fac4beb9-d0f8-59e7-a716-c7550c8e6e15', NULL, 9, 9, 'Two are better than one, because they have a good reward for their labor.'),
  ('7a46ecdb-fb68-5aa9-a32c-e2b2398ac729', 'fac4beb9-d0f8-59e7-a716-c7550c8e6e15', NULL, 10, 10, 'For if they fall, the one will lift up his fellow; but woe to him who is alone when he falls, and doesn''t have another to lift him up.'),
  ('878fb502-2722-5055-afd3-c7f69212694c', 'fac4beb9-d0f8-59e7-a716-c7550c8e6e15', NULL, 11, 11, 'Again, if two lie together, then they have warmth; but how can one keep warm alone?'),
  ('e1bffa65-5066-5460-a7c6-b69650613f17', 'fac4beb9-d0f8-59e7-a716-c7550c8e6e15', NULL, 12, 12, 'If a man prevails against one who is alone, two shall withstand him; and a threefold cord is not quickly broken.'),
  ('fa43f371-94e8-5877-a44e-83f730c2d7b5', 'fac4beb9-d0f8-59e7-a716-c7550c8e6e15', NULL, 13, 13, 'Better is a poor and wise youth than an old and foolish king who doesn''t know how to receive admonition any more.'),
  ('1e863058-0606-5680-ab6e-2e40461ab860', 'fac4beb9-d0f8-59e7-a716-c7550c8e6e15', NULL, 14, 14, 'For out of prison he came forth to be king; yes, even in his kingdom he was born poor.'),
  ('a6564675-512b-51ab-a76d-835c0808ad60', 'fac4beb9-d0f8-59e7-a716-c7550c8e6e15', NULL, 15, 15, 'I saw all the living who walk under the sun, that they were with the youth, the other, who succeeded him.'),
  ('622a72b8-fcfb-5090-a009-d671cb82ebcd', 'fac4beb9-d0f8-59e7-a716-c7550c8e6e15', NULL, 16, 16, 'There was no end of all the people, even of all them over whom he was--yet those who come after shall not rejoice in him. Surely this also is vanity and a chasing after wind.'),
  ('2721d67a-f7b1-5448-a688-b72874231c01', '6417cfaf-b228-5e79-ab1a-213974758b54', NULL, 1, 1, 'Guard your steps when you go to God''s house; for to draw near to listen is better than to give the sacrifice of fools, for they don''t know that they do evil.'),
  ('bf219b90-5fe8-555e-a1ae-fe2cdf32db78', '6417cfaf-b228-5e79-ab1a-213974758b54', NULL, 2, 2, 'Don''t be rash with your mouth, and don''t let your heart be hasty to utter anything before God; for God is in heaven, and you on earth. Therefore let your words be few.'),
  ('4b608931-d17d-5c12-ae35-4775ad994b1a', '6417cfaf-b228-5e79-ab1a-213974758b54', NULL, 3, 3, 'For as a dream comes with a multitude of cares, so a fool''s speech with a multitude of words.'),
  ('22baef95-6227-5f18-a4a0-0d52f3aa12c9', '6417cfaf-b228-5e79-ab1a-213974758b54', NULL, 4, 4, 'When you vow a vow to God, don''t defer to pay it; for he has no pleasure in fools. Pay that which you vow.'),
  ('065e0bfe-d309-553b-adb2-0a7a385ce0c1', '6417cfaf-b228-5e79-ab1a-213974758b54', NULL, 5, 5, 'It is better that you should not vow, than that you should vow and not pay.'),
  ('6850f7b8-2bec-5352-a4f9-6f68d041e82f', '6417cfaf-b228-5e79-ab1a-213974758b54', NULL, 6, 6, 'Don''t allow your mouth to lead you into sin. Don''t protest before the messenger that this was a mistake. Why should God be angry at your voice, and destroy the work of your hands?'),
  ('c3c31951-c57c-5a20-a656-75cb5afc7a74', '6417cfaf-b228-5e79-ab1a-213974758b54', NULL, 7, 7, 'For in the multitude of dreams there are vanities, as well as in many words: but you must fear God.'),
  ('228700bb-4ee7-5947-a6a9-4ff9c01cbfbf', '6417cfaf-b228-5e79-ab1a-213974758b54', NULL, 8, 8, 'If you see the oppression of the poor, and the violent taking away of justice and righteousness in a district, don''t marvel at the matter: for one official is eyed by a higher one; and there are officials over them.'),
  ('6d87b71f-6355-525a-a65e-25ff607ed70f', '6417cfaf-b228-5e79-ab1a-213974758b54', NULL, 9, 9, 'Moreover the profit of the earth is for all. The king profits from the field.'),
  ('f3573c5d-b1a1-5b7b-a21c-84ecfdae8596', '6417cfaf-b228-5e79-ab1a-213974758b54', NULL, 10, 10, 'He who loves silver shall not be satisfied with silver; nor he who loves abundance, with increase: this also is vanity.'),
  ('c34b1f45-9d48-5439-a481-9d43bf63bdb9', '6417cfaf-b228-5e79-ab1a-213974758b54', NULL, 11, 11, 'When goods increase, those who eat them are increased; and what advantage is there to its owner, except to feast on them with his eyes?'),
  ('98959700-d9c6-5b11-a0cb-2aefbd5ab0c1', '6417cfaf-b228-5e79-ab1a-213974758b54', NULL, 12, 12, 'The sleep of a laboring man is sweet, whether he eats little or much; but the abundance of the rich will not allow him to sleep.'),
  ('884c52ee-913a-503b-a4a3-bc8d75c4fd87', '6417cfaf-b228-5e79-ab1a-213974758b54', NULL, 13, 13, 'There is a grievous evil which I have seen under the sun: wealth kept by its owner to his harm.'),
  ('e84906a8-a578-5ae0-a885-733a3d48f155', '6417cfaf-b228-5e79-ab1a-213974758b54', NULL, 14, 14, 'Those riches perish by misfortune, and if he has fathered a son, there is nothing in his hand.'),
  ('8b3e526f-1a1f-5d87-adcb-36dc852ac5dc', '6417cfaf-b228-5e79-ab1a-213974758b54', NULL, 15, 15, 'As he came forth from his mother''s womb, naked shall he go again as he came, and shall take nothing for his labor, which he may carry away in his hand.'),
  ('c65dac40-f7cc-5f97-a6d1-49d54d0b8ea7', '6417cfaf-b228-5e79-ab1a-213974758b54', NULL, 16, 16, 'This also is a grievous evil, that in all points as he came, so shall he go. And what profit does he have who labors for the wind?'),
  ('04304fb4-cc65-59c9-a3e1-5e70b40072cd', '6417cfaf-b228-5e79-ab1a-213974758b54', NULL, 17, 17, 'All his days he also eats in darkness, he is frustrated, and has sickness and wrath.'),
  ('0248bfdf-af98-5a50-a306-11cc992bf840', '6417cfaf-b228-5e79-ab1a-213974758b54', NULL, 18, 18, 'Behold, that which I have seen to be good and proper is for one to eat and to drink, and to enjoy good in all his labor, in which he labors under the sun, all the days of his life which God has given him; for this is his portion.'),
  ('080f454b-58d4-5db0-aa9f-186f6b98c3a9', '6417cfaf-b228-5e79-ab1a-213974758b54', NULL, 19, 19, 'Every man also to whom God has given riches and wealth, and has given him power to eat of it, and to take his portion, and to rejoice in his labor--this is the gift of God.'),
  ('c55dc58f-c642-5a6d-a755-81406f4bb2c4', '6417cfaf-b228-5e79-ab1a-213974758b54', NULL, 20, 20, 'For he shall not often reflect on the days of his life; because God occupies him with the joy of his heart.'),
  ('ed327cdd-7405-5f21-ab0a-f7689e4dc3f8', '3d5ed1b4-4872-5d57-a8c0-d0f7127df7df', NULL, 1, 1, 'There is an evil which I have seen under the sun, and it is heavy on men:'),
  ('99218790-041a-5c47-a672-fb44484f2537', '3d5ed1b4-4872-5d57-a8c0-d0f7127df7df', NULL, 2, 2, 'a man to whom God gives riches, wealth, and honor, so that he lacks nothing for his soul of all that he desires, yet God gives him no power to eat of it, but an alien eats it. This is vanity, and it is an evil disease.'),
  ('60e21974-4a49-5fc4-a717-577bb7e1e185', '3d5ed1b4-4872-5d57-a8c0-d0f7127df7df', NULL, 3, 3, 'If a man fathers a hundred children, and lives many years, so that the days of his years are many, but his soul is not filled with good, and moreover he has no burial; I say, that a stillborn child is better than he:'),
  ('75386d6f-1381-51f6-a726-1189ee6b0ea9', '3d5ed1b4-4872-5d57-a8c0-d0f7127df7df', NULL, 4, 4, 'for it comes in vanity, and departs in darkness, and its name is covered with darkness.'),
  ('16370391-a8f4-5332-af0b-1c99d7fdbd96', '3d5ed1b4-4872-5d57-a8c0-d0f7127df7df', NULL, 5, 5, 'Moreover it has not seen the sun nor known it. This has rest rather than the other.'),
  ('76b46759-c2a1-545a-a214-1c7cdf4d410e', '3d5ed1b4-4872-5d57-a8c0-d0f7127df7df', NULL, 6, 6, 'Yes, though he live a thousand years twice told, and yet fails to enjoy good, don''t all go to one place?'),
  ('cf4927fa-855d-579e-aa28-458f811a17c4', '3d5ed1b4-4872-5d57-a8c0-d0f7127df7df', NULL, 7, 7, 'All the labor of man is for his mouth, and yet the appetite is not filled.'),
  ('e5413161-7351-5dc1-a217-a95f687e6526', '3d5ed1b4-4872-5d57-a8c0-d0f7127df7df', NULL, 8, 8, 'For what advantage has the wise more than the fool? What has the poor man, that knows how to walk before the living?'),
  ('12b7bf4c-6d58-5f7d-a466-4835123fd99e', '3d5ed1b4-4872-5d57-a8c0-d0f7127df7df', NULL, 9, 9, 'Better is the sight of the eyes than the wandering of the desire. This also is vanity and a chasing after wind.'),
  ('8e62d734-e998-51b3-a4b7-f3e9c0123f39', '3d5ed1b4-4872-5d57-a8c0-d0f7127df7df', NULL, 10, 10, 'Whatever has been, its name was given long ago; and it is known what man is; neither can he contend with him who is mightier than he.'),
  ('47760b2c-d14a-587e-ab8f-fcc7485a4690', '3d5ed1b4-4872-5d57-a8c0-d0f7127df7df', NULL, 11, 11, 'For there are many words that create vanity. What does that profit man?'),
  ('a8e3d466-6e5f-5a3d-ad56-4b567fd6696e', '3d5ed1b4-4872-5d57-a8c0-d0f7127df7df', NULL, 12, 12, 'For who knows what is good for man in life, all the days of his vain life which he spends like a shadow? For who can tell a man what will be after him under the sun?'),
  ('5de43b73-b022-5940-a03f-5230e30cf4c1', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 1, 1, 'A good name is better than fine perfume; and the day of death better than the day of one''s birth.'),
  ('62add4e1-e4f3-5a9a-a41a-e67996f6d75b', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 2, 2, 'It is better to go to the house of mourning than to go to the house of feasting: for that is the end of all men, and the living should take this to heart.'),
  ('41d94b67-1de8-5317-a0d4-2385b0250b24', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 3, 3, 'Sorrow is better than laughter; for by the sadness of the face the heart is made good.'),
  ('b8df3725-f134-56b1-aa8c-98a04f8dfb0d', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 4, 4, 'The heart of the wise is in the house of mourning; but the heart of fools is in the house of mirth.'),
  ('38698e5c-7512-5b74-a215-6d629a3952a0', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 5, 5, 'It is better to hear the rebuke of the wise, than for a man to hear the song of fools.'),
  ('23a31c3d-d13b-51bb-acec-be467eb3475c', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 6, 6, 'For as the crackling of thorns under a pot, so is the laughter of the fool. This also is vanity.'),
  ('1c23524a-8484-5408-a68c-d8b404a8f3c6', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 7, 7, 'Surely extortion makes the wise man foolish; and a bribe destroys the understanding.'),
  ('c9b38934-48af-524c-a3b9-ede3060ce411', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 8, 8, 'Better is the end of a thing than its beginning. The patient in spirit is better than the proud in spirit.'),
  ('1091e91b-5693-543c-a94c-3cedc846908f', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 9, 9, 'Don''t be hasty in your spirit to be angry, for anger rests in the bosom of fools.'),
  ('a91a8c0a-e1d0-53fc-a6f3-c1c03b7b5afc', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 10, 10, 'Don''t say, "Why were the former days better than these?" For you do not ask wisely about this.'),
  ('6edf3865-d757-500f-aa99-91d34b2a7e9d', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 11, 11, 'Wisdom is as good as an inheritance. Yes, it is more excellent for those who see the sun.'),
  ('b429a7b5-a2f8-5e27-acdc-0e9c877c59af', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 12, 12, 'For wisdom is a defense, even as money is a defense; but the excellency of knowledge is that wisdom preserves the life of him who has it.'),
  ('48428225-a00d-5b2d-a8e6-1b69de85cd7c', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 13, 13, 'Consider the work of God, for who can make that straight, which he has made crooked?'),
  ('2efdebd7-f0d3-5679-a14e-2b6c83df4bfa', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 14, 14, 'In the day of prosperity be joyful, and in the day of adversity consider; yes, God has made the one side by side with the other, to the end that man should not find out anything after him.'),
  ('b6eb1742-319d-5396-abe2-c57b9f98af88', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 15, 15, 'All this have I seen in my days of vanity: there is a righteous man who perishes in his righteousness, and there is a wicked man who lives long in his evildoing.'),
  ('bc4b753e-585a-519a-aa2a-ff1ec50353c0', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 16, 16, 'Don''t be overly righteous, neither make yourself overly wise. Why should you destroy yourself?'),
  ('262ad8ca-4fc7-5739-a91a-a79a7b385eac', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 17, 17, 'Don''t be too wicked, neither be foolish. Why should you die before your time?'),
  ('0a9e81dd-ecc2-5171-a9a6-4326cf9d5e68', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 18, 18, 'It is good that you should take hold of this. Yes, also from that don''t withdraw your hand; for he who fears God will come forth from them all.'),
  ('5c43f613-2ac9-5612-a02b-9252e9299da7', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 19, 19, 'Wisdom is a strength to the wise man more than ten rulers who are in a city.'),
  ('57d25300-f142-549b-a95a-21be800c5797', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 20, 20, 'Surely there is not a righteous man on earth, who does good and doesn''t sin.'),
  ('e5ea2645-b8e0-5633-a55f-f0db8f2aed68', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 21, 21, 'Also don''t take heed to all words that are spoken, lest you hear your servant curse you;'),
  ('7dd6c222-7148-5c75-a082-445ec5addbc0', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 22, 22, 'for often your own heart knows that you yourself have likewise cursed others.'),
  ('1976e1f3-1122-5575-a33c-0e5bb24dc480', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 23, 23, 'All this have I proved in wisdom. I said, "I will be wise;" but it was far from me.'),
  ('1f6152e9-329b-5cd0-aa0e-2e2e51baf73f', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 24, 24, 'That which is, is far off and exceedingly deep. Who can find it out?'),
  ('e173fb0b-10a9-562c-ae48-21374a7b8659', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 25, 25, 'I turned around, and my heart sought to know and to search out, and to seek wisdom and the scheme of things, and to know that wickedness is stupidity, and that foolishness is madness.'),
  ('f53917a1-eebc-5d7a-a18b-5fcfe94cdfc9', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 26, 26, 'I find more bitter than death the woman whose heart is snares and traps, whose hands are chains. Whoever pleases God shall escape from her; but the sinner will be ensnared by her.'),
  ('e060d6cc-c260-5000-a057-7845562884f6', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 27, 27, '"Behold, I have found this," says the Preacher, "one to another, to find out the scheme;'),
  ('ff2c732e-d8f5-58a3-a396-0c53a04e445c', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 28, 28, 'which my soul still seeks; but I have not found. One man among a thousand have I found; but I have not found a woman among all those.'),
  ('de3ea48d-bcb0-567e-a1c4-75f27af51d1d', 'e6c1670c-ff9b-5107-a7d6-91fb984f796e', NULL, 29, 29, 'Behold, this only have I found: that God made man upright; but they search for many schemes."'),
  ('06e59dba-c249-5fa3-af2a-b295c1f6c1e6', 'b760a2e3-d6f5-580e-afef-077cf2e37aac', NULL, 1, 1, 'Who is like the wise man? And who knows the interpretation of a thing? A man''s wisdom makes his face shine, and the hardness of his face is changed.'),
  ('4ba08357-f412-575a-aa6e-99de4a3e944e', 'b760a2e3-d6f5-580e-afef-077cf2e37aac', NULL, 2, 2, 'I say, "Keep the king''s command!" because of the oath to God.'),
  ('cad0b1d4-4451-5b2d-a816-ea46a846849d', 'b760a2e3-d6f5-580e-afef-077cf2e37aac', NULL, 3, 3, 'Don''t be hasty to go out of his presence. Don''t persist in an evil thing, for he does whatever pleases him,'),
  ('3f70b1bd-4223-51f8-a0f3-46d2fb16ac8a', 'b760a2e3-d6f5-580e-afef-077cf2e37aac', NULL, 4, 4, 'for the king''s word is supreme. Who can say to him, "What are you doing?"'),
  ('faa4fe05-8a0a-544f-a5fc-d9b54900757d', 'b760a2e3-d6f5-580e-afef-077cf2e37aac', NULL, 5, 5, 'Whoever keeps the commandment shall not come to harm, and his wise heart will know the time and procedure.'),
  ('54220298-e54c-56d3-a264-503e1eff8266', 'b760a2e3-d6f5-580e-afef-077cf2e37aac', NULL, 6, 6, 'For there is a time and procedure for every purpose, although the misery of man is heavy on him.'),
  ('0327fca8-429f-5e9a-a44c-3a8f31874ab8', 'b760a2e3-d6f5-580e-afef-077cf2e37aac', NULL, 7, 7, 'For he doesn''t know that which will be; for who can tell him how it will be?'),
  ('a6b38878-83b2-5dfb-a611-942b029f905a', 'b760a2e3-d6f5-580e-afef-077cf2e37aac', NULL, 8, 8, 'There is no man who has power over the spirit to contain the spirit; neither does he have power over the day of death. There is no discharge in war; neither shall wickedness deliver those who practice it.'),
  ('bc28fbf0-8fa5-5fa5-ac57-6eb757e6af5c', 'b760a2e3-d6f5-580e-afef-077cf2e37aac', NULL, 9, 9, 'All this have I seen, and applied my mind to every work that is done under the sun. There is a time in which one man has power over another to his hurt.'),
  ('3c404765-3fe6-5db9-a046-c5074025aad8', 'b760a2e3-d6f5-580e-afef-077cf2e37aac', NULL, 10, 10, 'So I saw the wicked buried. Indeed they came also from holiness. They went and were forgotten in the city where they did this. This also is vanity.'),
  ('b7d7af58-bed6-5ac8-af5a-e28d5c5ade3f', 'b760a2e3-d6f5-580e-afef-077cf2e37aac', NULL, 11, 11, 'Because sentence against an evil work is not executed speedily, therefore the heart of the sons of men is fully set in them to do evil.'),
  ('bb7bf328-747b-5d51-a2af-ee0c9da6168e', 'b760a2e3-d6f5-580e-afef-077cf2e37aac', NULL, 12, 12, 'Though a sinner commits crimes a hundred times, and lives long, yet surely I know that it will be better with those who fear God, who are reverent before him.'),
  ('c762a880-0080-5f97-a243-0ee1e4b6649d', 'b760a2e3-d6f5-580e-afef-077cf2e37aac', NULL, 13, 13, 'But it shall not be well with the wicked, neither shall he lengthen days like a shadow; because he doesn''t fear God.'),
  ('590c50cf-b978-5b28-a33e-ca2f410e001d', 'b760a2e3-d6f5-580e-afef-077cf2e37aac', NULL, 14, 14, 'There is a vanity which is done on the earth, that there are righteous men to whom it happens according to the work of the wicked. Again, there are wicked men to whom it happens according to the work of the righteous. I said that this also is vanity.'),
  ('f433da22-00ac-581d-ad0b-06e2d58eb0c3', 'b760a2e3-d6f5-580e-afef-077cf2e37aac', NULL, 15, 15, 'Then I commended mirth, because a man has no better thing under the sun, than to eat, and to drink, and to be joyful: for that will accompany him in his labor all the days of his life which God has given him under the sun.'),
  ('d95778e4-4630-52a0-a8d7-734ef67591bb', 'b760a2e3-d6f5-580e-afef-077cf2e37aac', NULL, 16, 16, 'When I applied my heart to know wisdom, and to see the business that is done on the earth (for also there is that neither day nor night sees sleep with his eyes),'),
  ('747e384c-eaf4-563c-a6dd-7733d728b5a4', 'b760a2e3-d6f5-580e-afef-077cf2e37aac', NULL, 17, 17, 'then I saw all the work of God, that man can''t find out the work that is done under the sun, because however much a man labors to seek it out, yet he won''t find it. Yes even though a wise man thinks he can comprehend it, he won''t be able to find it.'),
  ('cc848282-f11d-5b13-a803-fb4b670eb678', '68939def-9fb6-5ff4-a634-514e0396bfe7', NULL, 1, 1, 'For all this I laid to my heart, even to explore all this: that the righteous, and the wise, and their works, are in the hand of God; whether it is love or hatred, man doesn''t know it; all is before them.'),
  ('2f09b1b7-0f58-5105-aca7-6f9dc5ec613a', '68939def-9fb6-5ff4-a634-514e0396bfe7', NULL, 2, 2, 'All things come alike to all. There is one event to the righteous and to the wicked; to the good, to the clean, to the unclean, to him who sacrifices, and to him who doesn''t sacrifice. As is the good, so is the sinner; he who takes an oath, as he who fears an oath.'),
  ('bca7d8aa-8f31-5221-a83b-0fb259d74ca8', '68939def-9fb6-5ff4-a634-514e0396bfe7', NULL, 3, 3, 'This is an evil in all that is done under the sun, that there is one event to all: yes also, the heart of the sons of men is full of evil, and madness is in their heart while they live, and after that they go to the dead.'),
  ('d730c921-4eaf-503c-a2cd-6ddc0bbba84a', '68939def-9fb6-5ff4-a634-514e0396bfe7', NULL, 4, 4, 'For to him who is joined with all the living there is hope; for a living dog is better than a dead lion.'),
  ('9418c1ac-9ef2-5e80-a46f-48aea105dd40', '68939def-9fb6-5ff4-a634-514e0396bfe7', NULL, 5, 5, 'For the living know that they will die, but the dead don''t know anything, neither do they have any more a reward; for the memory of them is forgotten.'),
  ('012db93e-7f0f-533b-a627-34dcc5b1cfeb', '68939def-9fb6-5ff4-a634-514e0396bfe7', NULL, 6, 6, 'Also their love, their hatred, and their envy has perished long ago; neither have they any more a portion forever in anything that is done under the sun.'),
  ('4963d810-3574-5823-a625-47c0eabd1f69', '68939def-9fb6-5ff4-a634-514e0396bfe7', NULL, 7, 7, 'Go your way--eat your bread with joy, and drink your wine with a merry heart; for God has already accepted your works.'),
  ('257aef34-b278-54ee-ab8e-16d0224da9f1', '68939def-9fb6-5ff4-a634-514e0396bfe7', NULL, 8, 8, 'Let your garments be always white, and don''t let your head lack oil.'),
  ('457c4a20-c6ef-5536-a3bd-e7b47a9a555f', '68939def-9fb6-5ff4-a634-514e0396bfe7', NULL, 9, 9, 'Live joyfully with the wife whom you love all the days of your life of vanity, which he has given you under the sun, all your days of vanity: for that is your portion in life, and in your labor in which you labor under the sun.'),
  ('5a5547ba-a344-56a2-a903-24b92e5ff85b', '68939def-9fb6-5ff4-a634-514e0396bfe7', NULL, 10, 10, 'Whatever your hand finds to do, do it with your might; for there is no work, nor device, nor knowledge, nor wisdom, in Sheol, where you are going.'),
  ('981ce39f-3459-5ec8-a7cf-6ef85ed6fcaf', '68939def-9fb6-5ff4-a634-514e0396bfe7', NULL, 11, 11, 'I returned, and saw under the sun, that the race is not to the swift, nor the battle to the strong, neither yet bread to the wise, nor yet riches to men of understanding, nor yet favor to men of skill; but time and chance happen to them all.'),
  ('d453b5b5-c1a5-56db-a33d-38caa2b9b81d', '68939def-9fb6-5ff4-a634-514e0396bfe7', NULL, 12, 12, 'For man also doesn''t know his time. As the fish that are taken in an evil net, and as the birds that are caught in the snare, even so are the sons of men snared in an evil time, when it falls suddenly on them.'),
  ('9811c30d-9148-5a0d-a33f-a83dc06fe8e2', '68939def-9fb6-5ff4-a634-514e0396bfe7', NULL, 13, 13, 'I have also seen wisdom under the sun in this way, and it seemed great to me.'),
  ('49e5df33-8dfa-54d3-a1a6-b180d8278a1c', '68939def-9fb6-5ff4-a634-514e0396bfe7', NULL, 14, 14, 'There was a little city, and few men within it; and a great king came against it, besieged it, and built great bulwarks against it.'),
  ('28521eb5-b809-5458-afe4-04cb09c3006f', '68939def-9fb6-5ff4-a634-514e0396bfe7', NULL, 15, 15, 'Now a poor wise man was found in it, and he by his wisdom delivered the city; yet no man remembered that same poor man.'),
  ('8974cd01-9952-5363-ae45-402c9b5dcb07', '68939def-9fb6-5ff4-a634-514e0396bfe7', NULL, 16, 16, 'Then I said, "Wisdom is better than strength." Nevertheless the poor man''s wisdom is despised, and his words are not heard.'),
  ('7043c963-bf67-5c93-ae37-cad1797f285f', '68939def-9fb6-5ff4-a634-514e0396bfe7', NULL, 17, 17, 'The words of the wise heard in quiet are better than the cry of him who rules among fools.'),
  ('b19858c4-4391-5f57-a52d-d83da366dd58', '68939def-9fb6-5ff4-a634-514e0396bfe7', NULL, 18, 18, 'Wisdom is better than weapons of war; but one sinner destroys much good.'),
  ('3d97c02e-72b1-5fb5-a18c-41ad1b732682', 'a6ff7cc0-2afe-51c5-ad19-d9ef8cddc686', NULL, 1, 1, 'Dead flies cause the oil of the perfumer to send forth an evil odor; so does a little folly outweigh wisdom and honor.'),
  ('fae234ac-5090-57c7-a421-6a41258f969b', 'a6ff7cc0-2afe-51c5-ad19-d9ef8cddc686', NULL, 2, 2, 'A wise man''s heart is at his right hand, but a fool''s heart at his left.'),
  ('92b22166-982d-5e09-a22a-5a329e762792', 'a6ff7cc0-2afe-51c5-ad19-d9ef8cddc686', NULL, 3, 3, 'Yes also, when the fool walks by the way, his understanding fails him, and he says to everyone that he is a fool.'),
  ('230d7cf4-4d4a-51a8-a9b2-365d5ffed6c8', 'a6ff7cc0-2afe-51c5-ad19-d9ef8cddc686', NULL, 4, 4, 'If the spirit of the ruler rises up against you, don''t leave your place; for gentleness lays great offenses to rest.'),
  ('e3c594ee-00f1-54ef-a4a2-58d36bc1b9e6', 'a6ff7cc0-2afe-51c5-ad19-d9ef8cddc686', NULL, 5, 5, 'There is an evil which I have seen under the sun, the sort of error which proceeds from the ruler.'),
  ('69abdaa4-aee3-56db-a82b-ce15b3f2d8b5', 'a6ff7cc0-2afe-51c5-ad19-d9ef8cddc686', NULL, 6, 6, 'Folly is set in great dignity, and the rich sit in a low place.'),
  ('66a1128b-3084-585a-ae64-25529841e6f7', 'a6ff7cc0-2afe-51c5-ad19-d9ef8cddc686', NULL, 7, 7, 'I have seen servants on horses, and princes walking like servants on the earth.'),
  ('429eb8e6-c520-5424-a5bd-e650bbbd332d', 'a6ff7cc0-2afe-51c5-ad19-d9ef8cddc686', NULL, 8, 8, 'He who digs a pit may fall into it; and whoever breaks through a wall may be bitten by a snake.'),
  ('dba59df8-f975-5522-a3e7-5834cbec4ffb', 'a6ff7cc0-2afe-51c5-ad19-d9ef8cddc686', NULL, 9, 9, 'Whoever carves out stones may be injured by them. Whoever splits wood may be endangered thereby.'),
  ('af196487-6602-5a83-a198-da0495cd1079', 'a6ff7cc0-2afe-51c5-ad19-d9ef8cddc686', NULL, 10, 10, 'If the axe is blunt, and one doesn''t sharpen the edge, then he must use more strength; but skill brings success.'),
  ('b3c77fbc-c7f0-5d4d-a3da-421b32739119', 'a6ff7cc0-2afe-51c5-ad19-d9ef8cddc686', NULL, 11, 11, 'If the snake bites before it is charmed, then is there no profit for the charmer''s tongue.'),
  ('5afafc68-1669-5059-ae6e-9aae951635b6', 'a6ff7cc0-2afe-51c5-ad19-d9ef8cddc686', NULL, 12, 12, 'The words of a wise man''s mouth are gracious; but a fool is swallowed by his own lips.'),
  ('3d3204b6-d797-5030-a376-4565441482ba', 'a6ff7cc0-2afe-51c5-ad19-d9ef8cddc686', NULL, 13, 13, 'The beginning of the words of his mouth is foolishness; and the end of his talk is mischievous madness.'),
  ('2d16e3d2-dade-5b45-ab99-72c68a1c4d88', 'a6ff7cc0-2afe-51c5-ad19-d9ef8cddc686', NULL, 14, 14, 'A fool also multiplies words. Man doesn''t know what will be; and that which will be after him, who can tell him?'),
  ('2df5209d-3355-584d-a741-a9ed604fa8ce', 'a6ff7cc0-2afe-51c5-ad19-d9ef8cddc686', NULL, 15, 15, 'The labor of fools wearies every one of them; for he doesn''t know how to go to the city.'),
  ('27a45b56-d128-551d-ab5f-0f119ee3ed99', 'a6ff7cc0-2afe-51c5-ad19-d9ef8cddc686', NULL, 16, 16, 'Woe to you, land, when your king is a child, and your princes eat in the morning!'),
  ('e457fe46-71a0-5eb3-ace7-7b3d609965b9', 'a6ff7cc0-2afe-51c5-ad19-d9ef8cddc686', NULL, 17, 17, 'Happy are you, land, when your king is the son of nobles, and your princes eat in due season, for strength, and not for drunkenness!'),
  ('f703828f-fae7-5ef3-a862-15aa13364302', 'a6ff7cc0-2afe-51c5-ad19-d9ef8cddc686', NULL, 18, 18, 'By slothfulness the roof sinks in; and through idleness of the hands the house leaks.'),
  ('6ab505d3-2f32-5d9a-a18f-5a1b5b971df2', 'a6ff7cc0-2afe-51c5-ad19-d9ef8cddc686', NULL, 19, 19, 'A feast is made for laughter, and wine makes the life glad; and money is the answer for all things.'),
  ('baf482be-7d6a-5b59-ad43-113690f57ee1', 'a6ff7cc0-2afe-51c5-ad19-d9ef8cddc686', NULL, 20, 20, 'Don''t curse the king, no, not in your thoughts; and don''t curse the rich in your bedroom: for a bird of the sky may carry your voice, and that which has wings may tell the matter.'),
  ('9ab159c3-1aff-5332-ab7a-51127eaeb711', 'f3ccb1bb-27e0-5d01-aaa6-a5d3070da30d', NULL, 1, 1, 'Cast your bread on the waters; for you shall find it after many days.'),
  ('1047078a-beb4-5408-a631-42de66d710cf', 'f3ccb1bb-27e0-5d01-aaa6-a5d3070da30d', NULL, 2, 2, 'Give a portion to seven, yes, even to eight; for you don''t know what evil will be on the earth.'),
  ('bc0982f4-3a59-5817-a1da-380d1b6dfe5b', 'f3ccb1bb-27e0-5d01-aaa6-a5d3070da30d', NULL, 3, 3, 'If the clouds are full of rain, they empty themselves on the earth; and if a tree falls toward the south, or toward the north, in the place where the tree falls, there shall it be.'),
  ('81f871dc-8d75-5418-a139-43752938f1b6', 'f3ccb1bb-27e0-5d01-aaa6-a5d3070da30d', NULL, 4, 4, 'He who observes the wind won''t sow; and he who regards the clouds won''t reap.'),
  ('19c448a8-017b-50fe-ab0c-cf6649fcb46a', 'f3ccb1bb-27e0-5d01-aaa6-a5d3070da30d', NULL, 5, 5, 'As you don''t know what is the way of the wind, nor how the bones grow in the womb of her who is with child; even so you don''t know the work of God who does all.'),
  ('b5e6d779-6c1c-510b-ad76-680f46c5172e', 'f3ccb1bb-27e0-5d01-aaa6-a5d3070da30d', NULL, 6, 6, 'In the morning sow your seed, and in the evening don''t withhold your hand; for you don''t know which will prosper, whether this or that, or whether they both will be equally good.'),
  ('6461cf19-176f-5a8e-a301-fef9b75ca09a', 'f3ccb1bb-27e0-5d01-aaa6-a5d3070da30d', NULL, 7, 7, 'Truly the light is sweet, and a pleasant thing it is for the eyes to see the sun.'),
  ('3fc0d0a3-551a-543c-a366-432229284797', 'f3ccb1bb-27e0-5d01-aaa6-a5d3070da30d', NULL, 8, 8, 'Yes, if a man lives many years, let him rejoice in them all; but let him remember the days of darkness, for they shall be many. All that comes is vanity.'),
  ('4fa33fa3-5f1e-5b8c-a82d-f7df3eb439da', 'f3ccb1bb-27e0-5d01-aaa6-a5d3070da30d', NULL, 9, 9, 'Rejoice, young man, in your youth, and let your heart cheer you in the days of your youth, and walk in the ways of your heart, and in the sight of your eyes; but know that for all these things God will bring you into judgment.'),
  ('2fa783db-7a49-5f4f-a860-fef46c86ed5d', 'f3ccb1bb-27e0-5d01-aaa6-a5d3070da30d', NULL, 10, 10, 'Therefore remove sorrow from your heart, and put away evil from your flesh; for youth and the dawn of life are vanity.'),
  ('b3ed3b2b-07d1-5652-a3b6-104552312e1d', '07df5350-ebfc-5c46-ab75-e7890e71a8d3', NULL, 1, 1, 'Remember also your Creator in the days of your youth, before the evil days come, and the years draw near, when you will say, "I have no pleasure in them;"'),
  ('143e47b1-085b-547f-a3af-fb561dafc5fa', '07df5350-ebfc-5c46-ab75-e7890e71a8d3', NULL, 2, 2, 'Before the sun, the light, the moon, and the stars are darkened, and the clouds return after the rain;'),
  ('0a1dfe4a-ed8f-5c63-af1e-472568d963ee', '07df5350-ebfc-5c46-ab75-e7890e71a8d3', NULL, 3, 3, 'in the day when the keepers of the house shall tremble, and the strong men shall bow themselves, and the grinders cease because they are few, and those who look out of the windows are darkened,'),
  ('234b81df-a742-56a8-a4bb-b4fe1a8ee522', '07df5350-ebfc-5c46-ab75-e7890e71a8d3', NULL, 4, 4, 'and the doors shall be shut in the street; when the sound of the grinding is low, and one shall rise up at the voice of a bird, and all the daughters of music shall be brought low;'),
  ('9d382515-00d3-5aaa-a0d5-a98d6f7502b5', '07df5350-ebfc-5c46-ab75-e7890e71a8d3', NULL, 5, 5, 'yes, they shall be afraid of heights, and terrors will be in the way; and the almond tree shall blossom, and the grasshopper shall be a burden, and desire shall fail; because man goes to his everlasting home, and the mourners go about the streets:'),
  ('5b894a2d-9639-55b7-a4dd-ecb3063c4538', '07df5350-ebfc-5c46-ab75-e7890e71a8d3', NULL, 6, 6, 'before the silver cord is severed, or the golden bowl is broken, or the pitcher is broken at the spring, or the wheel broken at the cistern,'),
  ('57870305-3588-577a-a433-b27f8aedde48', '07df5350-ebfc-5c46-ab75-e7890e71a8d3', NULL, 7, 7, 'and the dust returns to the earth as it was, and the spirit returns to God who gave it.'),
  ('1c61296b-b284-5fbb-aa49-f9bf4d1a2f44', '07df5350-ebfc-5c46-ab75-e7890e71a8d3', NULL, 8, 8, '"Vanity of vanities," says the Preacher. "All is vanity!"'),
  ('d6edde6a-d814-5a79-a19c-30f496ef242c', '07df5350-ebfc-5c46-ab75-e7890e71a8d3', NULL, 9, 9, 'Further, because the Preacher was wise, he still taught the people knowledge. Yes, he pondered, sought out, and set in order many proverbs.'),
  ('aef571d7-fd52-5e97-a078-761b28708922', '07df5350-ebfc-5c46-ab75-e7890e71a8d3', NULL, 10, 10, 'The Preacher sought to find out acceptable words, and that which was written blamelessly, words of truth.'),
  ('dba2b842-2a74-54fc-a7dc-a384e351be8a', '07df5350-ebfc-5c46-ab75-e7890e71a8d3', NULL, 11, 11, 'The words of the wise are like goads; and like nails well fastened are words from the masters of assemblies, which are given from one shepherd.'),
  ('a3a83656-d0d4-56dd-a20d-e1152fb10651', '07df5350-ebfc-5c46-ab75-e7890e71a8d3', NULL, 12, 12, 'Furthermore, my son, be admonished: of making many books there is no end; and much study is a weariness of the flesh.'),
  ('c5d7d2a2-c9bf-5491-ab2f-52f6bb00cef8', '07df5350-ebfc-5c46-ab75-e7890e71a8d3', NULL, 13, 13, 'This is the end of the matter. All has been heard. Fear God, and keep his commandments; for this is the whole duty of man.'),
  ('e7206683-b501-5018-abbe-a80ccbccbb42', '07df5350-ebfc-5c46-ab75-e7890e71a8d3', NULL, 14, 14, 'For God will bring every work into judgment, with every hidden thing, whether it is good, or whether it is evil.'),
  ('f28ca9bd-827a-5b07-aad7-6584be89127a', '75a393da-4b6f-5a90-a083-3b7cb37df64f', NULL, 1, 1, 'The Song of songs, which is Solomon''s. Beloved'),
  ('80f31a86-a5e9-583b-a8b3-5a16b11d70a3', '75a393da-4b6f-5a90-a083-3b7cb37df64f', NULL, 2, 2, 'Let him kiss me with the kisses of his mouth; for your love is better than wine.'),
  ('7b2b3bc4-94c9-56f6-a687-ff3c082b191e', '75a393da-4b6f-5a90-a083-3b7cb37df64f', NULL, 3, 3, 'Your oils have a pleasing fragrance. Your name is oil poured forth, therefore the virgins love you.'),
  ('6ced3539-d482-53af-a09a-1220d261ff2a', '75a393da-4b6f-5a90-a083-3b7cb37df64f', NULL, 4, 4, 'Take me away with you. Let us hurry. The king has brought me into his rooms. Friends We will be glad and rejoice in you. We will praise your love more than wine! Beloved They are right to love you.'),
  ('60f54e46-298e-586e-a407-7634294ce832', '75a393da-4b6f-5a90-a083-3b7cb37df64f', NULL, 5, 5, 'I am dark, but lovely, you daughters of Jerusalem, like Kedar''s tents, like Solomon''s curtains.'),
  ('2edaad33-f487-57a1-a38a-75761f8ee7f4', '75a393da-4b6f-5a90-a083-3b7cb37df64f', NULL, 6, 6, 'Don''t stare at me because I am dark, because the sun has scorched me. My mother''s sons were angry with me. They made me keeper of the vineyards. I haven''t kept my own vineyard.'),
  ('395e245c-8266-5a5b-aca5-bda6a20d144e', '75a393da-4b6f-5a90-a083-3b7cb37df64f', NULL, 7, 7, 'Tell me, you whom my soul loves, where you graze your flock, where you rest them at noon; For why should I be as one who is veiled beside the flocks of your companions? Lover'),
  ('bb8cbdc1-5854-5ab3-a0c3-6b090b918dad', '75a393da-4b6f-5a90-a083-3b7cb37df64f', NULL, 8, 8, 'If you don''t know, most beautiful among women, follow the tracks of the sheep. Graze your young goats beside the shepherds'' tents.'),
  ('db8d6d9f-5054-5807-ab61-0db67cf1837f', '75a393da-4b6f-5a90-a083-3b7cb37df64f', NULL, 9, 9, 'I have compared you, my love, to a steed in Pharaoh''s chariots.'),
  ('cee080f1-91fc-59ca-a0ea-e498370ec246', '75a393da-4b6f-5a90-a083-3b7cb37df64f', NULL, 10, 10, 'Your cheeks are beautiful with earrings, your neck with strings of jewels.'),
  ('1643e04a-5e1b-5a95-a249-3f4c203c8725', '75a393da-4b6f-5a90-a083-3b7cb37df64f', NULL, 11, 11, 'We will make you earrings of gold, with studs of silver. Beloved'),
  ('9427b103-b827-5e26-a775-7b4a25791d8f', '75a393da-4b6f-5a90-a083-3b7cb37df64f', NULL, 12, 12, 'While the king sat at his table, my perfume spread its fragrance.'),
  ('e151a8d4-5b4f-5c69-a7f1-62ff7835439c', '75a393da-4b6f-5a90-a083-3b7cb37df64f', NULL, 13, 13, 'My beloved is to me a sachet of myrrh, that lies between my breasts.'),
  ('89aff3b4-67e3-5889-a926-4c90c3ad9e13', '75a393da-4b6f-5a90-a083-3b7cb37df64f', NULL, 14, 14, 'My beloved is to me a cluster of henna blossoms from the vineyards of En Gedi. Lover'),
  ('bb3d0e82-efb0-5ee2-aa68-fc228865d8f6', '75a393da-4b6f-5a90-a083-3b7cb37df64f', NULL, 15, 15, 'Behold, you are beautiful, my love. Behold, you are beautiful. Your eyes are doves. Beloved'),
  ('7fcd97d2-e301-5141-aa81-987e8539a824', '75a393da-4b6f-5a90-a083-3b7cb37df64f', NULL, 16, 16, 'Behold, you are beautiful, my beloved, yes, pleasant; and our couch is verdant. Lover'),
  ('d650d05c-273d-5c20-a9a4-d653c23a102d', '75a393da-4b6f-5a90-a083-3b7cb37df64f', NULL, 17, 17, 'The beams of our house are cedars. Our rafters are firs. Beloved'),
  ('146348f9-73c2-568b-a4f5-020ebab27012', 'd4502655-93b4-5ac5-aaec-a0ce64aa6870', NULL, 1, 1, 'I am a rose of Sharon, a lily of the valleys. Lover'),
  ('9d692476-4a69-5fff-a226-f85eeb70e462', 'd4502655-93b4-5ac5-aaec-a0ce64aa6870', NULL, 2, 2, 'As a lily among thorns, so is my love among the daughters. Beloved'),
  ('9d7f1153-a722-5fc0-a6f3-9a61c0ab3a5e', 'd4502655-93b4-5ac5-aaec-a0ce64aa6870', NULL, 3, 3, 'As the apple tree among the trees of the wood, so is my beloved among the sons. I sat down under his shadow with great delight, his fruit was sweet to my taste.'),
  ('ae5f3d9c-b8e5-52ae-aaeb-7f69e64122fc', 'd4502655-93b4-5ac5-aaec-a0ce64aa6870', NULL, 4, 4, 'He brought me to the banquet hall. His banner over me is love.'),
  ('f8baa146-d125-5fac-ad59-56e9932f994b', 'd4502655-93b4-5ac5-aaec-a0ce64aa6870', NULL, 5, 5, 'Strengthen me with raisins, refresh me with apples; For I am faint with love.'),
  ('a218131a-0dba-57a0-a396-5b57fc6337ee', 'd4502655-93b4-5ac5-aaec-a0ce64aa6870', NULL, 6, 6, 'His left hand is under my head. His right hand embraces me.'),
  ('e03c494d-0362-545c-a581-ce67fe0ea9a2', 'd4502655-93b4-5ac5-aaec-a0ce64aa6870', NULL, 7, 7, 'I adjure you, daughters of Jerusalem, by the roes, or by the hinds of the field, that you not stir up, nor awaken love, until it so desires.'),
  ('cfa8595e-e74f-5938-a3c3-8798a550a5f7', 'd4502655-93b4-5ac5-aaec-a0ce64aa6870', NULL, 8, 8, 'The voice of my beloved! Behold, he comes, leaping on the mountains, skipping on the hills.'),
  ('144489cd-cefc-5b03-a3f9-54702e63753f', 'd4502655-93b4-5ac5-aaec-a0ce64aa6870', NULL, 9, 9, 'My beloved is like a roe or a young hart. Behold, he stands behind our wall! He looks in at the windows. He glances through the lattice.'),
  ('74fc9d24-5661-59e5-a36e-f266ab22a4da', 'd4502655-93b4-5ac5-aaec-a0ce64aa6870', NULL, 10, 10, 'My beloved spoke, and said to me, "Rise up, my love, my beautiful one, and come away.'),
  ('051d8fa2-1d2a-56ae-ab06-dddbcf2e93a0', 'd4502655-93b4-5ac5-aaec-a0ce64aa6870', NULL, 11, 11, 'For, behold, the winter is past. The rain is over and gone.'),
  ('f6726e10-f5b6-51af-a65e-6b9827e159e1', 'd4502655-93b4-5ac5-aaec-a0ce64aa6870', NULL, 12, 12, 'The flowers appear on the earth. The time of the singing has come, and the voice of the turtledove is heard in our land.'),
  ('01d446b4-4ebb-5192-a081-841716091983', 'd4502655-93b4-5ac5-aaec-a0ce64aa6870', NULL, 13, 13, 'The fig tree ripens her green figs. The vines are in blossom. They give forth their fragrance. Arise, my love, my beautiful one, and come away." Lover'),
  ('a8464a5d-1126-5825-a6b3-dd0405f0d395', 'd4502655-93b4-5ac5-aaec-a0ce64aa6870', NULL, 14, 14, 'My dove in the clefts of the rock, In the hiding places of the mountainside, Let me see your face. Let me hear your voice; for your voice is sweet, and your face is lovely.'),
  ('8ab8fe49-fdcf-502a-a7a6-e2a9622aec68', 'd4502655-93b4-5ac5-aaec-a0ce64aa6870', NULL, 15, 15, 'Catch for us the foxes, the little foxes that spoil the vineyards; for our vineyards are in blossom. Beloved'),
  ('782182b6-4fbf-56d0-a82c-b163d5a45c7c', 'd4502655-93b4-5ac5-aaec-a0ce64aa6870', NULL, 16, 16, 'My beloved is mine, and I am his. He browses among the lilies.'),
  ('2da8a741-fecb-5fc5-a03d-4cb5a74a586d', 'd4502655-93b4-5ac5-aaec-a0ce64aa6870', NULL, 17, 17, 'Until the day is cool, and the shadows flee away, turn, my beloved, and be like a roe or a young hart on the mountains of Bether.'),
  ('03486218-1917-5d79-a557-3624fac1d9ed', '613139e7-5260-570c-ab92-1080e074dfa4', NULL, 1, 1, 'By night on my bed, I sought him whom my soul loves. I sought him, but I didn''t find him.'),
  ('7c6d2bce-9bcc-5c78-acba-4af74428617d', '613139e7-5260-570c-ab92-1080e074dfa4', NULL, 2, 2, 'I will get up now, and go about the city; in the streets and in the squares I will seek him whom my soul loves. I sought him, but I didn''t find him.'),
  ('dc30ab1b-ed19-54db-ae62-dfd1a8e6ba63', '613139e7-5260-570c-ab92-1080e074dfa4', NULL, 3, 3, 'The watchmen who go about the city found me; "Have you seen him whom my soul loves?"'),
  ('78b3b45c-3942-59cd-a650-2f42f8ed238b', '613139e7-5260-570c-ab92-1080e074dfa4', NULL, 4, 4, 'I had scarcely passed from them, when I found him whom my soul loves. I held him, and would not let him go, until I had brought him into my mother''s house, into the room of her who conceived me.'),
  ('89ddd20d-7077-5d76-a93c-1977dd316c53', '613139e7-5260-570c-ab92-1080e074dfa4', NULL, 5, 5, 'I adjure you, daughters of Jerusalem, by the roes, or by the hinds of the field, that you not stir up, nor awaken love, until it so desires.'),
  ('53ca48ed-eea2-52fb-a762-0c6456d53c56', '613139e7-5260-570c-ab92-1080e074dfa4', NULL, 6, 6, 'Who is this who comes up from the wilderness like pillars of smoke, perfumed with myrrh and frankincense, with all spices of the merchant?'),
  ('8b71a0d4-d0f2-591c-af9b-4492fa129b1c', '613139e7-5260-570c-ab92-1080e074dfa4', NULL, 7, 7, 'Behold, it is Solomon''s carriage! Sixty mighty men are around it, of the mighty men of Israel.'),
  ('5ac53525-c11d-58d0-a9a7-7496c1925546', '613139e7-5260-570c-ab92-1080e074dfa4', NULL, 8, 8, 'They all handle the sword, and are expert in war. Every man has his sword on his thigh, because of fear in the night.'),
  ('e9293321-eb58-5aa6-afcf-242792760e0e', '613139e7-5260-570c-ab92-1080e074dfa4', NULL, 9, 9, 'King Solomon made himself a carriage of the wood of Lebanon.'),
  ('4501cb50-8301-5e21-aa71-1f3328a1da94', '613139e7-5260-570c-ab92-1080e074dfa4', NULL, 10, 10, 'He made its pillars of silver, its bottom of gold, its seat of purple, its midst being paved with love, from the daughters of Jerusalem.'),
  ('b9f09e81-a63a-52ac-aac4-999763886e6c', '613139e7-5260-570c-ab92-1080e074dfa4', NULL, 11, 11, 'Go forth, you daughters of Zion, and see king Solomon, with the crown with which his mother has crowned him, in the day of his weddings, in the day of the gladness of his heart. Lover'),
  ('eb2ecff4-4ac5-5e10-a515-8bbd98b9da40', '808fc7e7-874f-5bd8-a1de-dd4c8494671f', NULL, 1, 1, 'Behold, you are beautiful, my love. Behold, you are beautiful. Your eyes are doves behind your veil. Your hair is as a flock of goats, that descend from Mount Gilead.'),
  ('8e1f7690-ca83-58bd-a48e-0edbe0986635', '808fc7e7-874f-5bd8-a1de-dd4c8494671f', NULL, 2, 2, 'Your teeth are like a newly shorn flock, which have come up from the washing, where every one of them has twins. None is bereaved among them.'),
  ('72c2a231-9e4a-5da5-a39a-ce01978b5342', '808fc7e7-874f-5bd8-a1de-dd4c8494671f', NULL, 3, 3, 'Your lips are like scarlet thread. Your mouth is lovely. Your temples are like a piece of a pomegranate behind your veil.'),
  ('edc11cfd-ed0e-5c61-af3e-e952b0c0cbfc', '808fc7e7-874f-5bd8-a1de-dd4c8494671f', NULL, 4, 4, 'Your neck is like David''s tower built for an armory, whereon a thousand shields hang, all the shields of the mighty men.'),
  ('54702787-7731-5a34-aefc-396c35fd4389', '808fc7e7-874f-5bd8-a1de-dd4c8494671f', NULL, 5, 5, 'Your two breasts are like two fawns that are twins of a roe, which feed among the lilies.'),
  ('69014243-e782-577e-a8d4-31d955fe6863', '808fc7e7-874f-5bd8-a1de-dd4c8494671f', NULL, 6, 6, 'Until the day is cool, and the shadows flee away, I will go to the mountain of myrrh, to the hill of frankincense.'),
  ('2a938387-a32d-514b-ac0d-bb8a09710fe9', '808fc7e7-874f-5bd8-a1de-dd4c8494671f', NULL, 7, 7, 'You are all beautiful, my love. There is no spot in you.'),
  ('fc6da7fc-309e-5a91-ac76-925c432cfbc0', '808fc7e7-874f-5bd8-a1de-dd4c8494671f', NULL, 8, 8, 'Come with me from Lebanon, my bride, with me from Lebanon. Look from the top of Amana, from the top of Senir and Hermon, from the lions'' dens, from the mountains of the leopards.'),
  ('84ee392d-de26-5bf8-a47d-9745ae0afd8d', '808fc7e7-874f-5bd8-a1de-dd4c8494671f', NULL, 9, 9, 'You have ravished my heart, my sister, my bride. You have ravished my heart with one of your eyes, with one chain of your neck.'),
  ('1fba9958-d0b3-5691-ab66-e20874788a23', '808fc7e7-874f-5bd8-a1de-dd4c8494671f', NULL, 10, 10, 'How beautiful is your love, my sister, my bride! How much better is your love than wine! The fragrance of your perfumes than all kinds of spices!'),
  ('f147137e-6390-5abf-af6c-bca3b0d16de4', '808fc7e7-874f-5bd8-a1de-dd4c8494671f', NULL, 11, 11, 'Your lips, my bride, drip like the honeycomb. Honey and milk are under your tongue. The smell of your garments is like the smell of Lebanon.'),
  ('1192d70f-89b0-55f2-a431-de131902fd98', '808fc7e7-874f-5bd8-a1de-dd4c8494671f', NULL, 12, 12, 'A locked up garden is my sister, my bride; a locked up spring, a sealed fountain.'),
  ('672bb568-9ca8-51ce-a80f-4b8d1195d757', '808fc7e7-874f-5bd8-a1de-dd4c8494671f', NULL, 13, 13, 'Your shoots are an orchard of pomegranates, with precious fruits: henna with spikenard plants,'),
  ('7b852bd9-4591-5702-a7b7-980e5bcd4752', '808fc7e7-874f-5bd8-a1de-dd4c8494671f', NULL, 14, 14, 'spikenard and saffron, calamus and cinnamon, with every kind of incense tree; myrrh and aloes, with all the best spices,'),
  ('a1c0bb1b-a5a1-53fe-ae5e-96adfdd23440', '808fc7e7-874f-5bd8-a1de-dd4c8494671f', NULL, 15, 15, 'a fountain of gardens, a well of living waters, flowing streams from Lebanon. Beloved'),
  ('6bfe28f1-92b2-5140-a5b9-f61ad79eeb98', '808fc7e7-874f-5bd8-a1de-dd4c8494671f', NULL, 16, 16, 'Awake, north wind; and come, you south! Blow on my garden, that its spices may flow out. Let my beloved come into his garden, and taste his precious fruits. Lover'),
  ('ffa6a743-8187-5832-a58c-725674911b4f', '732a812e-1e5e-5571-a920-2b5761ffa66e', NULL, 1, 1, 'I have come into my garden, my sister, my bride. I have gathered my myrrh with my spice; I have eaten my honeycomb with my honey; I have drunk my wine with my milk. Friends Eat, friends! Drink, yes, drink abundantly, beloved. Beloved'),
  ('e31dc63f-2426-52a3-a666-ccfcddba176f', '732a812e-1e5e-5571-a920-2b5761ffa66e', NULL, 2, 2, 'I was asleep, but my heart was awake. It is the voice of my beloved who knocks: "Open to me, my sister, my love, my dove, my undefiled; for my head is filled with dew, and my hair with the dampness of the night."'),
  ('8e873ec0-060c-59f0-ad29-3e5c1136cbcc', '732a812e-1e5e-5571-a920-2b5761ffa66e', NULL, 3, 3, 'I have taken off my robe. Indeed, must I put it on? I have washed my feet. Indeed, must I soil them?'),
  ('d50186f7-04ae-585f-ab2d-23813bc57f2e', '732a812e-1e5e-5571-a920-2b5761ffa66e', NULL, 4, 4, 'My beloved thrust his hand in through the latch opening. My heart pounded for him.'),
  ('c76b7c01-f57f-5402-a606-53ae764dbff9', '732a812e-1e5e-5571-a920-2b5761ffa66e', NULL, 5, 5, 'I rose up to open for my beloved. My hands dripped with myrrh, my fingers with liquid myrrh, on the handles of the lock.'),
  ('f921ddc7-4746-5b4c-a884-988b5cb73708', '732a812e-1e5e-5571-a920-2b5761ffa66e', NULL, 6, 6, 'I opened to my beloved; but my beloved left; and had gone away. My heart went out when he spoke. I looked for him, but I didn''t find him. I called him, but he didn''t answer.'),
  ('591b7928-23e6-57a3-a8ac-5d324b7720df', '732a812e-1e5e-5571-a920-2b5761ffa66e', NULL, 7, 7, 'The watchmen who go about the city found me. They beat me. They bruised me. The keepers of the walls took my cloak away from me.'),
  ('0c19e55f-ef75-5f11-af35-8e1887a67c87', '732a812e-1e5e-5571-a920-2b5761ffa66e', NULL, 8, 8, 'I adjure you, daughters of Jerusalem, If you find my beloved, that you tell him that I am faint with love. Friends'),
  ('8800b481-5085-5ebe-a1da-a869f8bdd1b3', '732a812e-1e5e-5571-a920-2b5761ffa66e', NULL, 9, 9, 'How is your beloved better than another beloved, you fairest among women? How is your beloved better than another beloved, that you do so adjure us? Beloved'),
  ('abc34b11-e47b-5cf1-afb0-bcb71c32680f', '732a812e-1e5e-5571-a920-2b5761ffa66e', NULL, 10, 10, 'My beloved is white and ruddy. The best among ten thousand.'),
  ('35a8963d-a1dc-5ec9-a9ab-2f6cc34497c7', '732a812e-1e5e-5571-a920-2b5761ffa66e', NULL, 11, 11, 'His head is like the purest gold. His hair is bushy, black as a raven.'),
  ('066f9873-42b6-5d63-a62c-9a96c3f06781', '732a812e-1e5e-5571-a920-2b5761ffa66e', NULL, 12, 12, 'His eyes are like doves beside the water brooks, washed with milk, mounted like jewels.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('eda7b3b0-a989-5ccc-ad7d-cbbbcde45e72', '732a812e-1e5e-5571-a920-2b5761ffa66e', NULL, 13, 13, 'His cheeks are like a bed of spices with towers of perfumes. His lips are like lilies, dropping liquid myrrh.'),
  ('205dbd71-f642-5aca-a699-f511815874f9', '732a812e-1e5e-5571-a920-2b5761ffa66e', NULL, 14, 14, 'His hands are like rings of gold set with beryl. His body is like ivory work overlaid with sapphires.'),
  ('aed155bf-4b40-5c15-aeaa-a5aab6ea223b', '732a812e-1e5e-5571-a920-2b5761ffa66e', NULL, 15, 15, 'His legs are like pillars of marble set on sockets of fine gold. His appearance is like Lebanon, excellent as the cedars.'),
  ('46f319b9-8808-5787-aec5-fae6f6c6c72b', '732a812e-1e5e-5571-a920-2b5761ffa66e', NULL, 16, 16, 'His mouth is sweetness; yes, he is altogether lovely. This is my beloved, and this is my friend, daughters of Jerusalem. Friends'),
  ('7959f2c2-ad5e-5d0e-ad2b-3b96058e5193', 'd6281a2e-3736-5162-a8df-844d3c553adc', NULL, 1, 1, 'Where has your beloved gone, you fairest among women? Where has your beloved turned, that we may seek him with you? Beloved'),
  ('bede3861-f093-5ad1-a1dd-c7d9c3514c76', 'd6281a2e-3736-5162-a8df-844d3c553adc', NULL, 2, 2, 'My beloved has gone down to his garden, to the beds of spices, to feed in the gardens, and to gather lilies.'),
  ('6a3c7739-55eb-554d-ac0c-31f331910f97', 'd6281a2e-3736-5162-a8df-844d3c553adc', NULL, 3, 3, 'I am my beloved''s, and my beloved is mine. He browses among the lilies,'),
  ('27ebb367-0e31-50eb-adc3-55f3bde73a07', 'd6281a2e-3736-5162-a8df-844d3c553adc', NULL, 4, 4, 'You are beautiful, my love, as Tirzah, lovely as Jerusalem, awesome as an army with banners.'),
  ('50bbcc86-43f8-5ade-a867-adcb8125d555', 'd6281a2e-3736-5162-a8df-844d3c553adc', NULL, 5, 5, 'Turn away your eyes from me, for they have overcome me. Your hair is like a flock of goats, that lie along the side of Gilead.'),
  ('ea0823de-d5c2-5d9b-a41c-31c9010a5b18', 'd6281a2e-3736-5162-a8df-844d3c553adc', NULL, 6, 6, 'Your teeth are like a flock of ewes, which have come up from the washing; of which every one has twins; none is bereaved among them.'),
  ('ba1cc099-26cb-58fc-aae3-edfa98665191', 'd6281a2e-3736-5162-a8df-844d3c553adc', NULL, 7, 7, 'Your temples are like a piece of a pomegranate behind your veil.'),
  ('89bbc9c8-8148-571a-ab42-892139344898', 'd6281a2e-3736-5162-a8df-844d3c553adc', NULL, 8, 8, 'There are sixty queens, eighty concubines, and virgins without number.'),
  ('3fb50eba-925c-5ad1-a41c-32de2a217543', 'd6281a2e-3736-5162-a8df-844d3c553adc', NULL, 9, 9, 'My dove, my perfect one, is unique. She is her mother''s only daughter. She is the favorite one of her who bore her. The daughters saw her, and called her blessed; the queens and the concubines, and they praised her.'),
  ('e5ca54a0-a023-5050-a8de-be094f7f20a5', 'd6281a2e-3736-5162-a8df-844d3c553adc', NULL, 10, 10, 'Who is she who looks forth as the morning, beautiful as the moon, clear as the sun, and awesome as an army with banners?'),
  ('f1e4ee22-73c3-5655-aa7a-970dfc46e385', 'd6281a2e-3736-5162-a8df-844d3c553adc', NULL, 11, 11, 'I went down into the nut tree grove, to see the green plants of the valley, to see whether the vine budded, and the pomegranates were in flower.'),
  ('90a4ffc6-884c-5ce0-a15c-f7a4cb1f5696', 'd6281a2e-3736-5162-a8df-844d3c553adc', NULL, 12, 12, 'Without realizing it, my desire set me with my royal people''s chariots. Friends'),
  ('e69aa006-e64f-5387-acd3-8ee8e946b615', 'd6281a2e-3736-5162-a8df-844d3c553adc', NULL, 13, 13, 'Return, return, Shulammite! Return, return, that we may gaze at you. Lover Why do you desire to gaze at the Shulammite, as at the dance of Mahanaim?'),
  ('1523b3a4-2a75-5666-adb7-0b6e822cfee2', 'c864d073-9e56-53f4-a8d0-f58c2abcccd7', NULL, 1, 1, 'How beautiful are your feet in sandals, prince''s daughter! Your rounded thighs are like jewels, the work of the hands of a skillful workman.'),
  ('150ff82f-4cb2-5290-aeb5-c52e6fe58f24', 'c864d073-9e56-53f4-a8d0-f58c2abcccd7', NULL, 2, 2, 'Your body is like a round goblet, no mixed wine is wanting. Your waist is like a heap of wheat, set about with lilies.'),
  ('7e049e42-5aa7-525c-aba8-20afd1ec92d8', 'c864d073-9e56-53f4-a8d0-f58c2abcccd7', NULL, 3, 3, 'Your two breasts are like two fawns, that are twins of a roe.'),
  ('e7d7f28d-980a-57dc-af74-0e37ce9fcfdc', 'c864d073-9e56-53f4-a8d0-f58c2abcccd7', NULL, 4, 4, 'Your neck is like an ivory tower. Your eyes are like the pools in Heshbon by the gate of Bathrabbim. Your nose is like the tower of Lebanon which looks toward Damascus.'),
  ('9b58d59d-70db-5328-a7c8-a24a4511e201', 'c864d073-9e56-53f4-a8d0-f58c2abcccd7', NULL, 5, 5, 'Your head on you is like Carmel. The hair of your head like purple. The king is held captive in its tresses.'),
  ('20e0fda0-0146-57e0-a81c-871f246e645b', 'c864d073-9e56-53f4-a8d0-f58c2abcccd7', NULL, 6, 6, 'How beautiful and how pleasant you are, love, for delights!'),
  ('4e3f48de-f51b-5b67-ac87-605fe97b6d97', 'c864d073-9e56-53f4-a8d0-f58c2abcccd7', NULL, 7, 7, 'This, your stature, is like a palm tree, your breasts like its fruit.'),
  ('849ce3d2-0fe3-5d8c-ac96-a1b2f57576db', 'c864d073-9e56-53f4-a8d0-f58c2abcccd7', NULL, 8, 8, 'I said, "I will climb up into the palm tree. I will take hold of its fruit." Let your breasts be like clusters of the vine, the smell of your breath like apples, Beloved'),
  ('39f0d65b-5dea-58ea-a7f0-147f3614b0ad', 'c864d073-9e56-53f4-a8d0-f58c2abcccd7', NULL, 9, 9, 'Your mouth like the best wine, that goes down smoothly for my beloved, gliding through the lips of those who are asleep.'),
  ('cb771fe5-6927-5523-ac78-015570d9036f', 'c864d073-9e56-53f4-a8d0-f58c2abcccd7', NULL, 10, 10, 'I am my beloved''s. His desire is toward me.'),
  ('cb71d8be-bc0a-50f0-aac9-af94d8d0f2d8', 'c864d073-9e56-53f4-a8d0-f58c2abcccd7', NULL, 11, 11, 'Come, my beloved, let us go forth into the field. Let us lodge in the villages.'),
  ('37aa15bb-ec9a-5a79-afb3-4048c9ca9bdb', 'c864d073-9e56-53f4-a8d0-f58c2abcccd7', NULL, 12, 12, 'Let''s go early up to the vineyards. Let''s see whether the vine has budded, its blossom is open, and the pomegranates are in flower. There I will give you my love.'),
  ('50e33791-192f-5f14-a397-8772980069c2', 'c864d073-9e56-53f4-a8d0-f58c2abcccd7', NULL, 13, 13, 'The mandrakes give forth fragrance. At our doors are all kinds of precious fruits, new and old, which I have stored up for you, my beloved.'),
  ('6d3633d6-d09e-5cde-a14c-02cdee009995', 'c646b486-76e7-5ee4-a0e6-4b7b6a51d5f9', NULL, 1, 1, 'Oh that you were like my brother, who nursed from the breasts of my mother! If I found you outside, I would kiss you; yes, and no one would despise me.'),
  ('bb5bf1be-1f1f-51f1-a5b3-ee32042e12a7', 'c646b486-76e7-5ee4-a0e6-4b7b6a51d5f9', NULL, 2, 2, 'I would lead you, bringing you into my mother''s house, who would instruct me. I would have you drink spiced wine, of the juice of my pomegranate.'),
  ('140c566b-ec6d-572b-abe6-5a8179a369ce', 'c646b486-76e7-5ee4-a0e6-4b7b6a51d5f9', NULL, 3, 3, 'His left hand would be under my head. His right hand would embrace me.'),
  ('8208c2a6-6816-5257-a02f-abfbffc9571c', 'c646b486-76e7-5ee4-a0e6-4b7b6a51d5f9', NULL, 4, 4, 'I adjure you, daughters of Jerusalem, that you not stir up, nor awaken love, until it so desires. Friends'),
  ('7f1f5002-338a-5a47-a56a-7250563c95fb', 'c646b486-76e7-5ee4-a0e6-4b7b6a51d5f9', NULL, 5, 5, 'Who is this who comes up from the wilderness, leaning on her beloved? Under the apple tree I aroused you. There your mother conceived you. There she was in labor and bore you.'),
  ('07e96470-b1f5-5c46-a6d8-51e60039774a', 'c646b486-76e7-5ee4-a0e6-4b7b6a51d5f9', NULL, 6, 6, 'Set me as a seal on your heart, as a seal on your arm; for love is strong as death. Jealousy is as cruel as Sheol. Its flashes are flashes of fire, a very flame of Yahweh.'),
  ('c0bd43d7-5330-59ba-a365-14fbd58267f3', 'c646b486-76e7-5ee4-a0e6-4b7b6a51d5f9', NULL, 7, 7, 'Many waters can''t quench love, neither can floods drown it. If a man would give all the wealth of his house for love, he would be utterly scorned. Friends'),
  ('8ad1c37a-440a-581d-a6fc-ed85db7dddf7', 'c646b486-76e7-5ee4-a0e6-4b7b6a51d5f9', NULL, 8, 8, 'We have a little sister. She has no breasts. What shall we do for our sister in the day when she is to be spoken for?'),
  ('9bf43733-840e-5d27-a0f5-3f66a06122d3', 'c646b486-76e7-5ee4-a0e6-4b7b6a51d5f9', NULL, 9, 9, 'If she is a wall, we will build on her a turret of silver. if she is a door, we will enclose her with boards of cedar. Beloved'),
  ('e87709db-e680-5960-a565-a724952338b3', 'c646b486-76e7-5ee4-a0e6-4b7b6a51d5f9', NULL, 10, 10, 'I am a wall, and my breasts like towers, then I was in his eyes like one who found peace.'),
  ('18b426f6-97da-56b5-aefa-2958d724f420', 'c646b486-76e7-5ee4-a0e6-4b7b6a51d5f9', NULL, 11, 11, 'Solomon had a vineyard at Baal Hamon. He leased out the vineyard to keepers. Each was to bring a thousand shekels of silver for its fruit.'),
  ('8bd50e5e-2cc7-5b51-ae7a-80fa40762989', 'c646b486-76e7-5ee4-a0e6-4b7b6a51d5f9', NULL, 12, 12, 'My own vineyard is before me. The thousand are for you, Solomon; two hundred for those who tend its fruit. Lover'),
  ('b1dee74d-adf9-532a-a9e4-79704977c980', 'c646b486-76e7-5ee4-a0e6-4b7b6a51d5f9', NULL, 13, 13, 'You who dwell in the gardens, with friends in attendance, let me hear your voice! Beloved'),
  ('1c5dc0ac-b574-5b21-a603-e3a39507de7c', 'c646b486-76e7-5ee4-a0e6-4b7b6a51d5f9', NULL, 14, 14, 'Come away, my beloved! Be like a gazelle or a young stag on the mountains of spices!'),
  ('100814ee-971c-5ed3-adce-0cb891c0f5f9', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 1, 1, 'The vision of Isaiah the son of Amoz, which he saw concerning Judah and Jerusalem, in the days of Uzziah, Jotham, Ahaz, and Hezekiah, kings of Judah.'),
  ('e4a975b8-84e0-541d-a645-fd50cd54cfa5', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 2, 2, 'Hear, heavens, and listen, earth; for Yahweh has spoken: "I have nourished and brought up children, and they have rebelled against me.'),
  ('b918fa9d-3712-5e23-a9d6-d3cf5ace40ee', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 3, 3, 'The ox knows his owner, and the donkey his master''s crib; but Israel doesn''t know, my people don''t consider."'),
  ('7fe7843c-1181-5c1a-a082-00e248fe854b', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 4, 4, 'Ah sinful nation, a people loaded with iniquity, a seed of evildoers, children who deal corruptly! They have forsaken Yahweh. They have despised the Holy One of Israel. They are estranged and backward.'),
  ('eb0e1015-2510-5fef-af78-fe61995c6992', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 5, 5, 'Why should you be beaten more, that you revolt more and more? The whole head is sick, and the whole heart faint.'),
  ('e0803c2a-5d5f-5aec-a738-8e1d8b598166', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 6, 6, 'From the sole of the foot even to the head there is no soundness in it: wounds, welts, and open sores. They haven''t been closed, neither bandaged, neither soothed with oil.'),
  ('e0a9677f-4ab1-5fae-a6e2-eb877880d325', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 7, 7, 'Your country is desolate. Your cities are burned with fire. Strangers devour your land in your presence, and it is desolate, as overthrown by strangers.'),
  ('a2758018-06c1-5162-a672-618871186eff', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 8, 8, 'The daughter of Zion is left like a shelter in a vineyard, like a hut in a field of melons, like a besieged city.'),
  ('ccd79c8b-132c-57bb-a3a3-b9085bc9345c', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 9, 9, 'Unless Yahweh of Armies had left to us a very small remnant, we would have been as Sodom; we would have been like Gomorrah.'),
  ('6ac2cc4a-1115-56e3-a3c3-9c0379d3fdd1', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 10, 10, 'Hear the word of Yahweh, you rulers of Sodom! Listen to the law of our God, you people of Gomorrah!'),
  ('628aac3c-4f04-55a8-aa8c-2852db2faf1b', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 11, 11, '"What are the multitude of your sacrifices to me?," says Yahweh. "I have had enough of the burnt offerings of rams, and the fat of fed animals. I don''t delight in the blood of bulls, or of lambs, or of male goats.'),
  ('eb6d7067-e20f-52d9-af88-3381d00e8edc', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 12, 12, 'When you come to appear before me, who has required this at your hand, to trample my courts?'),
  ('2322c465-2267-5cf2-a4d0-74f2d5a2a29f', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 13, 13, 'Bring no more vain offerings. Incense is an abomination to me; new moons, Sabbaths, and convocations: I can''t bear with evil assemblies.'),
  ('bcb8fe84-8841-5648-a78e-5f99b544767c', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 14, 14, 'My soul hates your New Moons and your appointed feasts. They are a burden to me. I am weary of bearing them.'),
  ('3b113bb2-f52b-5681-af39-a9601493c053', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 15, 15, 'When you spread forth your hands, I will hide my eyes from you. Yes, when you make many prayers, I will not hear. Your hands are full of blood.'),
  ('fe9a5a0b-3a8a-5217-a5ff-d98596c05bb3', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 16, 16, 'Wash yourselves, make yourself clean. Put away the evil of your doings from before my eyes. Cease to do evil.'),
  ('91ba2cf4-b127-5961-a35c-8b58040c44eb', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 17, 17, 'Learn to do well. Seek justice. Relieve the oppressed. Judge the fatherless. Plead for the widow."'),
  ('0fc2245f-8e20-5193-ace6-4dffe11bee7c', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 18, 18, '"Come now, and let us reason together," says Yahweh: "Though your sins be as scarlet, they shall be as white as snow. Though they be red like crimson, they shall be as wool.'),
  ('29bfd0a5-b251-5d05-a3b9-09c1a70c834c', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 19, 19, 'If you are willing and obedient, you shall eat the good of the land;'),
  ('af40aabf-0eb4-58b8-acea-f47dbc813d05', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 20, 20, 'but if you refuse and rebel, you shall be devoured with the sword; for the mouth of Yahweh has spoken it."'),
  ('2e99181a-0661-52e7-a95d-cb2e48a736cc', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 21, 21, 'How the faithful city has become a prostitute! She was full of justice; righteousness lodged in her, but now murderers.'),
  ('a021ec24-1b75-59e2-ab77-9926724a4a34', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 22, 22, 'Your silver has become dross, your wine mixed with water.'),
  ('f2e1ddb1-9e3c-5e40-a27d-697166c5b6d3', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 23, 23, 'Your princes are rebellious, and companions of thieves. Everyone loves bribes, and follows after rewards. They don''t judge the fatherless, neither does the cause of the widow come to them.'),
  ('71c7337b-0b84-5059-add0-81955165f786', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 24, 24, 'Therefore the Lord, Yahweh of Armies, the Mighty One of Israel, says: "Ah, I will get relief from my adversaries, and avenge myself of my enemies;'),
  ('48e1d187-a374-5865-a3f2-b7af6b56be38', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 25, 25, 'and I will turn my hand on you, thoroughly purge away your dross, and will take away all your tin.'),
  ('a8015d6b-16cc-5cdb-ad49-b24260b064a1', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 26, 26, 'I will restore your judges as at the first, and your counselors as at the beginning. Afterward you shall be called ''The city of righteousness, a faithful town.'''),
  ('6e26dfd2-f4f0-5f2a-acb2-71095c9da810', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 27, 27, 'Zion shall be redeemed with justice, and her converts with righteousness.'),
  ('c33531c5-80d7-520e-aaee-ddf12cfa5b67', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 28, 28, 'But the destruction of transgressors and sinners shall be together, and those who forsake Yahweh shall be consumed.'),
  ('98b24b61-9346-521e-a962-a267be623e22', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 29, 29, 'For they shall be ashamed of the oaks which you have desired, and you shall be confounded for the gardens that you have chosen.'),
  ('ced84102-44f8-51da-ab63-a52e7311efec', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 30, 30, 'For you shall be as an oak whose leaf fades, and as a garden that has no water.'),
  ('d8ea4ef4-1003-5046-a1c2-1511f4c9e7be', '570e4f1d-e7fb-5f5b-abf3-764db2015f1e', NULL, 31, 31, 'The strong will be like tinder, and his work like a spark. They will both burn together, and no one will quench them."'),
  ('0c8cc797-c4d6-567e-a8d2-1ce7eff70548', '7adc34f2-2571-587e-aaf7-f0e704a627b7', NULL, 1, 1, 'This is what Isaiah the son of Amoz saw concerning Judah and Jerusalem.'),
  ('7f49fd75-e18a-5c8c-a634-2d71c71e0fa1', '7adc34f2-2571-587e-aaf7-f0e704a627b7', NULL, 2, 2, 'It shall happen in the latter days, that the mountain of Yahweh''s house shall be established on the top of the mountains, and shall be raised above the hills; and all nations shall flow to it.'),
  ('9b9d38d1-87c4-596c-aeae-59185f76761e', '7adc34f2-2571-587e-aaf7-f0e704a627b7', NULL, 3, 3, 'Many peoples shall go and say, "Come, let''s go up to the mountain of Yahweh, to the house of the God of Jacob; and he will teach us of his ways, and we will walk in his paths." For out of Zion the law shall go forth, and the word of Yahweh from Jerusalem.'),
  ('4175964c-3a87-5218-a6e2-673e77e0ef45', '7adc34f2-2571-587e-aaf7-f0e704a627b7', NULL, 4, 4, 'He will judge between the nations, and will decide concerning many peoples; and they shall beat their swords into plowshares, and their spears into pruning hooks. Nation shall not lift up sword against nation, neither shall they learn war any more.'),
  ('3b5c373d-959f-523a-a735-8b332b91e76b', '7adc34f2-2571-587e-aaf7-f0e704a627b7', NULL, 5, 5, 'House of Jacob, come, and let us walk in the light of Yahweh.'),
  ('59d7e6ba-1a77-545a-aded-ef93f6cbc6e3', '7adc34f2-2571-587e-aaf7-f0e704a627b7', NULL, 6, 6, 'For you have forsaken your people, the house of Jacob, because they are filled from the east, with those who practice divination like the Philistines, and they clasp hands with the children of foreigners.'),
  ('16cf68b8-8078-5aaa-a638-0b004c53f61f', '7adc34f2-2571-587e-aaf7-f0e704a627b7', NULL, 7, 7, 'Their land is full of silver and gold, neither is there any end of their treasures. Their land also is full of horses, neither is there any end of their chariots.'),
  ('31fc7241-a4c4-5576-a2ed-b986cc244a0d', '7adc34f2-2571-587e-aaf7-f0e704a627b7', NULL, 8, 8, 'Their land also is full of idols. They worship the work of their own hands, that which their own fingers have made.'),
  ('42124b86-cd4d-5d1b-a98b-d5137e7b9984', '7adc34f2-2571-587e-aaf7-f0e704a627b7', NULL, 9, 9, 'Man is brought low, and mankind is humbled; therefore don''t forgive them.'),
  ('d752bcc2-e1d2-579f-a46d-91bba9a656fa', '7adc34f2-2571-587e-aaf7-f0e704a627b7', NULL, 10, 10, 'Enter into the rock, and hide in the dust, from before the terror of Yahweh, and from the glory of his majesty.'),
  ('aa2b3a4d-6b2c-59ea-a44a-343a1a197a85', '7adc34f2-2571-587e-aaf7-f0e704a627b7', NULL, 11, 11, 'The lofty looks of man will be brought low, the haughtiness of men will be bowed down, and Yahweh alone will be exalted in that day.'),
  ('fa13cc11-0e04-5477-affd-0ad1be5063dd', '7adc34f2-2571-587e-aaf7-f0e704a627b7', NULL, 12, 12, 'For there will be a day of Yahweh of Armies for all that is proud and haughty, and for all that is lifted up; and it shall be brought low:'),
  ('96bb4958-c6b2-5d9e-ac57-8373db78fbab', '7adc34f2-2571-587e-aaf7-f0e704a627b7', NULL, 13, 13, 'For all the cedars of Lebanon, that are high and lifted up, for all the oaks of Bashan,'),
  ('679e0f93-9e39-5ced-a274-57830b8ed78a', '7adc34f2-2571-587e-aaf7-f0e704a627b7', NULL, 14, 14, 'For all the high mountains, for all the hills that are lifted up,'),
  ('b90482b3-984e-5d91-a415-99370a3940ce', '7adc34f2-2571-587e-aaf7-f0e704a627b7', NULL, 15, 15, 'For every lofty tower, for every fortified wall,'),
  ('dae26f34-1a19-53cd-abd4-1cd331704003', '7adc34f2-2571-587e-aaf7-f0e704a627b7', NULL, 16, 16, 'For all the ships of Tarshish, and for all pleasant imagery.'),
  ('be24786a-9e02-514e-afea-6919d069051c', '7adc34f2-2571-587e-aaf7-f0e704a627b7', NULL, 17, 17, 'The loftiness of man shall be bowed down, and the haughtiness of men shall be brought low; and Yahweh alone shall be exalted in that day.'),
  ('e7481c73-12b4-50da-abee-be67da17ff9e', '7adc34f2-2571-587e-aaf7-f0e704a627b7', NULL, 18, 18, 'The idols shall utterly pass away.'),
  ('cbd08b1b-6f7c-5c3a-adf5-c31aeeb25507', '7adc34f2-2571-587e-aaf7-f0e704a627b7', NULL, 19, 19, 'Men shall go into the caves of the rocks, and into the holes of the earth, from before the terror of Yahweh, and from the glory of his majesty, when he arises to shake the earth mightily.'),
  ('04725f59-e844-528b-af14-165330c0f908', '7adc34f2-2571-587e-aaf7-f0e704a627b7', NULL, 20, 20, 'In that day, men shall cast away their idols of silver, and their idols of gold, which have been made for themselves to worship, to the moles and to the bats;'),
  ('d67888cc-1f05-5153-ad8c-a743594d4f79', '7adc34f2-2571-587e-aaf7-f0e704a627b7', NULL, 21, 21, 'To go into the caverns of the rocks, and into the clefts of the ragged rocks, from before the terror of Yahweh, and from the glory of his majesty, when he arises to shake the earth mightily.'),
  ('e6d29889-49e8-5a37-a38d-e0e6a988c91d', '7adc34f2-2571-587e-aaf7-f0e704a627b7', NULL, 22, 22, 'Stop trusting in man, whose breath is in his nostrils; for of what account is he?'),
  ('f9756743-db38-52c0-a19c-e7f0cc3fce59', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 1, 1, 'For, behold, the Lord, Yahweh of Armies, takes away from Jerusalem and from Judah supply and support, the whole supply of bread, and the whole supply of water;'),
  ('a0227f05-771c-585e-a1ad-f145180e29ea', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 2, 2, 'the mighty man, the man of war, the judge, the prophet, the diviner, the elder,'),
  ('bc0b2327-8c69-5a9b-aa1e-49cd8b6c7969', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 3, 3, 'the captain of fifty, the honorable man, the counselor, the skilled craftsman, and the clever enchanter.'),
  ('6c3720cb-b8fa-53cf-a5e0-95d484083077', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 4, 4, 'I will give boys to be their princes, and children shall rule over them.'),
  ('52622e91-e39d-5e7a-a959-d1e330d03529', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 5, 5, 'The people will be oppressed, everyone by another, and everyone by his neighbor. The child will behave himself proudly against the old man, and the base against the honorable.'),
  ('48435f84-d59f-58a1-a925-5bdade67c195', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 6, 6, 'Indeed a man shall take hold of his brother in the house of his father, saying, "You have clothing, you be our ruler, and let this ruin be under your hand."'),
  ('ae1868a8-dcfa-5d67-ad75-4d27f5a7284a', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 7, 7, 'In that day he will cry out, saying, "I will not be a healer; for in my house is neither bread nor clothing. You shall not make me ruler of the people."'),
  ('c6e24836-800d-58f6-a0e4-8e7aeb6ee585', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 8, 8, 'For Jerusalem is ruined, and Judah is fallen; because their tongue and their doings are against Yahweh, to provoke the eyes of his glory.'),
  ('46aa427e-79d1-5485-a297-943d64444dcc', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 9, 9, 'The look of their faces testify against them. They parade their sin like Sodom. They don''t hide it. Woe to their soul! For they have brought disaster upon themselves.'),
  ('eeca5c37-5b35-5af1-a79f-48905ad36123', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 10, 10, 'Tell the righteous "Good!" For they shall eat the fruit of their deeds.'),
  ('486b46df-a9e3-506e-a782-18f1f8da2109', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 11, 11, 'Woe to the wicked! Disaster is upon them; for the deeds of his hands will be paid back to him.'),
  ('7ad31972-662f-5f81-a607-25f43ea2949e', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 12, 12, 'As for my people, children are their oppressors, and women rule over them. My people, those who lead you cause you to err, and destroy the way of your paths.'),
  ('e6b7047e-4fd8-5f5d-a720-b61c6a066d0b', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 13, 13, 'Yahweh stands up to contend, and stands to judge the peoples.'),
  ('dec1c3e7-f596-5207-a3a7-667a289e36dc', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 14, 14, 'Yahweh will enter into judgment with the elders of his people, and their leaders: "It is you who have eaten up the vineyard. The spoil of the poor is in your houses.'),
  ('f69ff2e7-4417-5b9e-af52-4a2a309bd7e3', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 15, 15, 'What do you mean that you crush my people, and grind the face of the poor?" says the Lord, Yahweh of Armies.'),
  ('631e95d3-de38-5305-aeec-5d188549bb54', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 16, 16, 'Moreover Yahweh said, "Because the daughters of Zion are haughty, and walk with outstretched necks and flirting eyes, walking to trip as they go, jingling ornaments on their feet;'),
  ('7e1ba314-0bd1-57f1-a516-f4c072da984d', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 17, 17, 'therefore the Lord brings sores on the crown of the head of the women of Zion, and Yahweh will make their scalps bald."'),
  ('2905e834-7aa6-55ca-ac9b-925ef34a4c8e', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 18, 18, 'In that day the Lord will take away the beauty of their anklets, the headbands, the crescent necklaces,'),
  ('e3dfac6c-0e7f-5907-af13-0eeb6ffc0d3f', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 19, 19, 'the earrings, the bracelets, the veils,'),
  ('91f13fc6-2438-5d72-aca3-ef28febf2911', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 20, 20, 'the headdresses, the ankle chains, the sashes, the perfume bottles, the charms,'),
  ('df779f55-0673-5551-a4ed-a2434124c8df', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 21, 21, 'the signet rings, the nose rings,'),
  ('d4dd968b-edd0-5540-abaf-263c50915e19', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 22, 22, 'the fine robes, the capes, the cloaks, the purses,'),
  ('dd75d126-64d1-5297-af70-5ba5d2bd05be', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 23, 23, 'the hand mirrors, the fine linen garments, the tiaras, and the shawls.'),
  ('e7b17700-ae8c-5e95-aa54-688db1ba368b', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 24, 24, 'It shall happen that instead of sweet spices, there shall be rottenness; instead of a belt, a rope; instead of well set hair, baldness; instead of a robe, a wearing of sackcloth; and branding instead of beauty.'),
  ('55d509ed-839e-5dd0-a7a1-3aa79a823e19', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 25, 25, 'Your men shall fall by the sword, and your mighty in the war.'),
  ('e75cbd63-d7f4-5a95-ae6e-e7d15ccef2ca', 'e69044b7-fd7b-5f88-a135-d9137ac9f6e5', NULL, 26, 26, 'Her gates shall lament and mourn; and she shall be desolate and sit on the ground.'),
  ('8938415e-8950-5b93-ab2a-9cef6ead3506', '93b0d058-b094-52ac-ab97-766ed10b11b2', NULL, 1, 1, 'Seven women shall take hold of one man in that day, saying, "We will eat our own bread, and wear our own clothing: only let us be called by your name. Take away our reproach."'),
  ('09dbd4d5-d441-5516-a860-5c02b0c79fbf', '93b0d058-b094-52ac-ab97-766ed10b11b2', NULL, 2, 2, 'In that day, Yahweh''s branch will be beautiful and glorious, and the fruit of the land will be the beauty and glory of the survivors of Israel.'),
  ('823d5904-ce92-5242-a5e1-65d7b9d9cbb5', '93b0d058-b094-52ac-ab97-766ed10b11b2', NULL, 3, 3, 'It will happen, that he who is left in Zion, and he who remains in Jerusalem, shall be called holy, even everyone who is written among the living in Jerusalem;'),
  ('4c51dd9c-dff7-5051-a4b7-e9d8369cf85d', '93b0d058-b094-52ac-ab97-766ed10b11b2', NULL, 4, 4, 'when the Lord shall have washed away the filth of the daughters of Zion, and shall have purged the blood of Jerusalem from its midst, by the spirit of justice, and by the spirit of burning.'),
  ('4eb00a2d-74d4-598b-a9b0-11ddaf358abf', '93b0d058-b094-52ac-ab97-766ed10b11b2', NULL, 5, 5, 'Yahweh will create over the whole habitation of Mount Zion, and over her assemblies, a cloud and smoke by day, and the shining of a flaming fire by night; for over all the glory will be a canopy.'),
  ('9273e089-c54e-566a-aae7-3b93d365e8ef', '93b0d058-b094-52ac-ab97-766ed10b11b2', NULL, 6, 6, 'There will be a pavilion for a shade in the daytime from the heat, and for a refuge and for a shelter from storm and from rain.'),
  ('d0b8abb8-6969-5e76-adab-bfe67508cc07', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 1, 1, 'Let me sing for my well beloved a song of my beloved about his vineyard. My beloved had a vineyard on a very fruitful hill.'),
  ('0fafece9-f61b-5fdc-a76e-3315e5cd95e0', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 2, 2, 'He dug it up, gathered out its stones, planted it with the choicest vine, built a tower in its midst, and also cut out a winepress therein. He looked for it to yield grapes, but it yielded wild grapes.'),
  ('504da357-745d-5a68-ada6-3d8e44915e7f', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 3, 3, '"Now, inhabitants of Jerusalem and men of Judah, please judge between me and my vineyard.'),
  ('00960293-52e1-58eb-ad08-af189416f9cc', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 4, 4, 'What could have been done more to my vineyard, that I have not done in it? Why, when I looked for it to yield grapes, did it yield wild grapes?'),
  ('83f28d32-f232-5287-ae72-376fcd03e08f', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 5, 5, 'Now I will tell you what I will do to my vineyard. I will take away its hedge, and it will be eaten up. I will break down its wall of it, and it will be trampled down.'),
  ('0014374e-48fa-50ad-ae79-abeeb94aa6f9', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 6, 6, 'I will lay it a wasteland. It won''t be pruned nor hoed, but it will grow briers and thorns. I will also command the clouds that they rain no rain on it."'),
  ('c71b646a-8236-5562-a149-3dc7822189a3', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 7, 7, 'For the vineyard of Yahweh of Armies is the house of Israel, and the men of Judah his pleasant plant: and he looked for justice, but, behold, oppression; for righteousness, but, behold, a cry of distress.'),
  ('063c0560-cb3a-57ff-a4b1-cc908924db23', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 8, 8, 'Woe to those who join house to house, who lay field to field, until there is no room, and you are made to dwell alone in the midst of the land!'),
  ('044a2fd4-eff9-5fe7-a213-2d49e2c54944', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 9, 9, 'In my ears, Yahweh of Armies says: "Surely many houses will be desolate, even great and beautiful, unoccupied.'),
  ('89f13254-efa8-5541-a534-518a27e12e75', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 10, 10, 'For ten acres of vineyard shall yield one bath, and a homer of seed shall yield an ephah."'),
  ('3cb0b742-fc07-5e63-a1e4-87c21e5a5286', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 11, 11, 'Woe to those who rise up early in the morning, that they may follow strong drink; who stay late into the night, until wine inflames them!'),
  ('24df7279-2655-5f74-a9ee-b1b6345e8474', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 12, 12, 'The harp, lyre, tambourine, and flute, with wine, are at their feasts; but they don''t respect the work of Yahweh, neither have they considered the operation of his hands.'),
  ('4c56fab5-7168-5605-a7f0-8d6b8c494b87', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 13, 13, 'Therefore my people go into captivity for lack of knowledge. Their honorable men are famished, and their multitudes are parched with thirst.'),
  ('70107317-0c47-5d1c-ad5e-ca1517d3c2ed', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 14, 14, 'Therefore Sheol has enlarged its desire, and opened its mouth without measure; and their glory, their multitude, their pomp, and he who rejoices among them, descend into it.'),
  ('376a080b-9abb-5df6-a1c2-d7b610d973c8', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 15, 15, 'So man is brought low, mankind is humbled, and the eyes of the arrogant ones are humbled;'),
  ('b52ee9db-ce9b-5154-a62b-3ea649d2a929', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 16, 16, 'but Yahweh of Armies is exalted in justice, and God the Holy One is sanctified in righteousness.'),
  ('d35260e2-cfaa-5d22-adf9-cec3efb97987', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 17, 17, 'Then the lambs will graze as in their pasture, and strangers will eat the ruins of the rich.'),
  ('5e760986-ee79-5399-ac71-b2f99797b931', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 18, 18, 'Woe to those who draw iniquity with cords of falsehood, and wickedness as with cart rope;'),
  ('1dfbb3fd-c48a-59f3-afef-5857bbe2ed92', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 19, 19, 'Who say, "Let him make speed, let him hasten his work, that we may see it; and let the counsel of the Holy One of Israel draw near and come, that we may know it!"'),
  ('1721e08f-b25f-5b6b-a582-a4e1988bcc4c', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 20, 20, 'Woe to those who call evil good, and good evil; who put darkness for light, and light for darkness; who put bitter for sweet, and sweet for bitter!'),
  ('eb839cc0-307e-5dff-a3ee-81d415040b75', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 21, 21, 'Woe to those who are wise in their own eyes, and prudent in their own sight!'),
  ('5a298ef2-f856-56b9-aa8a-5cf32e02596e', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 22, 22, 'Woe to those who are mighty to drink wine, and champions at mixing strong drink;'),
  ('55b08963-ca55-5fde-af8c-db18be4fa71d', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 23, 23, 'who acquit the guilty for a bribe, but deny justice for the innocent!'),
  ('d05842ae-9981-5c90-a03a-3808497e4d95', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 24, 24, 'Therefore as the tongue of fire devours the stubble, and as the dry grass sinks down in the flame, so their root shall be as rottenness, and their blossom shall go up as dust; because they have rejected the law of Yahweh of Armies, and despised the word of the Holy One of Israel.'),
  ('ff192e31-f645-51ed-a122-ac5698a8b3a9', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 25, 25, 'Therefore Yahweh''s anger burns against his people, and he has stretched out his hand against them, and has struck them. The mountains tremble, and their dead bodies are as refuse in the midst of the streets. For all this, his anger is not turned away, but his hand is still stretched out.'),
  ('0115db24-d7bf-5c00-afe0-646a36917f71', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 26, 26, 'He will lift up a banner to the nations from far, and he will whistle for them from the end of the earth. Behold, they will come speedily and swiftly.'),
  ('cf84cc1c-897e-5808-a2a2-d5fce8614504', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 27, 27, 'None shall be weary nor stumble among them; none shall slumber nor sleep; neither shall the belt of their waist be untied, nor the latchet of their shoes be broken:'),
  ('61134e76-d61b-5554-a1eb-fe2e9683da28', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 28, 28, 'whose arrows are sharp, and all their bows bent. Their horses'' hoofs will be like flint, and their wheels like a whirlwind.'),
  ('db763714-defb-5099-aa5f-1bf1d40bf575', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 29, 29, 'Their roaring will be like a lioness. They will roar like young lions. Yes, they shall roar, and seize their prey and carry it off, and there will be no one to deliver.'),
  ('a16a6690-3ef4-5dc9-a150-4451cb7dbb3f', '7a609e20-384b-51bf-a9b1-6fe589d2f8ba', NULL, 30, 30, 'They will roar against them in that day like the roaring of the sea. If one looks to the land behold, darkness and distress. The light is darkened in its clouds.'),
  ('7078e001-b386-53d0-a807-6e55d67c8f18', '9ccf4bed-4ef0-5d63-a0f2-0f981f49cf5c', NULL, 1, 1, 'In the year that king Uzziah died, I saw the Lord sitting on a throne, high and lifted up; and his train filled the temple.'),
  ('6b1bc0c8-656f-5677-a1b2-405b0672edd1', '9ccf4bed-4ef0-5d63-a0f2-0f981f49cf5c', NULL, 2, 2, 'Above him stood the seraphim. Each one had six wings. With two he covered his face. With two he covered his feet. With two he flew.'),
  ('cba9de70-2e8a-578d-a265-7f31f2946809', '9ccf4bed-4ef0-5d63-a0f2-0f981f49cf5c', NULL, 3, 3, 'One called to another, and said, "Holy, holy, holy, is Yahweh of Armies! The whole earth is full of his glory!"'),
  ('33f619c1-d4f4-5ac8-aec3-d7130e569793', '9ccf4bed-4ef0-5d63-a0f2-0f981f49cf5c', NULL, 4, 4, 'The foundations of the thresholds shook at the voice of him who called, and the house was filled with smoke.'),
  ('7a6666cc-7a40-58c5-ab06-16420fdd3f82', '9ccf4bed-4ef0-5d63-a0f2-0f981f49cf5c', NULL, 5, 5, 'Then I said, "Woe is me! For I am undone, because I am a man of unclean lips, and I dwell in the midst of a people of unclean lips: for my eyes have seen the King, Yahweh of Armies!"'),
  ('4d5bd326-6512-51ab-a1a3-ef03ecc6d645', '9ccf4bed-4ef0-5d63-a0f2-0f981f49cf5c', NULL, 6, 6, 'Then one of the seraphim flew to me, having a live coal in his hand, which he had taken with the tongs from off the altar.'),
  ('0defff48-6ab3-50ed-a871-325aeabbc2ce', '9ccf4bed-4ef0-5d63-a0f2-0f981f49cf5c', NULL, 7, 7, 'He touched my mouth with it, and said, "Behold, this has touched your lips; and your iniquity is taken away, and your sin forgiven."'),
  ('1434fbb0-7274-5cfb-a121-0ef979b5c5d6', '9ccf4bed-4ef0-5d63-a0f2-0f981f49cf5c', NULL, 8, 8, 'I heard the Lord''s voice, saying, "Whom shall I send, and who will go for us?" Then I said, "Here I am. Send me!"'),
  ('c3f01e58-e172-552f-a097-3e552824d994', '9ccf4bed-4ef0-5d63-a0f2-0f981f49cf5c', NULL, 9, 9, 'He said, "Go, and tell this people, ''You hear indeed, but don''t understand; and you see indeed, but don''t perceive.'''),
  ('07ccab55-bb78-5adb-a3bd-22db840c7860', '9ccf4bed-4ef0-5d63-a0f2-0f981f49cf5c', NULL, 10, 10, 'Make the heart of this people fat. Make their ears heavy, and shut their eyes; lest they see with their eyes, and hear with their ears, and understand with their heart, and turn again, and be healed."'),
  ('aab62f2a-3b89-5ff0-a468-c4139f07c0ff', '9ccf4bed-4ef0-5d63-a0f2-0f981f49cf5c', NULL, 11, 11, 'Then I said, "Lord, how long?" He answered, "Until cities are waste without inhabitant, and houses without man, and the land becomes utterly waste,'),
  ('e0d6b712-343b-5be5-a910-ddfbe617e192', '9ccf4bed-4ef0-5d63-a0f2-0f981f49cf5c', NULL, 12, 12, 'And Yahweh has removed men far away, and the forsaken places are many in the midst of the land.'),
  ('a47351fc-7608-5e62-aa0d-dc4bfaefb62e', '9ccf4bed-4ef0-5d63-a0f2-0f981f49cf5c', NULL, 13, 13, 'If there is a tenth left in it, that also will in turn be consumed: as a terebinth, and as an oak, whose stock remains when they are felled; so the holy seed is its stock."'),
  ('de9aed6b-475f-598d-a3e8-48415c8249a0', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 1, 1, 'It happened in the days of Ahaz the son of Jotham, the son of Uzziah, king of Judah, that Rezin the king of Syria, and Pekah the son of Remaliah, king of Israel, went up to Jerusalem to war against it, but could not prevail against it.'),
  ('150bc6df-ca82-532f-a26d-04c03a8828ca', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 2, 2, 'It was told the house of David, saying, "Syria is allied with Ephraim." His heart trembled, and the heart of his people, as the trees of the forest tremble with the wind.'),
  ('97ec41d1-7f84-5e72-a0fc-395224db1ad2', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 3, 3, 'Then Yahweh said to Isaiah, "Go out now to meet Ahaz, you, and Shearjashub your son, at the end of the conduit of the upper pool, on the highway of the fuller''s field.'),
  ('4ede6c80-69a7-5cd8-a901-ef2af2e0c68b', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 4, 4, 'Tell him, ''Be careful, and keep calm. Don''t be afraid, neither let your heart be faint because of these two tails of smoking torches, for the fierce anger of Rezin and Syria, and of the son of Remaliah.'),
  ('5cca7f37-5463-5ca9-a6ce-f9312ff2d835', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 5, 5, 'Because Syria, Ephraim, and the son of Remaliah, have plotted evil against you, saying,'),
  ('b5f8c894-05b6-5b26-a9a5-26a475d80446', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 6, 6, '"Let''s go up against Judah, and tear it apart, and let''s divide it among ourselves, and set up a king in its midst, even the son of Tabeel."'),
  ('944bd444-1ed0-500c-aec3-287e30cc825c', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 7, 7, 'This is what the Lord Yahweh says: "It shall not stand, neither shall it happen."'),
  ('b2a4ca3c-ee36-5962-a0e1-56d7b93872ef', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 8, 8, 'For the head of Syria is Damascus, and the head of Damascus is Rezin; and within sixty-five years Ephraim shall be broken in pieces, so that it shall not be a people;'),
  ('21b4522a-2be4-510c-aedf-76dced859b96', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 9, 9, 'and the head of Ephraim is Samaria, and the head of Samaria is Remaliah''s son. If you will not believe, surely you shall not be established.''"'),
  ('1723ba24-6f45-508e-a6c6-8ee0322c8ed5', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 10, 10, 'Yahweh spoke again to Ahaz, saying,'),
  ('bced2d09-3f33-56fd-ad0a-ac3751293e11', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 11, 11, '"Ask a sign of Yahweh your God; ask it either in the depth, or in the height above."'),
  ('c9b6d3f2-1101-57a3-a854-ed4ccf4c0d76', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 12, 12, 'But Ahaz said, "I will not ask, neither will I tempt Yahweh."'),
  ('fa22337b-ddab-5ea8-a4e7-db26c9d574fd', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 13, 13, 'He said, "Listen now, house of David. Is it not enough for you to try the patience of men, that you will try the patience of my God also?'),
  ('285248f5-4003-5579-a0da-22969bf1e783', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 14, 14, 'Therefore the Lord himself will give you a sign. Behold, the virgin will conceive, and bear a son, and shall call his name Immanuel.'),
  ('7b08bb55-ce9f-5083-a1b4-e3d82bebc503', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 15, 15, 'He shall eat butter and honey when he knows to refuse the evil, and choose the good.'),
  ('3ccacb7d-5e55-540f-afad-72e479fa54b5', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 16, 16, 'For before the child knows to refuse the evil, and choose the good, the land whose two kings you abhor shall be forsaken.'),
  ('a5ae6134-fa81-5473-a92e-d877ed0053ec', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 17, 17, 'Yahweh will bring on you, on your people, and on your father''s house, days that have not come, from the day that Ephraim departed from Judah; even the king of Assyria.'),
  ('14aef824-804a-5815-a68a-f81320b7b176', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 18, 18, 'It will happen in that day that Yahweh will whistle for the fly that is in the uttermost part of the rivers of Egypt, and for the bee that is in the land of Assyria.'),
  ('5eb3fa8f-0360-5c41-a3be-99c3e35d4043', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 19, 19, 'They shall come, and shall all rest in the desolate valleys, in the clefts of the rocks, on all thorn hedges, and on all pastures.'),
  ('cb61037f-944e-5e4f-aa29-6a392487d24a', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 20, 20, 'In that day the Lord will shave with a razor that is hired in the parts beyond the River, even with the king of Assyria, the head and the hair of the feet; and it shall also consume the beard.'),
  ('abed750f-8b4f-53d0-ad0c-41e784f963b7', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 21, 21, 'It shall happen in that day that a man shall keep alive a young cow, and two sheep;'),
  ('f5c3528f-46fe-55fc-aae8-f44c7a04e4b7', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 22, 22, 'and it shall happen, that because of the abundance of milk which they shall give he shall eat butter: for everyone will eat butter and honey that is left in the midst of the land.'),
  ('cade03a0-5d04-5c61-a12e-e19173aa3a9c', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 23, 23, 'It will happen in that day that every place where there were a thousand vines at a thousand silver shekels, shall be for briers and thorns.'),
  ('90463e2e-1082-5833-a509-a2b5b0ad05b5', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 24, 24, 'People will go there with arrows and with bow, because all the land will be briers and thorns.'),
  ('ee2ca981-28af-5c87-a814-61781280351c', 'cf0fb097-ffbf-5e10-a726-a3411af3b7f7', NULL, 25, 25, 'All the hills that were cultivated with the hoe, you shall not come there for fear of briers and thorns; but it shall be for the sending forth of oxen, and for the treading of sheep."'),
  ('d08cdadb-f7f0-5fd8-a847-0a8093653e8c', '845ea232-fc36-5f99-a06e-bfbc4a76a18a', NULL, 1, 1, 'Yahweh said to me, "Take a large tablet, and write on it with a man''s pen, ''For Maher Shalal Hash Baz;'''),
  ('1f21f017-1837-52e8-aa1c-58ecbbabbb9e', '845ea232-fc36-5f99-a06e-bfbc4a76a18a', NULL, 2, 2, 'and I will take for myself faithful witnesses to testify: Uriah the priest, and Zechariah the son of Jeberechiah."'),
  ('64058334-d946-52bf-aa9a-e4aa3f8610d1', '845ea232-fc36-5f99-a06e-bfbc4a76a18a', NULL, 3, 3, 'I went to the prophetess, and she conceived, and bore a son. Then Yahweh said to me, "Call his name ''Maher Shalal Hash Baz.'''),
  ('736ac191-8fb6-57fd-acf9-29c0ae00359b', '845ea232-fc36-5f99-a06e-bfbc4a76a18a', NULL, 4, 4, 'For before the child knows how to say, ''My father,'' and, ''My mother,'' the riches of Damascus and the spoil of Samaria will be carried away by the king of Assyria."'),
  ('41d2390b-787c-5ac3-af41-6ab50ec5bc9f', '845ea232-fc36-5f99-a06e-bfbc4a76a18a', NULL, 5, 5, 'Yahweh spoke to me yet again, saying,'),
  ('ececf85d-6a9b-51cd-a643-862a5e80b571', '845ea232-fc36-5f99-a06e-bfbc4a76a18a', NULL, 6, 6, '"Because this people have refused the waters of Shiloah that go softly, and rejoice in Rezin and Remaliah''s son;'),
  ('f08624ce-d6fe-5448-ad9a-633dcc952ab1', '845ea232-fc36-5f99-a06e-bfbc4a76a18a', NULL, 7, 7, 'now therefore, behold, the Lord brings upon them the mighty flood waters of the River: the king of Assyria and all his glory. It will come up over all its channels, and go over all its banks.'),
  ('05ec81ac-0df5-5b16-aa2b-5f20f79941e8', '845ea232-fc36-5f99-a06e-bfbc4a76a18a', NULL, 8, 8, 'It will sweep onward into Judah. It will overflow and pass through; it will reach even to the neck; and the stretching out of its wings will fill the breadth of your land, Immanuel.'),
  ('177e28fc-faa2-580d-aed9-7332d1726e55', '845ea232-fc36-5f99-a06e-bfbc4a76a18a', NULL, 9, 9, 'Make an uproar, you peoples, and be broken in pieces! Listen, all you from far countries: dress for battle, and be shattered! Dress for battle, and be shattered!'),
  ('43554e59-f4a0-5707-a3e3-4672af4c842b', '845ea232-fc36-5f99-a06e-bfbc4a76a18a', NULL, 10, 10, 'Take counsel together, and it will be brought to nothing; speak the word, and it will not stand: for God is with us."'),
  ('ae5938c7-296b-5bd4-a971-b4c5e008cb99', '845ea232-fc36-5f99-a06e-bfbc4a76a18a', NULL, 11, 11, 'For Yahweh spoke thus to me with a strong hand, and instructed me not to walk in the way of this people, saying,'),
  ('7c9f8ec6-f251-50b9-a327-ce4092acb6c1', '845ea232-fc36-5f99-a06e-bfbc4a76a18a', NULL, 12, 12, '"Don''t say, ''A conspiracy!'' concerning all about which this people say, ''A conspiracy!'' neither fear their threats, nor be terrorized.'),
  ('3b6accc7-148b-5c6a-a294-d3ba2a6f23c3', '845ea232-fc36-5f99-a06e-bfbc4a76a18a', NULL, 13, 13, 'Yahweh of Armies is who you must respect as holy. He is the one you must fear. He is the one you must dread.'),
  ('774dab41-4ee3-5b6c-a187-cc11657b9460', '845ea232-fc36-5f99-a06e-bfbc4a76a18a', NULL, 14, 14, 'He will be a sanctuary, but for both houses of Israel, he will be a trap and a snare for the inhabitants of Jerusalem.'),
  ('8914f906-be0e-5301-a6bf-c6e6c82ec207', '845ea232-fc36-5f99-a06e-bfbc4a76a18a', NULL, 15, 15, 'Many will stumble over it, fall, be broken, be snared, and be captured."'),
  ('8b77a2bd-b237-58d9-af12-fd38c76772b8', '845ea232-fc36-5f99-a06e-bfbc4a76a18a', NULL, 16, 16, 'Wrap up the testimony. Seal the law among my disciples.'),
  ('4eeb2c91-5020-57ec-a1e0-7e9adbb8ec8b', '845ea232-fc36-5f99-a06e-bfbc4a76a18a', NULL, 17, 17, 'I will wait for Yahweh, who hides his face from the house of Jacob, and I will look for him.'),
  ('81e3b648-029a-5952-aafc-ac4937b20795', '845ea232-fc36-5f99-a06e-bfbc4a76a18a', NULL, 18, 18, 'Behold, I and the children whom Yahweh has given me are for signs and for wonders in Israel from Yahweh of Armies, who dwells in Mount Zion.'),
  ('f4bc0427-befa-5ae5-a9bd-ee82b709df65', '845ea232-fc36-5f99-a06e-bfbc4a76a18a', NULL, 19, 19, 'When they tell you, "Consult with those who have familiar spirits and with the wizards, who chirp and who mutter:" shouldn''t a people consult with their God? Should they consult the dead on behalf of the living?'),
  ('829e727e-a1e7-575c-a8ab-1c10c260e13d', '845ea232-fc36-5f99-a06e-bfbc4a76a18a', NULL, 20, 20, 'Turn to the law and to the testimony! If they don''t speak according to this word, surely there is no morning for them.'),
  ('59029532-1f6d-507e-a913-7c2a959498bc', '845ea232-fc36-5f99-a06e-bfbc4a76a18a', NULL, 21, 21, 'They will pass through it, very distressed and hungry; and it will happen that when they are hungry, they will worry, and curse by their king and by their God. They will turn their faces upward,'),
  ('c9bb5855-b5b6-5ca7-ab26-c379806c3ce8', '845ea232-fc36-5f99-a06e-bfbc4a76a18a', NULL, 22, 22, 'and look to the earth, and see distress, darkness, and the gloom of anguish. They will be driven into thick darkness.'),
  ('4c021023-c93c-549c-ae98-55a32268fe84', '3b9c4e17-1dc1-51f8-a6db-60a6544259a1', NULL, 1, 1, 'But there shall be no more gloom for her who was in anguish. In the former time, he brought into contempt the land of Zebulun and the land of Naphtali; but in the latter time he has made it glorious, by the way of the sea, beyond the Jordan, Galilee of the nations.'),
  ('85d1ab85-3f40-58a9-a86c-5d4cc1276930', '3b9c4e17-1dc1-51f8-a6db-60a6544259a1', NULL, 2, 2, 'The people who walked in darkness have seen a great light. Those who lived in the land of the shadow of death, on them the light has shined.'),
  ('988064b7-fd0d-54fc-ae07-4743f5475202', '3b9c4e17-1dc1-51f8-a6db-60a6544259a1', NULL, 3, 3, 'You have multiplied the nation. You have increased their joy. They rejoice before you according to the joy in harvest, as men rejoice when they divide the spoil.'),
  ('bdb8d121-a507-524b-a7c3-80af8babd8cd', '3b9c4e17-1dc1-51f8-a6db-60a6544259a1', NULL, 4, 4, 'For the yoke of his burden, and the staff of his shoulder, the rod of his oppressor, you have broken as in the day of Midian.'),
  ('5e5d5044-1e16-55da-a4f0-a53dd5c0eae3', '3b9c4e17-1dc1-51f8-a6db-60a6544259a1', NULL, 5, 5, 'For all the armor of the armed man in the noisy battle, and the garments rolled in blood, will be for burning, fuel for the fire.'),
  ('e3699e20-54b7-5b84-a5b0-5f0e903a4278', '3b9c4e17-1dc1-51f8-a6db-60a6544259a1', NULL, 6, 6, 'For to us a child is born. To us a son is given; and the government will be on his shoulders. His name will be called Wonderful, Counselor, Mighty God, Everlasting Father, Prince of Peace.'),
  ('fa5645cd-9e11-5929-ab5a-17feee72f10c', '3b9c4e17-1dc1-51f8-a6db-60a6544259a1', NULL, 7, 7, 'Of the increase of his government and of peace there shall be no end, on the throne of David, and on his kingdom, to establish it, and to uphold it with justice and with righteousness from that time on, even forever. The zeal of Yahweh of Armies will perform this.'),
  ('41b42c2c-0d2e-5f03-a4af-8d1f28503820', '3b9c4e17-1dc1-51f8-a6db-60a6544259a1', NULL, 8, 8, 'The Lord sent a word into Jacob, and it falls on Israel.'),
  ('17ef3d23-fca8-5173-acd6-029840a762f8', '3b9c4e17-1dc1-51f8-a6db-60a6544259a1', NULL, 9, 9, 'All the people will know, including Ephraim and the inhabitants of Samaria, who say in pride and in arrogance of heart,'),
  ('c1e975d2-6e33-5dc3-a0f5-860abf54980b', '3b9c4e17-1dc1-51f8-a6db-60a6544259a1', NULL, 10, 10, '"The bricks have fallen, but we will build with cut stone. The sycamore fig trees have been cut down, but we will put cedars in their place."'),
  ('834e9237-c4a9-5f2e-a830-2cc3857fe4f8', '3b9c4e17-1dc1-51f8-a6db-60a6544259a1', NULL, 11, 11, 'Therefore Yahweh will set up on high against him the adversaries of Rezin, and will stir up his enemies,'),
  ('ef5ca401-e1c6-5dc7-a367-7067c2641502', '3b9c4e17-1dc1-51f8-a6db-60a6544259a1', NULL, 12, 12, 'The Syrians in front, and the Philistines behind; and they will devour Israel with open mouth. For all this, his anger is not turned away, but his hand is stretched out still.'),
  ('0495ab00-0f41-55a2-ad37-f174e708839f', '3b9c4e17-1dc1-51f8-a6db-60a6544259a1', NULL, 13, 13, 'Yet the people have not turned to him who struck them, neither have they sought Yahweh of Armies.'),
  ('97fb1bdf-ca5e-53e4-afbb-0f508fcaf2dc', '3b9c4e17-1dc1-51f8-a6db-60a6544259a1', NULL, 14, 14, 'Therefore Yahweh will cut off from Israel head and tail, palm branch and reed, in one day.'),
  ('14338fa1-12b5-54e1-a53b-694279a56a6e', '3b9c4e17-1dc1-51f8-a6db-60a6544259a1', NULL, 15, 15, 'The elder and the honorable man is the head, and the prophet who teaches lies is the tail.'),
  ('f3622221-2f98-594d-a524-a325f34915a8', '3b9c4e17-1dc1-51f8-a6db-60a6544259a1', NULL, 16, 16, 'For those who lead this people lead them astray; and those who are led by them are destroyed.'),
  ('56e3a269-3e9c-5caa-a6cb-9ba2b1c52a9e', '3b9c4e17-1dc1-51f8-a6db-60a6544259a1', NULL, 17, 17, 'Therefore the Lord will not rejoice over their young men, neither will he have compassion on their fatherless and widows; for everyone is profane and an evildoer, and every mouth speaks folly. For all this his anger is not turned away, but his hand is stretched out still.'),
  ('650b0c3f-c216-58e2-aa4b-452cb606cde3', '3b9c4e17-1dc1-51f8-a6db-60a6544259a1', NULL, 18, 18, 'For wickedness burns like a fire. It devours the briers and thorns; yes, it kindles in the thickets of the forest, and they roll upward in a column of smoke.'),
  ('83edc9eb-584d-59c6-a1bf-3b5f246a8cb6', '3b9c4e17-1dc1-51f8-a6db-60a6544259a1', NULL, 19, 19, 'Through the wrath of Yahweh of Armies, the land is burnt up; and the people are the fuel for the fire. No one spares his brother.'),
  ('860b93b5-8b8e-5601-a10c-c29b16e01b60', '3b9c4e17-1dc1-51f8-a6db-60a6544259a1', NULL, 20, 20, 'One will devour on the right hand, and be hungry; and he will eat on the left hand, and they will not be satisfied. Everyone will eat the flesh of his own arm:'),
  ('4a3b6e71-6d3a-5153-aee2-f175dc1f7bb4', '3b9c4e17-1dc1-51f8-a6db-60a6544259a1', NULL, 21, 21, 'Manasseh, Ephraim; and Ephraim, Manasseh; and they together shall be against Judah. For all this his anger is not turned away, but his hand is stretched out still.'),
  ('455db877-7a5c-51af-a1e2-3fcccbb8cbdc', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 1, 1, 'Woe to those who decree unrighteous decrees, and to the writers who write oppressive decrees;'),
  ('9587bd33-6a11-5603-a7e3-10ed55e7c514', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 2, 2, 'to deprive the needy from justice, and to rob the poor among my people of their rights, that widows may be their spoil, and that they may make the fatherless their prey!'),
  ('5c87411b-c2be-5dd0-a43b-fa1d35de6929', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 3, 3, 'What will you do in the day of visitation, and in the desolation which will come from afar? To whom will you flee for help? Where will you leave your wealth?'),
  ('81299e28-93a4-5aa0-a393-735d61a44734', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 4, 4, 'They will only bow down under the prisoners, and will fall under the slain. For all this his anger is not turned away, but his hand is stretched out still.'),
  ('b95131c6-9a89-56ed-a045-96de1e8d8c09', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 5, 5, 'Alas Assyrian, the rod of my anger, the staff in whose hand is my indignation!'),
  ('d46ee42d-02b5-521b-acc8-4a01460bb370', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 6, 6, 'I will send him against a profane nation, and against the people who anger me will I give him a command to take the spoil and to take the prey, and to tread them down like the mire of the streets.'),
  ('1eaacaea-a96e-519b-a520-c3a4a143b0ce', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 7, 7, 'However he doesn''t mean so, neither does his heart think so; but it is in his heart to destroy, and to cut off not a few nations.'),
  ('4aceee87-60ed-5d26-a790-2cf6d5c641e4', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 8, 8, 'For he says, "Aren''t all of my princes kings?'),
  ('7cbf3d6b-c4ac-5473-ad27-fcf31ee0be7e', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 9, 9, 'Isn''t Calno like Carchemish? Isn''t Hamath like Arpad? Isn''t Samaria like Damascus?"'),
  ('0862adb2-cb2c-5c51-ac54-8a00794cfb87', '16225a38-f2ec-5209-a3e8-7785a67ffe26', NULL, 10, 10, 'As my hand has found the kingdoms of the idols, whose engraved images exceeded those of Jerusalem and of Samaria;')
